COLLDATA("qenc","ur",[[146,"§پاکی\nدیکھیے: طہارت","",{}],[147,"§پتنگا\nدیکھیے: فراش","",{}],[148,"§پروانہ\nدیکھیے: فراش","",{}],[149,"§پوجاپاٹ\nدیکھیے: عبادت","",{}],[150,"§پوشیدہ حال جاننا\nدیکھیے: غیب","",{}],[151,"§پیاز=بصل\n§ت","",{}],[152,"§تابوت\nتابوت عبرانی زبان کا لفظ ہے۔ اس کو سادہ زبان میں آپ لکڑی کا صندوق کہہ سکتے ہیں۔ اس کا ذکر قرآن کریم میں دو جگہوں پر آیا ہے:\n۱- وہ تابوت جس کو بنی اسرئیل مصر سےآتے ہوےاپنے ساتھ لائے تھے اور ہمیشہ اپنے ساتھ رکھتے تھے۔ جنگ میں اس کو اپنے ساتھ لے جاتے تھے۔ اس کے ذریعےسے وہ فتح حاصل کرنے کی امید رکھتے تھے اور اس کی وجہ سے اپنے دل میں بہت سکون محسوس کرتے تھے۔ ایک جنگ میں ایسا ہوا کہ ان کے فلسطینی دشمن فتح یاب ہوگئے اور ان سے تابوت چھین کر اپنے ساتھ لے گئے۔اسی کی طرف قرآن اشارہ کرتے ہوے ایک جگہ پر کہتا ہے:﴿وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ءَايَةَ مُلۡكِهِۦٓ أَن يَأۡتِيَكُمُ ٱلتَّابُوتُ فِيهِ سَكِينَةࣱ مِّن رَّبِّكُمۡ وَبَقِيَّةࣱ مِّمَّا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَٰرُونَ تَحۡمِلُهُ ٱلۡمَلَٰٓئِكَةُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةࣰ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ﴾ [البقرة: ۲۴۸] \"ان کے نبی نے ان سے کہا: اس کے بادشاہ منتخب ہونے کی پہچان یہ ہےکہ وہ تابوت (صندوق) تمھارے پاس آجائے گا، جس میں تمھارے رب کی طرف سے تمھارے لیے دل جمعی ہے اورآل موسیٰ اورآل ہارون کی چھوڑی ہوئی یادگاریں ہیں۔ اسے فرشتے اٹھائے ہوے ہوں گے\"۔\nیہ اس وقت کا ذکر ہے، جب بنی اسرئیل نے نبی شمویل علیہ السلام سے گزارش کی کہ ہمارے لیے کوئی بادشاہ منتخب کردیں۔ تاکہ اس کے ساتھ مل کر ہم اپنے دشمن فلسطینیوں سےجنگ کریں۔ جب نبی نے ان کےلیے طالوت کو بادشاہ بنایا تووہ نبی پر اعتراض کرنے لگے۔ تب نبی نے ان کو بتایا کہ اس کی نشانیوں میں سے ایک یہ ہوگی کہ وہ تابوت تمھیں واپس دلا دے گا۔ تابوت کے بارے میں بائبل میں بہت تفصیلی بیان آیا ہے، جس سے پتا چلتا ہے کہ اس کو موسیٰ علیہ السلام نے اللہ کے حکم سے بنایا تھا، جو کیکر کی لکڑی کا تھا۔ پونے چار فٹ لمبا، سوا دو فٹ چوڑا اور اتنا ہی گہرا۔ اس پر سونے کی چادریں لگی ہوئی تھیں۔ دونوں طرف دولاٹھیاں لگی تھیں جیسے ڈولی میں لگی ہوتی ہیں تا کہ کندھے پر اٹھا کر لے جانے میں آسانی ہو۔ پھر اس کےاوپر کپڑا ڈال دیا جاتا تھا تاکہ دکھائی نہ دے۔ (دیکھیے: خروج:۲۵:۱۰)\nاس میں ہارون علیہ السلام کی لاٹھی، وہ برتن جس میں موسیٰ علیہ السلام منّ جمع کرتے تھے، جو آسمان سےاترتا تھا۔ دوتختیاں جن پر دس احکام لکھے تھے اور ایک طرف توریت کا ایک نسخہ رکھا ہوا تھا۔ اس کے اٹھانے والے لاوی نسل کے ہوتے تھے (جن میں سے موسیٰ کے والدتھے)جب کوئی جنگ ہوتی تو تابوت کو اٹھانے والے تابوت کو لےکر فوج کےآگے آگے چلتے تھے، جس سے لشکر کو بہت سکون اور دل جمعی حاصل ہوتی تھی اور زیادہ تر موقعوں پر فتح حاصل ہوجاتی تھی۔\nایک جنگ میں بنی اسرئیل شکست کہا گئے اورفلسطینی اپنے ساتھ تابوت بھی اٹھالے گئے، انھوں نے اس کو اپنے دیوتا (داجون) کے مندر میں رکھ دیاِ۔پھر وہ تابوت طالوت کے زمانے میں واپس آیا۔ جب داود علیہ السلام حکمراں بنے تو انھوں نے ایک خیمہ بنوایا اور تابوت کو اس میں رکھ دیا۔ جب سلیمان علیہ السلام نےمسجد تعمیر کرائی تو اس میں ایک مخصوص مکان پرمستقل طور پر اسے رکھ دیا گیا (دیکھئے: شمویل دوم:۶:۱ـ۱۰ وتاریخاول: ۱۵:۲۵)\nجب بابل کے بادشاہ بخت نصر نے تقریباً چھے سو قبل مسیح یہودیوں پر حملہ کیا تو اپنے ساتھ تابوت بھی لے گیا،جو یروشلم کے ساتھ برباد ہوگیا۔ کیونکہ اس کے بعد اس کا کچھ پتا نہیں چلا کہ کہا ں گیا، کچھ لوگوں کا خیال ہے کہ وہ ابھی تک ایتھوپیا میں موجود ہے۔لیکن اس کا کوئی ثبوت نہیں ملتا (دیکھیے: قاموس مقدس:صفحہ ۲۰۹،۲۱۰)\n۲-دوسری جگہ اس تابوت کا قرآن میں ذکر ہے، جس میں موسیٰ علیہ السلام کو ان کی ماں نے تابوت میں رکھ کر اللہ کے حکم سے دریا میں ڈال دیا تھا۔ کیونکہ فرعون جو مصر کا بادشاہ تھا، بنی اسرئیل کے لڑکوں کا قتل کروادیتا تھا۔ اس طرح اللہ نے موسیٰ کو بچانے کے لیے ان کی ماں کو حکم دیا کہ ایک تابوت میں موسی کو رکھ کر دریا میں ڈال دو جو بہتاہوا کنارے لگ جائے گا اور اس کو دشمن اٹھا لے گا۔ پھر وہ اسی کے گھر میں پرورش پائے گا۔ قرآن میں ہے :﴿إِذۡ أَوۡحَيۡنَآ إِلَىٰٓ أُمِّكَ مَا يُوحَىٰٓ أَنِ ٱقۡذِفِيهِ فِي ٱلتَّابُوتِ فَٱقۡذِفِيهِ فِي ٱلۡيَمِّ فَلۡيُلۡقِهِ ٱلۡيَمُّ بِٱلسَّاحِلِ يَأۡخُذۡهُ عَدُوࣱّ لِّي وَعَدُوࣱّ لَّهُۥۚ وَأَلۡقَيۡتُ عَلَيۡكَ مَحَبَّةࣰ مِّنِّي وَلِتُصۡنَعَ عَلَىٰ عَيۡنِيٓ﴾ [طه: ۳۸-۳۹] \"(اے موسی!)یاد کرو جب ہم نے تمھاری ماں کو الہام کیا جس کاذکر اب کیا جارہا ہے کہ اس کو تابوت میں رکھ کر دریا میں ڈال دے، دریا اسے کنارے پر ڈال دے گا۔اسے میرا دشمن اور اس کا دشمن اٹھا لے گا (اس کی پرورش کرے گا ) میں نے اپنی طرف سے تجھ پر شفقت ڈال دی۔ تاکہ تم میری آنکھوں کے سامنے پرورش پائے\"۔\nموسیٰ علیہ السلام اپنی ماں کے پاس کیسے پہنچے، اس کا مفصل ذکر موسیٰ میں دیکھیے۔","",{}],[153,"§تادیب\nدیکھیے: تعزیر","",{}],[154,"§تُبَّع\nتبع کا ذکرقرآن کریم میں دوبارآیا ہے:﴿أَهُمۡ خَيۡرٌ أَمۡ قَوۡمُ تُبَّعࣲ وَٱلَّذِينَ مِن قَبۡلِهِمۡ أَهۡلَكۡنَٰهُمۡۚ إِنَّهُمۡ كَانُواْ مُجۡرِمِينَ﴾ [الدخان: ۳۷] \"کیایہ لوگ بہترہیں یاتبع کی قوم کے لوگ اور جوان سے پہلے بھی تھے۔ہم نے ان سب کوہلاک کردیا۔يقیناً وہ گنہگار تھے \"۔\nدوسری جگہ سورہ ق میں آیا ہے:﴿كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحࣲ وَأَصۡحَٰبُ ٱلرَّسِّ وَثَمُودُ وَعَادࣱ وَفِرۡعَوۡنُ وَإِخۡوَٰنُ لُوطࣲ وَأَصۡحَٰبُ ٱلۡأَيۡكَةِ وَقَوۡمُ تُبَّعࣲۚ كُلࣱّ كَذَّبَ ٱلرُّسُلَ فَحَقَّ وَعِيدِ﴾ [ق: ۱۲-۱۴] \"ان سے پہلے نوح کی قوم نے\"رسّ والوں نے ثمودنےعاد نے،فرعون نے،برادران لوط نے،ایکہ والوں نے اور تبع کی قوم نے بھی تکذیب کی تھی۔سب نے نبیوں اوررسولوں کو جھٹلایا،پس میرا وعدہ عذاب ان پر صادق آگیا\"۔\nقوم تبع کاتعلق یمن کے حمیری قبیلے سے تھا،جن کا عہد حکومت ۵۰ا سال قبل مسیح تھا۔ان کے حکمرانوں کالقب تبع تھا جیسےمصر کے حکمرانوں کا لقب فرعون تھا۔دیگر علما کا خیال ہے کہ تبع ایک موحد کانام تھا، جو لوگوں کو توحید کی دعوت دیتا تھا مگر دوسری قوموں کی طرح اس کی قوم نے بھی اس کوجھٹلایا جس کی وجہ سے وہ عذاب میں گهرگئے۔ ام المومنین عائشہ ڤ کا یہی خیال ہےکہ وہ ایک نیک شخص تھا، اس لیے اس کو برابھلا مت کہو۔\nکعب احبارنامی تابعی کہتے ہیں کہ االلہ تعالیٰ نے تبع کوبرا نہیں کہا۔ بلکہ ان کی قوم کوبرا کہا۔سہل بن سعدسےمروی ایک حسن حدیث میں آیا ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «لاَ تَسُبُّوا تُبَّعًا فَإِنَّهُ کَانَ قَدْ أَسْلَمَ» \"تبع کوگالی مت دوکیونکہ وہ مسلمان ہوگیا تھا\"۔(مسند احمد: ۲۲۸۸)\nسورہ \"ق\"کی آیات سے توتبع کےرسول کا خیال پیدا ہوتا ہے۔اس لیے کہ ان آیات میں جن اقوام کا ذکرہوا ہے۔ان کی جانب انبیاے کرام مبعوث کیے گئے، جن کی انھوں نے تکذیب کی اور انھیں ٹھکرا دیا۔ان انبیاےکرام کاتذکرہ قرآن کریم اور احادیث نبویہ میں باربار واضح طور پر کیا گیا ہے۔تاہم تبع کے رسول ہونے کا واضح ثبوت کہیں نہیں ہے۔اس لیے ان کونبی نہیں تسلیم کیا جاسکتا۔ نبی اکرم صلی اللہ علیہ وسلم کا ارشادہے: «مَا أَدْرِي أَتُبَّعُ أَنَبِيًّا کَانَ أَمْ لاَ؟ وَمَا أَدْرِي أَذَا الْقَرْنَيْنِ أَنَبِيًّا کَانَ أَمْ لاَ» \"مجھے تبع کے بارے میں اس بات کا علم نہیں ہےکہ وہ نبی ہیں یا نبی نہیں اور مجھےذوالقرنین کے بارے میں اس بات کا علم نہیں ہے کہ وہ نبی ہیں یانبی نہیں ہیں\"۔ (امام حاکم نے اس حدیث کی سند کو صحیح کہاہے، دیکھیے: المستدرک علی الصحیحین )","",{}],[155,"§تبوک\nتبوک ایک شہر کا نام ہے۔ جو مدینہ منورہ کے شمال میں۷۸۰کیلو میٹر کے فاصلے پر واقع ہے۔یہاں کا بادشاہ ہرقل نصرانی تھا۔اس کو اسلام کی اشاعت ناگوارتھی۔ وہ صرف اپنے نصرانی مذہب ہی کو پھیلتےہوے دیکھناچاہتا تھا اور اسلام کونصرانی مذہب کے لیے خطرہ سمجھتا تھا۔اس لیے اس نے ایک لاکھ کی فوج تیار کی اور فوج کو مدینہ منورہ کی طرف بڑھنے کا حکم دیا۔جب اس کی خبر نبی اکرم صلی اللہ علیہ وسلم کو ملی تو آپ نے بھی مسلمانوں کوتیار رہنے اور تبوک کی طرف بڑھنے کا حکم دیا۔ وہ بڑا مشکل وقت تھا۔ جون، جولائی کامہیناایک تواس میں گرم ہوائیں چلتی ہیں،گهرسےباہرنکلنامشکل ہوتاہے۔دوسرےاسی موسم میں کھجوریں بھی پکنےلگتی ہیں۔ ایسے وقت میں مسلمانوں کو جنگ پر نکلنے کا حکم دیا جاتا ہے۔قرآن مجید نے بھی اس کو مشکل وقت بتایا ہے:﴿لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِيِّ وَٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ ٱلَّذِينَ ٱتَّبَعُوهُ فِي سَاعَةِ ٱلۡعُسۡرَةِ مِنۢ بَعۡدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقࣲ مِّنۡهُمۡ﴾ [التوبة: ۱۱۷] \"اللہ نے نبی اور ان مہاجرین وانصار پر مہربانی فرمائی، جنھوں نے مشکل وقت میں نبی کا ساتھ دیا۔گرچہ ان میں سے ایک گروہ کا دل تزلزل کی طرف جھک جانے کے قریب تھا\"۔\nلیکن مسلمان اللہ کا نام لےکر نکل پڑتے ہیں۔ اگرچہ ان کے پاس جنگ کا سامان نہیں ہے۔ کھانے کے لیے بھی صرف کچھ کھجوروں کے سوا کچھ نہیں ہے۔حدیثوں میں آتا ہے کہ دو آدمی مل کر ایک کھجور کھاتے تھے۔لیکن ان کا دل اللہ اور رسول کی محبت سے بھرا ہوا تھا۔ان کو دنیا کا کوئی غم نہ تھا۔ وہ تو اللہ کی راہ میں اپنی زندگی کو قربان کردینے کو بڑی خوش قسمتی سمجھتے تھے، اس لیے تیس ہزار کا لشکر لے کر نبی اکرم صلی اللہ علیہ وسلم مدینہ سے نکلے۔ آج کی طرح کوئی سڑک نہیں تھی۔دشوار گزار راستوں کو روندتے ہوے جب آپ تبوک پہنچے توہرقل کا دل گهبرانے لگا۔اس پر مسلمانوں کااتنا رعب طاری ہو گیا کہ اس نے جزیہ دینے پرصلح کرلی۔ راستے میں آنے والی بستیوں کے دیگر سردار بھی جزیہ دینے پر راضی ہوگئے، جس کے سبب جنگ کی ضرورت ہی نہیں پڑی۔ بیس دن تک نبی اکرم صلی اللہ علیہ وسلم تبوک میں رہ کر واپس آگئے۔\nاس جنگ میں منافقوں نے بڑی بزدلی دکهائی۔ نہ صرف یہ کہ وہ جنگ میں خود شامل نہیں ہوے، بلکہ انھوں نےسچے مسلمانوں کو بھی جنگ پرنہ جانے کے لیے اکسایا۔ لیکن وہ ناکام رہے۔ جب نبی اکرم صلی اللہ علیہ وسلم تبوک سےواپس آگئے تو وہ جنگ پر نہ جانے کا اپنا بہانا پیش کرنے کے لیے آنے لگے۔ آپ نے ان کے بہانے قبول کرلئے، جس پر قرآن مجید کی یہ آیت نازل ہوئی:﴿عَفَا ٱللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمۡ حَتَّىٰ يَتَبَيَّنَ لَكَ ٱلَّذِينَ صَدَقُواْ وَتَعۡلَمَ ٱلۡكَٰذِبِينَ﴾ [التوبة: ۴۳] \"اللہ تمھیں معاف کرے، تم نے انھیں (پیچھےرہ جانے کی) اجازت کیوں دے دی،یہاں تک ان میں سے سچے اور جھوٹے سامنے آجاتے\"۔\nاللہ تعالی نےابتدا میں تین پکے سچے صحابہ کی توبہ قبول نہیں کی، جن کے نام یہ ہیں:کعب بن مالک، مرارہ بن ربیع اور ہلال بن امیہ رضی اللہ عنہم۔لیکن جب وہ پورے دل و جان سے اللہ کی طرف مائل ہوگئے تو اللہ نے ان کی توبہ قبول کر لی،جس کا بیان قرآن میں اس طرح آیا ہے: ﴿وَعَلَى ٱلثَّلَٰثَةِ ٱلَّذِينَ خُلِّفُواْ حَتَّىٰٓ إِذَا ضَاقَتۡ عَلَيۡهِمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ وَضَاقَتۡ عَلَيۡهِمۡ أَنفُسُهُمۡ وَظَنُّوٓاْ أَن لَّا مَلۡجَأَ مِنَ ٱللَّهِ إِلَّآ إِلَيۡهِ ثُمَّ تَابَ عَلَيۡهِمۡ لِيَتُوبُوٓاْۚ إِنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ﴾ [التوبة: ۱۱۸] \"اللہ ان تینوں پر مہربان ہوگیا، جو پیچھےچھوڑ دیے گئے تھے یہاں تک کہ جب زمین کشادہ ہوتے ہوےبھی ان پر تنگ ہوگئی اور ان کی جانیں ان پر مشکل ہو گئیں اور انهون نے سمجھ لیاکہ اللہ کی پکڑ سے بچنے کے لیے کہیں اور پناہ نہیں مل سکتی، مل سکتی ہے تو بس اسی کے یہاں تو وہ اپنی مہربانی سے ان کی طرف متوجہ ہوا تاکہ وہ بھی اس کی طرف پلٹ جائیں۔ بےشک اللہ بڑا توبہ قبول کرنے والا ہے اور رحم کرنے والا ہے\"۔ (اس کی تفصیل کے لیے دیکھیے:تین آدمی جو پیچھے چھوڑ دیے گئے)","",{}],[156,"§تجارت\nتجارت کو اسلامی نظام زندگی میں انتہائی اہم مقام حا صل ہے۔اسےمعاشی نظام کی ریڑھ کی ہڈی مانا جاتا ہے۔ اسلامی تعلیمات میں تجارت پر جو زور دیا گیا ہے اس کی اہمیت کا اندازہ اس بات سے لگایا جاسکتا ہے کہ ایک جگہ پر اسےجہاد کے مماثل بتا یا گیا ہے:﴿إِنَّ رَبَّكَ يَعۡلَمُ أَنَّكَ تَقُومُ أَدۡنَىٰ مِن ثُلُثَيِ ٱلَّيۡلِ وَنِصۡفَهُۥ وَثُلُثَهُۥ وَطَآئِفَةࣱ مِّنَ ٱلَّذِينَ مَعَكَۚ وَٱللَّهُ يُقَدِّرُ ٱلَّيۡلَ وَٱلنَّهَارَۚ عَلِمَ أَن لَّن تُحۡصُوهُ فَتَابَ عَلَيۡكُمۡۖ فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنَ ٱلۡقُرۡءَانِۚ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرۡضَىٰ وَءَاخَرُونَ يَضۡرِبُونَ فِي ٱلۡأَرۡضِ يَبۡتَغُونَ مِن فَضۡلِ ٱللَّهِ وَءَاخَرُونَ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنۡهُۚ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَقۡرِضُواْ ٱللَّهَ قَرۡضًا حَسَنࣰ اۚ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنۡ خَيۡرࣲ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَيۡرࣰ ا وَأَعۡظَمَ أَجۡرࣰ اۚ وَٱسۡتَغۡفِرُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمُۢ﴾ [المزمل: ۲۰] \"اسے معلوم ہے کہ تم میں سے کچھ لوگ بیمار ہوں گے اور کچھ لوگ تجارت کی غرض سے زمین میں سفر کریں گے اور کچھ اللہ کے راستے میں جہاد کریں گے\"۔\nایک صحیح حدیث میں آیا ہے: سب سے عمدہ رزق (روزی) وہ ہے جو آدمی خود اپنی کدوکاوش سے حاصل کرے۔ (مسند احمد: ۴۲:۶)\nدوسری طرف ان لوگوں کی سخت مذمت کی گئی ہے، جو مانگ کر اپنی روزی حاصل کرتے ہیں۔ خواہ وہ سڑکوں پر مانگنےوالے ہوں یا مزاروں کے مجاور یا اپنے آپ کو اس دھوکے میں رکھتے ہوں کہ ہم تو اللہ پر توکل کرنے والے ہیں۔ ایسے لوگ قیامت کے دن اپنے چہروں کو اس طرح نوچیں گے کہ سارا گوشت نکل جائے گا۔\nاسلامی تعلیمات میں اس بات کی بہت تاکیدکی گئی ہے کہ آدمی کو چاہیے کہ وہ صحیح اور درست ذریعے سے مال حاصل کرے اور غلط راستے کو نہ اپنائے۔ بلکہ وہ یقین بھی رکھے کہ جو اس کے نصیب میں لکھا ہوا ہے وہ اسے مل کررہے گا۔ (دیکھیے: سنن ابن ماجہ: ۲۱۴۲ والمستدرک علی الصحیحین للحاکم: ۳:۲)\nاسلامی تجارت کے اہم ترین اصولوں میں سے ایک یہ بھی ہے کہ پیساکیسے کمایا جائے اور کہاں خرچ کیا جائے۔ کمائی کاذریعہ بھی صحیح ہو اور وہ متعین کیے گئے ضابطے کے مطابق ہو۔اگر ایسا نہیں ہے تو وہ تجارت حرام ہوگی۔اسی طرح ایک مسلمان کا خاص عمل یا اہم فریضہ ہےکہ وہ مال کو صحیح جگہ پرخرچ کرے، جو اسلامی تعلیمات کےمطابق ہو۔اگر ایسا نہیں کیا تو قیامت کے روزاس کو خرچ کا بھی حساب دینا پڑے گا۔\nیوں تو اسلام نے واضح طور پر ہر طرح کی تجارت کو جائز بتایا ہے تاہم کچھ تجارتوں کو حرام قرار دیا ہے۔ کیونکہ انسانی معاشرے کے لیے وہ نقصان دہ ہیں۔ وہ تجارتیں جن کے ذریعے ایک مال دار تو زر دار بن جاتا ہے، لیکن ایک غریب مزید غربت زدہ ہونےلگتاہے۔ ایسی تجارتوں کو اسلام نے حرام قرار دیا ہے۔ ان نقصان دہ تجارتوں کو دو حصوں میں تقسیم کیا جاسکتا ہے:\nایک وہ تجارت جو سودی نظام پر کی جائے۔اس طرح کی تجارت دین اسلام میں حرام ہے۔ خواہ وہ کسی بھی طورپر کی جائے۔اسی لیے اسلام مخالفوں نے جب یہ کہا : [آیت] وہ کہتے ہیں کہ تجارت بھی تو سود ہی جیسی ہے۔توقران میں اس کی تردید آ ئی: ﴿ٱلَّذِينَ يَأۡكُلُونَ ٱلرِّبَوٰاْ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِي يَتَخَبَّطُهُ ٱلشَّيۡطَٰنُ مِنَ ٱلۡمَسِّۚ ذَٰلِكَ بِأَنَّهُمۡ قَالُوٓاْ إِنَّمَا ٱلۡبَيۡعُ مِثۡلُ ٱلرِّبَوٰاْۗ وَأَحَلَّ ٱللَّهُ ٱلۡبَيۡعَ وَحَرَّمَ ٱلرِّبَوٰاْۚ فَمَن جَآءَهُۥ مَوۡعِظَةࣱ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمۡرُهُۥٓ إِلَى ٱللَّهِۖ وَمَنۡ عَادَ فَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ﴾ [البقرة: ۲۷۵] \" اللہ نے توتجارت کو حلال ٹھہرادیا ہے اورسود کو حرام اور جو شخص اپنے پاس آئی ہوئی اللہ تعالی کی نصیحت سن کررک گیا اس کے لیے وہ ہے جو گزر گیا اور اس کا معاملہ اللہ کی طرف ہے اور جو پھر دوبارہ (سود کی طرف) لوٹا وہ جہنمی ہے۔ ایسے لوگ ہمیشہ ہی اس میں رہیں گے\"۔\nدوسری وہ تجارتیں، جن سے عوام کو نقصان ہوتا ہو۔اس طرح کی تجارت بھی اسلام میں بالکل حرام ہے۔ درحقیقت عرب کے بے دین ہر طرح کی تجارت کو جائز سمجھتے تھے۔ خواہ اس سے عوام میں کتنا ہی بگاڑ پیدا ہو۔ ان کو صرف اپنی بھلائی در کار تھی۔ عوام کی نہیں۔ تجارت کے متعلق اسلامی تعلیمات کے ماہرین کی رائے ہے کہ معاشی نظام پر ہی معاشرے کی تعمیر وترقی ہوتی ہے۔ اس لیےہر وہ تجارت جو عوام کےلیے نقصان دہ ہو،حرام ہے۔ جیسے: سود، جس کا ذکر اوپر ہوچکا ہے۔ (مفصل معلومات کے لیے دیکھیں: سود)\nتجارت میں ہونے والی بعض ایسی چیزیں جن کو اسلام نے حرام قرار دیاہے،وہ درج ذیل ہیں۔\n§(۱)ناپ تول میں کمی کرنا:\nپرانے زمانے سے ناپ تول میں کمی کی عادت چلی آرہی تھی۔عربوں میں بھی یہ بیماری تھی۔ قرآن ایسے لوگوں کی مذمت کرتے ہوے اس دن سے ڈراتا ہے، جب انسان اپنے رب کے سامنے حساب دینے کے لیے کھڑا ہوگا: ﴿وَيۡلࣱ لِّلۡمُطَفِّفِينَ ٱلَّذِينَ إِذَا ٱكۡتَالُواْ عَلَى ٱلنَّاسِ يَسۡتَوۡفُونَ وَإِذَا كَالُوهُمۡ أَو وَّزَنُوهُمۡ يُخۡسِرُونَ أَلَا يَظُنُّ أُوْلَٰٓئِكَ أَنَّهُم مَّبۡعُوثُونَ لِيَوۡمٍ عَظِيمࣲ يَوۡمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلۡعَٰلَمِينَ﴾ [المطففین: ۱-۶] \"تباہی وبربادی ہے ناپ تول میں کمی کرنے والوں کے لیے،جو ناپ کر لوگوں سےپورا پورالیتےہیں، لیکن جب انھیں ناپ کر یا تول کردیتے ہیں تو گھٹا دیتے ہیں، کیا یہ لوگ سمجھتے نہیں کہ انھیں دوبارہ اٹھایا جائے گا؟ ایک بڑے دن کے لیے، جس دن لوگ ساری کائنات کے رب کے حضور اپنے اعمال کا حساب دینے کے لیے کھڑے ہوں گے\"۔\n§(۲)دھوکے والی تجارت کی حرمت:\nابوہریرہ رضی اللہ عنہ سےمروی ہے کہ\"نبی اکرم صلی اللہ علیہ وسلم نےدهوکے والی تجارت سےمنع فرمایا ہے\"۔ (صحیح مسلم: ۱۵۱۳) یہ حدیث تجارت کے اصول کو متعین کرتی ہے۔پس جس تجارت میں بھی دھوکے کا کوئی پہلو پایا جائے گا وہ اسلامی تعلیمات کےمطابق حرام ہوگی۔ جیسے: پھل کی ٹوکری میں اوپر اچھے پھل رکھ دیے جائیں اور نیچے خراب۔ اوپراچھا اناج رکھ دیا جائے اور نیچے خراب۔ایسی تجارت جس میں خریدی جانے والی چیزیں مجہول ہوں۔ان کی مقدار کا صحیح پتا نہ ہو اور اگر وہ گنتی والی ہوں تو صحیح گنتی کا پتا نہ ہو۔ اسی طرح ایسی چیزوں کی تجارت جو اب تک تیار نہ ہوئی ہوں یا جس کو فوری طور پر خریدنے والے کےحوالے کرنا ناممکن ہو۔یہ سب تجارتیں حرام ہیں۔ کیونکہ ان میں دھوکا پایاجاتا ہے۔ فروخت کرنے والا جو چیز دےرہا ہے،خرید نے والا اس کو صحیح نہیں سمجھ رہا ہے۔بیچنےاور خریدنےوالے جب تک کسی چیزپر پوری طرح اطمینان نہیں کرلیتے،اس وقت تک وہ دھوکے والی تجارت ہوگی اور جب اطمینان ہوجائے تو پھرصحیح تجارت ہوگی۔\n(۳) تجارت میں کوئی ایسی شرط نہ لگائی جائے جس سے تجارت کا مقصدہی فوت ہوجائے۔\nاگرکسی نےایسی شرط لگائی توتجارت درست ہوگی،لیکن وہ شرط نافذ نہیں ہوگی۔جیسے: زمین فروخت کرنےوالا زمین لینےوالےپر یہ شرط لگادے کہ اس زمین پر کوئی مکان نہیں بنایا جاسکتا یا نکاح کے وقت یہ شرط لگادی جائے کہ دو بچوں سے زیادہ بچے ییدا نہیں ہونے چاہییں۔ اس طرح کی باتوں میں معاملہ ٹھیک ہوگا، لیکن شرط درست نہیں ہوگی۔\nام المومنین عائشہڤکہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نےمنبرپرکھڑے ہو کرفرمایا: «مَا بَالُ أَقْوَامٍ يَشْتَرِطُونَ شُرُوطًا لَيْسَ فِي کِتَابِ اللَّهِ؟ مَنْ اشْتَرَطَ شَرْطًا لَيْسَ فِي کِتَابِ اللَّهِ فَلَيْسَ لَهُ وَإِنْ اشْتَرَطَ مِائَةَ مَرَّةٍ». (صحیح البخاری: ۴۵۶، و صحیح مسلم: ۱۵۰۴) \"لوگوں کا کیا معاملہ ہے؟ وہ ایسی شرطیں لگاتے ہیں جو اللہ کی کتاب یعنی شریعت میں نہیں ہیں۔ اگر کوئی ایسی شرط لگاتا ہے جو اللہ کی کتاب میں نہیں ہے، تو وہ شرط باطل ہے۔ خواہ وہ سو شرطیں کیوں نہ لگا لے\"۔\n(۴)اسلام میں ہر ایسی تجارت حرام ہے، جس میں ابھی خریدنے اوربیچنےوالےکے درمیان بات چیت چل رہی ہو تو پہلے خریدار کےدست بردار ہونے سے پہلے ہی دوسرا اس میں ٹپک پڑے۔\nعقبہ بن عامر رضی اللہ عنہ کہتےہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «الْمُؤْمِنُ أَخُو الْمُؤْمِنِ فَلا يَحِلُّ لِلْمُؤْمِنِ أَنْ يَبْتَاعَ عَلَی بَيْعِ أَخِيهِ وَلا يَخْطُبَ عَلَی خِطْبَةِ أَخِيهِ حَتَّی يَذَرَ». (صحیح البخاری: ۲۱۲۹، صحیح مسلم: ۵۶/۱۴۱۴) \"ایک مومن دوسرے مومن کا بھائی ہے، لہٰذا کسی مومن کے لیے جائز نہیں ہے کہ وہ اپنے بھائی کی بیع پر بیع کرے اور نہ اپنے بھائی کے پیغام پر پیغام دے یہاں تک کہ وہ چھوڑ دے\"۔\n§بعض حرام اورممنوع چیزوں کی تجارت کاذکر:\nشراب، مردارجانور، سوراوربتوں کی تجارت حرام اورناجائزہے۔\nجابربن عبداللہ رضی اللہ عنہما سےمروی ہےکہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے فتح مکہ کے سال کہتے سنا: «إِنَّ اللَّهَ وَرَسُولَهُ حَرَّمَ بَيْعَ الْخَمْرِ وَالْمَيْتَةِ وَالْخِنْزِيرِ وَالأَصْنَامِ».(صحیح البخاری: ۲۲۳۶، صحیح مسلم: ۱۵۸۱) \"اللہ اور اس کے رسول نے شراب،مرا ہوا جانور، سور اور بتوں کی تجارت کوحرام قرار دیا ہے\"۔\nمرے ہوےحلال جانور کے چمڑے کی تجارت درست ہے، جب اس کو دباغت دےدی جائے۔\nعبداللہ بن عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ایک مری ہوئی بکری کے پاس سے گزرےتوفرمایا: «هَلاَّ اسْتَمْتَعْتُمْ بِإِهَابِهَا». قَالُوا: إِنَّهَا مَيِّتَةٌ. قَالَ: «إِنَّمَا حَرُمَ أَکْلُهَا». (صحیح البخاری:۵۵۳۱) \"تم لوگوں نے اس کے چمڑے سے استفادہ کیوں نہیں کیا؟ لوگوں نے عرض کیا: یہ تو مردہ ہے۔ آپ نے فرمایا: اس کا کھانا حرام ہے(نہ کہ چمڑا)\"۔\nکتے اور خون کی تجارت حرام ہے۔ (دیکھیے: صحیح البخاری:۲۲۳۸)\nزنا کاری کی کمائی اور کہانت (پیشین گوئی) کی کمائی حرام ہے۔(دیکھیے: صحیح البخاری:۲۲۸۲ وصحیح مسلم:۱۵۶۷)\nآزاد شخص کو فروخت کردینا حرام ہے۔ابوہریرہ رضی اللہ عنہ سے مروی ایک صحیح حدیث میں آیا ہے کہ نبی اکرم صلی اللہ علیہ وسلم نےفرمایا: «قَالَ اللَّهُ: ثَلاَثَةٌ أَنَا خَصْمُهُمْ يَوْمَ الْقِيَامَةِ: رَجُلٌ أَعْطَی بِی ثُمَّ غَدَرَ، وَرَجُلٌ بَاعَ حُرًّا فَأَکَلَ ثَمَنَهُ، وَرَجُلٌ اسْتَأْجَرَ أَجِيرًا فَاسْتَوْفَی مِنْهُ، وَلَمْ يُعْطِ أَجْرَهُ». (صحیح البخاری: ۲۲۲۷) \"اللہ کا کہنا ہےکہ تین طرح کے لوگوں کا قیامت کے دن میں دشمن بنوں گا: ایک وہ جس نے میرے نام سے کوئی سمجھوتا (صلح )کیا پھر توڑ دیا، دوسرا وہ جس نے کسی آزاد شخص کو پکڑ کر فروخت کردیا اور اس کی قیمت کھالی اور تیسرا وہ شخص جس نے مزدور سے تو پورا کام لیا لیکن اس کی مزدوری نہیں دی\"۔\nضرورت سےزیادہ پانی کوفروخت کرنا حرام ہے۔ (دیکھیے: صحیح البخاری: ۲۳۵۴ و صحیح مسلم: ۱۵۶۶)\nسانڈ کا نطفہ بیچناحرام ہے۔ گائےبیل وغیرہ کی جفتی کرانے کی اجرت لینی حرام ہے۔\nپھل کودرخت پر کچا ہی بیچ دینا حرام ہے۔ (دیکھیے: صحیح البخاری: ۲۳۸۱ وصحیح مسلم:۱۵۳۶)\nایک دوسری حدیث میں اس کو \"کالا\" کہا گیا ہے۔ مطلب یہ ہے کہ پھل اس وقت تک نہ بیچاجائے جب تک وہ استعمال کے لائق نہ ہو جائے۔\nچونکہ عرب دنیا میں اکثر کھجور کےباغات میں درخت پرلگے پھل کی تجارت ہوتی تھی، اس لیے کھجوروں کو \"کالا\" کہا گیا۔ کیوں کہ کھجوریں بڑی ہوکررنگ بدلنےلگتی ہیں توان کے رنگ کالے اورپیلے نظرآتے ہیں۔اکثراس مرحلے پر پہنچ کرپھل ہوا اوربارش سے نہیں گرتے۔اسی پرقیاس کرکے آم وغیرہ کے باغات میں پھلوں کی تجارت کرنی چاہیے۔\nاس کے علاوہ اور بھی ایسی تجارتیں ہیں،جن کو اسلام میں حرام بتایا گیا ہے۔ کیونکہ وہ انسانی معاشرے کے لیے نقصان دہ ہیں۔ تاہم اختصار کی وجہ سے یہاں صرف ان اہم تجارتوں کا ذکر کیا گیا ہے، جو حرام ہیں۔ باقی وہ تجارت جو خرید نےاور فروخت کرنے والے کے درمیان باہم رضامندی سے ہوگی، جائز مانی جائے گی۔جیسا کہ قرآن پاک میں آیا ہے: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضࣲ مِّنكُمۡۚ وَلَا﴾ [النساء: ۲۹] \"اے ایمان والو!اپنے آپس کے مال ناجائز طریقوں سے مت کھاؤ۔ مگر یہ کہ تمھاری آپس کی رضامندی سے خریدو فروخت کے ذریعے ہو\"۔\nیہ اسلامی تجارت کے قوانین میں سب سے اہم ترین قانون ہے۔ اس لیے ہر وہ تجارت حرام ہوگی، جس میں فروخت کرنے اور خرید نے والے باہم رضا مندنہ ہوں۔","",{}],[157,"§تجسس\nتجسس کا مطلب جاسوسی ہے۔یہ دو قسم کی ہوتی ہے: ایک وہ جو معاشرے میں ایک دوسرے کے خلاف کی جاتی ہے۔اس کا مقصد ایک دوسرے کی برائی کرنا، کمزوری اور ہر قسم کی معلومات حاصل کرنے کی کوشش کرنا اور اسے معاشرےمیں پھیلانا یا اس سے کوئی غلط فائدہ حاصل کرنا۔ یہ حقیقت میں شخصی آزادی اور خودمختاری کے خلاف ہے۔ اس لیےقرآن کریم نے اس کی سخت مذمت کی ہے: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱجۡتَنِبُواْ كَثِيرࣰ ا مِّنَ ٱلظَّنِّ إِنَّ بَعۡضَ ٱلظَّنِّ إِثۡمࣱۖ وَلَا تَجَسَّسُواْ وَلَا يَغۡتَب بَّعۡضُكُم بَعۡضًاۚ أَيُحِبُّ أَحَدُكُمۡ أَن يَأۡكُلَ لَحۡمَ أَخِيهِ مَيۡتࣰ ا فَكَرِهۡتُمُوهُۚ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ تَوَّابࣱ رَّحِيمࣱ‏﴾ [الحجرات: ۱۲] \"اے ایمان والو! بہت بد گمانیوں سے بچو، کیونکہ ان میں سے کچھے بدگمانیاں گناہ ہیں اور جاسوسی (تجسس) میں نہ پڑو اور نہ تم میں سے کوئی کسی کی غیبت کرے۔کیا تم میں سے کوئی اس کو پسند کرےگا کہ وہ اپنے مرے ہوئے بھائی کا گوشت کھائے؟ وہ تو تمھیں ناپسند ہوگا ہی۔ تم اللہ سے ڈرو۔ بے شک اللہ تواب ورحیم( بہت توبہ قبول کرنے والا اور بہت بڑا مہربان) ہے\"۔\nدوسری قسم کی جاسوسی وہ ہے، جو کسی مسلم ملک کے خلاف کی جائے، جو بہت بڑا جرم ہے، جس کی سزا قتل بھی ہوسکتی ہے۔ صحیح حدیث میں آتا ہے:\n۱- سلمہ بن الاکوع رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم ہوازن نامی جنگ میں تھے کہ آپ کے پاس مشرکوں کی طرف سے ایک جاسوس آیا،صحابۂ کرام کےساتھ بیٹھ کربات کی پھر واپس لوٹ گیاتونبی اکرم صلی اللہ علیہ وسلم نے صحابہ کوحکم دیا: «اطْلُبُوهُ وَاقْتُلُوهُ» فَقَتَلَهُ فَنَفَّلَهُ سَلَبَهُ». (صحیح البخاری: ۳۰۵۱، صحیح مسلم: ۴۵/۱۷۵۴) \"جاؤ اس کو ڈھونڈ لاؤ اور قتل کردو\"، پس آپ نے اس کو قتل کردیا اور قتل کرنے والے کو اس کاسامان دے دیا۔\n۲- عبیداللہ بن ابی رافع کہتے ہیں کہ میں نے علی رضی اللہ عنہ سےکہتےسنا: «بَعَثَنِي رَسُولُ اللَّهِ صلی اللہ علیہ وسلم أَنَا وَالزُّبَيْرَ وَالْمِقْدَادَ بْنَ الأَسْوَدِ، قَالَ: انْطَلِقُوا حَتَّی تَأْتُوا رَوْضَةَ خَاخٍ فَإِنَّ بِهَا ظَعِينَةً وَمَعَهَا کِتَابٌ فَخُذُوهُ مِنْهَا، فَانْطَلَقْنَا تَعَادَی بِنَا خَيْلُنَا حَتَّی انْتَهَيْنَا إِلَی الرَّوْضَةِ، فَإِذَا نَحْنُ بِالظَّعِينَةِ، فَقُلْنَا: أَخْرِجِي الْکِتَابَ، فَقَالَتْ: مَا مَعِي مِنْ کِتَابٍ، فَقُلْنَا: لَتُخْرِجِنَّ الْکِتَابَ أَوْ لَنُلْقِيَنَّ الثِّيَابَ، فَأَخْرَجَتْهُ مِنْ عِقَاصِهَا، فَأَتَيْنَا بِهِ رَسُولَ اللَّهِ صلی اللہ علیہ وسلم فَإِذَا فِيهِ مِنْ حَاطِبِ بْنِ أَبِي بَلْتَعَةَ إِلَی أُنَاسٍ مِنْ الْمُشْرِکِينَ مِنْ أَهْلِ مَکَّةَ يُخْبِرُهُمْ بِبَعْضِ أَمْرِ رَسُولِ اللَّهِ صلی اللہ علیہ وسلم، فَقَالَ رَسُولُ اللَّهِ صلی اللہ علیہ وسلم : يَا حَاطِبُ! مَا هَذَا؟ قَالَ: يَا رَسُولَ اللَّهِ لا تَعْجَلْ عَلَيَّ، إِنِّي کُنْتُ امْرَأً مُلْصَقًا فِي قُرَيْشٍ وَلَمْ أَکُنْ مِنْ أَنْفُسِهَا وَکَانَ مَنْ مَعَکَ مِنْ الْمُهَاجِرِينَ لَهُمْ قَرَابَاتٌ بِمَکَّةَ يَحْمُونَ بِهَا أَهْلِيهِمْ وَأَمْوَالَهُمْ، فَأَحْبَبْتُ إِذْ فَاتَنِي ذَلِکَ مِنْ النَّسَبِ فِيهِمْ أَنْ أَتَّخِذَ عِنْدَهُمْ يَدًا يَحْمُونَ بِهَا قَرَابَتِي، وَمَا فَعَلْتُ کُفْرًا وَلاَ ارْتِدَادًا وَلاَ رِضًا بِالْکُفْرِ بَعْدَ الإِسْلاَمِ، فَقَالَ رَسُولُ اللَّهِ صلی اللہ علیہ وسلم : لَقَدْ صَدَقَکُمْ، قَالَ عُمَرُ: يَارَسُولَ اللَّهِ دَعْنِي أَضْرِبْ عُنُقَ هَذَا الْمُنَافِقِ، قَالَ: إِنَّهُ قَدْ شَهِدَ بَدْرًا وَمَا يُدْرِيکَ لَعَلَّ اللَّهَ أَنْ يَکُونَ قَدْ اطَّلَعَ عَلَی أَهْلِ بَدْرٍ، فَقَالَ: اعْمَلُوا مَا شِئْتُمْ فَقَدْ غَفَرْتُ لَکُمْ». (صحیح البخاری: ۳۰۰۷، صحیح مسلم: ۲۴۹۴) \"نبی اکرم صلی اللہ علیہ وسلم نے مجھ کو اور زبیر ومقداد بن اسود کو بھیجا،فرمایا: جاؤ روضۂ خاخ میں ایک عورت ملے گی، اس کے پاس ایک خط ہے۔ اس کو اس سے لے لو۔ ہم نے سوار عورت کو وہاں پالیا۔ ہم نے کہا: خط نکال! اس نے کہا: میرے پاس کوئی خط نہیں ہے، ہم نے کہا: خط نکال ورنہ ہم تجھے ننگی کردیں گے۔ تب اس نے جوڑے سے وہ خط نکالا، ہم اس کو اللہ کے رسول کے پاس لائے، وہ خط حاطب بن ابی بلتعہ رضی اللہ عنہ کی طرف سے چند کفار قریش کے نام تھا۔ اس میں کفار کو رسول اللہ صلی اللہ علیہ وسلم کے بعض (فوجی) معاملات کی خبر دی گئی تھی،اللہ کے رسول نےفرمایا:یہ کیا ہے حاطب! عرض کیا: اے اللہ کے رسول! میں قریش کے باہر کا آدمی ہوں۔ خودان کے قبیلے سے نہیں ہوں۔ جب کہ آپ کے مہاجر اصحاب خود قریش کے لوگ ہیں۔ ان کی وہاں قرابت داریاں ہیں،جس کی وجہ سے وہ لوگ ان مہاجرین کے اہل وعیال واموال کی حفاظت کرتے ہیں، تو جب میری ان سے کوئی رشتہ داری نہیں، تو میں نے چاہا کہ ان پر میرا احسان ہوجائے،جس کی وجہ سے وہ لوگ میرے قرابت داروں کی حفاظت کریں گے۔ میں نے یہ کام کفر کی وجہ سے نہیں کیا نہ ارتداد کی بناپر کیا ہے اور نہ اسلام کے بعد کفر سے خوش ہوکر کیا ہے۔اس پر رسول اللہ( صلی اللہ علیہ وسلم ) نے فرمایا: اس نے سچ کہا۔ لیکن عمر نے پھر بھی کہا: چھوڑیے میں اس منافق کی گردن اڑا دوں! آپ نے فرمایا: یہ بدری صحابی ہے؟ تجھے کیا معلوم کہ اللہ تعالیٰ نے بدروالوں سے فرمادیا ہے: جاؤ جو چاہو وہ کرو میں نے تم سب کو معاف کردیا ہے۔ تب اس پر یہ آیت نازل ہوئی: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ عَدُوِّي وَعَدُوَّكُمۡ أَوۡلِيَآءَ تُلۡقُونَ إِلَيۡهِم بِٱلۡمَوَدَّةِ وَقَدۡ كَفَرُواْ بِمَا جَآءَكُم مِّنَ ٱلۡحَقِّ يُخۡرِجُونَ ٱلرَّسُولَ وَإِيَّاكُمۡ أَن تُؤۡمِنُواْ بِٱللَّهِ رَبِّكُمۡ إِن كُنتُمۡ خَرَجۡتُمۡ جِهَٰدࣰ ا فِي سَبِيلِي وَٱبۡتِغَآءَ مَرۡضَاتِيۚ تُسِرُّونَ إِلَيۡهِم بِٱلۡمَوَدَّةِ وَأَنَا۠ أَعۡلَمُ بِمَآ أَخۡفَيۡتُمۡ وَمَآ أَعۡلَنتُمۡۚ وَمَن يَفۡعَلۡهُ مِنكُمۡ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ﴾ [الممتحنة: ۱] \"اے وہ لوگو جو ایمان لائے ہو! میرے اور (خود) اپنے دشمنوں کو اپنا دوست نہ بناؤ تم دوستی سے ان کی طرف پیغام بھیجتے ہواور وہ اس حق کے ساتھ جوتمھارے پاس آچکا ہے کفر کرتے ہیں، نبی کو اور خود تمھیں بھی محض اس وجہ سے جلا وطن کرتے ہیں کہ تم اپنے رب پر ایمان رکھتے ہواگر تم میری راہ میں جہاد کے لیےاور میری رضامندی کی طلب میں نکلتے ہو (تو ان سے دوستیاں نہ کرو ان کے پاس محبت کا پیغام چھپ کربھیجتے ہو اور مجھے خوب معلوم ہے جو تم نے چھپایا وہ بھی جو تم نے ظاہر کیا، تم میں سے جو بھی اس کام کو کرے گا وہ یقیناً وہ سیدھے راستےسے بہک جائے گا \"۔ (صحیح البخاری:۳۰۰۷ وصحیح مسلم:۲۴۹۴)\nاس سے علمانے یہ مطلب نکالا ہے کہ اگر حاطب بن ابی بلتعہ بدر ی صحابی نہ ہوتے تو انھیں قتل کردیا جاتا۔ تاکہ کوئی دوسرا اس طرح کی جاسوسی کرنے کی جرأت نہ کرے،جس سے مسلمانوں اور ان کی فوج کو نقصان پہنچے۔","",{}],[158,"§تخت\nدیکھیے: عرش","",{}],[159,"§تداول ايام\nاللہ تعالیٰ کی وسیع اورعظیم حکمرانی کا ایک مظہریہ بھی ہے کہ وہ حالات میں الٹ پھیر کرتا رہتا ہے اورقوم و قبیلےکے احوال میں تبدیلی لاتاہے۔ اس لیے کبھی ایک قوم کو برتری حاصل ہوتی ہے تو کبھی دوسری قوم کو۔ قرآن مجیدمیں کہا گیا ہے: ﴿إِن يَمۡسَسۡكُمۡ قَرۡحࣱ فَقَدۡ مَسَّ ٱلۡقَوۡمَ قَرۡحࣱ مِّثۡلُهُۥۚ وَتِلۡكَ ٱلۡأَيَّامُ نُدَاوِلُهَا بَيۡنَ ٱلنَّاسِ وَلِيَعۡلَمَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَيَتَّخِذَ مِنكُمۡ شُهَدَآءَۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ﴾ [آل عمران: ۱۴۰] \"اگرتمھیں (جنگ اُحد میں) نقصان ہوا تو مخالفین کوبھی تو (اس جنگ بدر) میں اسی طرح کانقصان ہوچکا ہے۔ اور ہم دنوں کو لوگوں کے درمیان بدلتے رہتے ہیں۔ تاکہ اللہ ایمان لانے والوں کو جان لے اور تم میں سے کچھ کو گواہ بنا لے۔ اللہ ظالموں سے محبت نہیں کرتا\"۔\nاس آیت میں اُحد اور بدر کی جنگوں کی طرف اشارہ کرتے ہوے اللہ تعالیٰ نے اپنا ایک قانون بتایا ہے۔وہ یہ کہ دنوں کے الٹ پھیر سے مسلمانوں کو اگر کوئی پریشانی ہوتی ہے تو ان کو صبرکرنا چاہیے۔ کیونکہ اگر کبھی کوئی پریشانی ہوئی تو اس سے پہلے بہت ساری آسانیاں بھی تو ہوئیں۔یہ جو کچھ ہو رہا ہے وہ حقیقت میں ایک قانون کے مطابق ہو رہا ہے۔ یہ کبھی نہیں سوچنا چاہیے کہ اللہ مسلمانوں کے مقابلے میں مخالفین اسلام اور مشرکین کو کامیابی عطا کر رہا ہے۔ بلکہ یہاں جوکچھ ہو رہا ہے،وہ سب ایک قانون کے مطابق ہو رہا ہے۔کیونکہ اگر اللہ اپنی طاقت سے سب کو مسلمان بنا دیتایا ہر حال میں صرف مسلمان ہی کامیاب ہوتے تو پھر کوئی کافر ومشرک کیوں رہتا اور پھر آخرت کا سوال وجواب سب بےکارہوجاتا،جبکہ اللہ کے اختیار میں ہے کہ سب کو مسلمان بنا دے۔ قرآن مجیدمیں ہے:﴿وَلَوۡ شَآءَ رَبُّكَ لَأٓمَنَ مَن فِي ٱلۡأَرۡضِ كُلُّهُمۡ جَمِيعًاۚ أَفَأَنتَ تُكۡرِهُ ٱلنَّاسَ حَتَّىٰ يَكُونُواْ مُؤۡمِنِينَ﴾ [یونس: ۹۹] \"اگر تیرا رب چاہتا تو زمین پررہنے والے سبھی مومن ہوتے۔ تو کیاتم لوگوں کو مجبور کروگے کہ وہ سب مومن ہوجائیں\"۔\nمطلب یہ ہے کہ جب خود اللہ تعالیٰ لوگوں کو ایمان لانے پر مجبور نہیں کر رہا ہے تو اے محمد! آپ کیوں کر لوگوں کو ایمان لانے پرمجبور کر سکتے ہیں؟\nاس آیت میں ان لوگوں کے لیے تنبیہ ہے جو نبی اکرم صلی اللہ علیہ وسلم پر جھوٹا الزام لگاتے ہیں کہ آپ نے لوگوں کو تلوار کے زور پر اسلام قبول کرنے پر مجبور کیا۔\nایک جگہ اللہ تعالیٰ نے مشرکین کے اس قول کوبھی بیان کیا ہے:﴿سَيَقُولُ ٱلَّذِينَ أَشۡرَكُواْ لَوۡ شَآءَ ٱللَّهُ مَآ أَشۡرَكۡنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمۡنَا مِن شَيۡءࣲۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ حَتَّىٰ ذَاقُواْ بَأۡسَنَاۗ قُلۡ هَلۡ عِندَكُم مِّنۡ عِلۡمࣲ فَتُخۡرِجُوهُ لَنَآۖ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ أَنتُمۡ إِلَّا تَخۡرُصُونَ﴾ [الأنعام: ۱۴۸] \"جو لوگ شرک کرتے ہیں،وہ کہیں گے اگر اللہ چاہتا تو نہ ہم شرک کرتے اور نہ ہمارے آباو اجداداور نہ ہم کسی چیز کو حرام ٹھہراتے\"۔\nلیکن اللہ کا قانون تو یہی ہے کہ کوئی شخص اپنے لیے جو کچھ پسند کرتا ہے، وہ اس کو اسی میں چھوڑ دیتاہے۔ وہ اپنی طاقت سے کسی کو اسلام پر مجبور نہیں کرتا۔\nاس لیے مسلمانوں کو چاہیےکہ دنوں کے الٹ پھیراور ادل بدل سے متاثر نہ ہوں۔بلکہ حالات کی تبدیلی کے مناسب طریقےاختیار کرتے رہیں اور اللہ تعالیٰ سے دعا بھی جاری رکھیں۔ کیونکہ اس کی مرضی کے بغیریہاں کچھ بھی نہیں ہوسکتا۔\nاللہ تعالی کا انسانوں کے بننے اور بگڑنے سے متعلق ایک اٹل قانون یہ ہے:﴿لَهُۥ مُعَقِّبَٰتࣱ مِّنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦ يَحۡفَظُونَهُۥ مِنۡ أَمۡرِ ٱللَّهِۗ إِنَّ ٱللَّهَ لَا يُغَيِّرُ مَا بِقَوۡمٍ حَتَّىٰ يُغَيِّرُواْ مَا بِأَنفُسِهِمۡۗ وَإِذَآ أَرَادَ ٱللَّهُ بِقَوۡمࣲ سُوٓءࣰ ا فَلَا مَرَدَّ لَهُۥۚ وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ﴾ [الرعد: ۱۱] \"بے شک اللہ تعالیٰ کسی قوم کی حالت اس وقت تک نہیں بدلتا، جب تک کہ وہ خود اپنے آپ کو نہیں بدل لیتی\"۔\nاس آیت میں اللہ تعالیٰ ایک عام قانون الٰہی کی طرف اشارہ کر رہا ہے کہ قوموں کو ملی ہوئی نعمتیں اس وقت تک اللہ کی طرف سے نہیں چھینی جاتیں جب تک کہ وہ خود اپنی بد اعمالیوں کی وجہ سے غضب الٰہی کی مستحق نہیں بن جاتیں۔اس لیےمسلمانوں کو خاص طورپراس بات پر غور کرنا چاہیے کہ ان کی گزشتہ عظمت کیوں چھین لی گئی اور اب یہ بری حالت ہوگئی ہے، جس کی طرف ایک صحیح حدیث میں دھیان دلایا گیا ہے کہ کافر قومیں مسلمانوں کی بربادی کی طرف دوسری دوست اقوام کو اس طرح دعوت دیں گی، جیسے دسترخوان پر دوست ہر ایک کو مختلف کھانوں کی طرف دعوت دیتا ہے۔","",{}],[160,"§ترک دنیا\nدیکھیے: رہبانیت","",{}],[161,"§ترک وطن\nدیکھیے: ہجرت","",{}],[162,"§ترکہ\nدیکھیے: ميراث","",{}],[163,"§تزکیہ نفس\nتزکیہ نفس یعنی نفس کی اصلاح۔\nنفس کی اصلاح دو چیزوں پر منحصرہے۔\n§۱- تخلیہ ۲- تحلیہ\nبرے اخلاق اور شک وشبہات سے اپنے دل کو پاک وصاف کرنے کا نام \"تخلیہ\" ہے جبکہ نفس کو اچھے آداب واخلاق کا پیکر بنانا \"تحلیہ\" کہلاتا ہے۔\n§نفس کی قسمیں:\nنفس کی تین قسمیں ہیں۔\n۱- نفس مطمئنہ: یعنی اطمینان پانے والا نفس\nجب انسان کا نفس ایمان, عمل صالح , توبہ واخلاص وغیرہ جیسے خصائل پر قائم ہو تو اسے \"نفس مطمئنہ\" کہا جاتا ہے۔ جس شخص میں یہ اوصاف پائے جاتے ہیں , موت کے وقت اس کے نفس کو مخاطب کرکے کہا جاتا ہے: ﴿يَـٰٓأَيَّتُهَا ٱلنَّفۡسُ ٱلۡمُطۡمَئِنَّةُ ٱرۡجِعِيٓ إِلَىٰ رَبِّكِ رَاضِيَةٗ مَّرۡضِيَّةٗ فَٱدۡخُلِي فِي عِبَٰدِي وَٱدۡخُلِي جَنَّتِي﴾ [الفجر: ۲۷-۳۰]\nترجمہ: اے اطمینان پانے والی روح, اپنے رب کی طرف لوٹ چل, تو اس سے راضی وہ تجھ سے راضی, تو میرے نیک بندوں میں شامل ہوجا اور میری جنت میں داخل ہوجا۔\n۲- نفس لوامہ: یعنی لعن طعن کرنے والا نفس\nانسان کے نفس میں ایک خاصیت یہ ہوتی ہے کہ وہ خیر کو پسند کرتا ہے اور شر سے نفرت کرتا ہے اور جب وہ کسی برائی میں مبتلا ہوتا ہے یا غفلت کا شکار بن جاتا ہے تو اس کا ضمیر اسے لعن طعن کرتا ہے۔ اسی کو \"نفس لوامہ\" کہتے ہیں۔ اللہ تعالی کا ارشاد ہے: ﴿لَآ أُقۡسِمُ بِيَوۡمِ ٱلۡقِيَٰمَةِ وَلَآ أُقۡسِمُ بِٱلنَّفۡسِ ٱللَّوَّامَةِ﴾ [القيامة: ۱-۲]\nترجمہ: میں قیامت کے دن کی قسم کھاتا ہوں اور میں ملامت کرنے والے نفس کی قسم کھاتا ہوں (کہ قیامت آکے رہے گی)۔\n۳- نفس امارہ: یعنی برائی پر اکسانے والا نفس\nیہ نفس قابل مذمت ہے , اس لئے کہ یہ انسان کو محض برائی کرنے پر آمادہ کرتا ہے, اس کے شر سے وہی شخص محفوظ رہ سکتا ہے جسے اللہ کی توفیق حاصل ہو۔\nاللہ تعالی کا راشاد ہے: ﴿وَمَآ أُبَرِّئُ نَفۡسِيٓۚ إِنَّ ٱلنَّفۡسَ لَأَمَّارَةُۢ بِٱلسُّوٓءِ إِلَّا مَا رَحِمَ رَبِّيٓۚ إِنَّ رَبِّي غَفُورٞ رَّحِيمٞ﴾ [يوسف: ۵۳]\nترجمہ: اور میں اپنے آپ کو پاک صاف نہیں کہتا کیونکہ نفس اکثر برائی پر اکساتا رہتا ہے مگر جس پر میرے رب کی رحمت ہو , یقیناً میرا رب معاف کرنے والا رحم والا ہے۔\nانسان کا کسی برائی سے بچ جانا اس کا اپنا کمال نہیں بلکہ یہ اللہ کا فضل ہے جس پر اسے اللہ تعالی کا شکر ادا کرنا چاہئے۔ در اصل اللہ کی توفیق کے بغیر انسان اپنے نفس کی اصلاح کرنے سے قاصر ہے۔ اللہ تعالی کا ارشاد ہے: ﴿وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنۡ أَحَدٍ أَبَدٗا وَلَٰكِنَّ ٱللَّهَ يُزَكِّي مَن يَشَآءُۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ﴾ [النور: ۲۱]\nترجمہ: اور اگر تم پر اللہ کا فضل اور اس کی رحمت نہ ہوتی تو تم میں سے کوئی پاک صاف نہ رہ سکتا تھا, مگر اللہ جسے چاہے پاک سیرت بنادیتا ہے, اور اللہ سب کچھ سننے والا اور جاننے والا ہے۔\n§تزکیہ نفس کے وسائل:\nنفس کی اصلاح کے وسائل بے شمار ہیں, ذیل میں چند اہم وسائل ذکر کئے جاتے ہیں۔\n۱- اللہ تعالی کے احکام کی مکمل پاسداری\n۲- رسول اکرم صلی اللہ علیہ وسلم کی خوش دلی کے ساتھ پیروی\n۳- نیک وکار اور اہل علم کی صحبت\n۴- تقوی اور درست بات\nاللہ تعالی کا ارشاد ہے: ﴿يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَقُولُواْ قَوۡلٗا سَدِيدٗا يُصۡلِحۡ لَكُمۡ أَعۡمَٰلَكُمۡ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡ﴾ [الأحزاب: ۷۰-۷۱]\nترجمہ: اے ایمان والو! اللہ سے ڈرتے رہو اور بات سیدھی کیا کرو, (اس طرح) اللہ تعالی تمہارے اعمال کو درست کردے گااور تمہارے گناہ معاف کردے گا۔\n۵- شرک وبدعات اور اخلاق رذیلہ سے مکمل اجتناب\n۶- توبہ واستغفار\n۷- صدقات وخیرات\nاللہ تعالی کا فرمان ہے: ﴿خُذۡ مِنۡ أَمۡوَٰلِهِمۡ صَدَقَةٗ تُطَهِّرُهُمۡ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيۡهِمۡۖ إِنَّ صَلَوٰتَكَ سَكَنٞ لَّهُمۡۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ﴾ [التوبة: ۱۰۳]\nترجمہ: تم ان کے مالوں کا صدقہ قبول کرلو۔ اس سے تم ان کو پاکیزہ بناؤگے اور ان کا تزکیہ کروگے۔ اور ان کے لئے دعا کرو۔ بے شک تمہاری دعا ان کے لئے باعث تسکین ہے۔ اور اللہ سننے والا, جاننے والا ہے۔\n۸- اللہ تعالی کا فضل اور اس کی رحمت کا حصول\nرب کائنات کا ارشاد ہے: ﴿وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنۡ أَحَدٍ أَبَدٗا وَلَٰكِنَّ ٱللَّهَ يُزَكِّي مَن يَشَآءُۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ﴾ [النور: ۲۱]\nترجمہ: اور اگر تم پر اللہ کا فضل اور اس کی رحمت نہ ہوتی تو تم میں سے کوئی بھی پاک صاف نہ رہ سکتا تھا, مگر اللہ جسے چاہے پاک سیرت بنادیتا ہے, اور اللہ سب کچھ سننے والا اور جاننے والا ہے۔\n§تزکیہ نفس کے ثمرات:\nتزکیہ نفس کی اہمیت کا اندازہ اس بات سے بخوبی لگایا جاسکتا ہے کہ اللہ تعالی نے نبی اکرم صلی اللہ علیہ وسلم کو دنیا میں اس لئے مبعوث فرمایا تاکہ وہ لوگوں کے دلوں کا تزکیہ کریں اور ان کے دل سے شرک وبدعت کی غلاظت کو دور کریں۔ اللہ تعالی کا راشاد ہے۔ ﴿لَقَدۡ مَنَّ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِينَ إِذۡ بَعَثَ فِيهِمۡ رَسُولٗا مِّنۡ أَنفُسِهِمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِهِۦ وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُواْ مِن قَبۡلُ لَفِي ضَلَٰلٖ مُّبِينٍ﴾ [آل عمران: ۱۶۴]\nترجمہ: بلا شبہ اللہ نے مومنوں پر بہت احسان کیا ہے کہ ان کے درمیان انہی میں سے ایک رسول مبعوث فرمایا جو ان پر اللہ کی آیات پڑھ کر سناتا ہے ان کے نفس کا تزکیہ کرتا ہے اور کتاب وحکمت کی تعلیم دیتا ہے۔ حالانکہ اس سے پہلے یہی لوگ کھلی گمراہی میں پڑے ہوئے تھے۔\nقرآن مجید میں تزکیہ نفس کے دنیوی واخروی فوائد کا تذکرہ آیا ہے جن کا خلاصہ یہ ہے۔\n۱- نفس کا تزکیہ کرنا دنیا وآخرت میں کامیابی کا ضامن ہے۔\nاللہ تعالی کا ارشاد ہے: ﴿قَدۡ أَفۡلَحَ مَن زَكَّىٰهَا﴾ [الشمس: ۹]\nترجمہ: کامیاب ہوا جس نے نفس کا تزکیہ کیا۔\nاور ایک دوسری آیت میں فرمایا: ﴿قَدۡ أَفۡلَحَ مَن تَزَكَّىٰ﴾ [الأعلی: ۱۴]\nترجمہ: فلاح پاگیا جس نے پاکیزگی اختیار کی۔\n۲- اپنے دل کو شبہات وشہوات سے محفوظ رکھنے والوں کو بلند درجات عطا کئے جاتے ہیں۔\nاللہ تعالی کا ارشاد ہے۔\n﴿وَمَن يَأۡتِهِۦ مُؤۡمِنٗا قَدۡ عَمِلَ ٱلصَّـٰلِحَٰتِ فَأُوْلَـٰٓئِكَ لَهُمُ ٱلدَّرَجَٰتُ ٱلۡعُلَىٰ جَنَّـٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ جَزَآءُ مَن تَزَكَّىٰ﴾ [طه: ۷۵-۷۶]\nترجمہ: اور جو مومن بن کر آئے اور اعمال بھی نیک کئے ہوں تو ایسے ہی لوگوں کے لئے بلند درجات ہیں۔ (اور) سدا بہار باغات جن میں نہریں بہہ رہی ہوں گی وہ اس میں ہمیشہ رہیں گے یہ اس شخص کے لئے جزا ہے جو (گناہوں سے) پاک رہا۔\n۳- تقوی اور نفس کی اصلاح کا بدلہ جنت ہے۔\nاللہ تعالی کا ارشاد ہے۔ ﴿وَأَمَّا مَنۡ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفۡسَ عَنِ ٱلۡهَوَىٰ فَإِنَّ ٱلۡجَنَّةَ هِيَ ٱلۡمَأۡوَىٰ﴾ [النازعات: ۴۰-۴۱]\nترجمہ: لیکن جو اپنے رب کے حضور (جوابدہی کے لئے) کھڑا ہونے سے ڈرتا رہا اور اپنے آپ کو خواہش نفس سے روکے رکھا تو جنت ہی اس کا ٹھکانہ ہوگا۔","",{}],[164,"§تسبیح\nتسبیح اسلامی اصطلاح ہے جس کا ترجمہ کسی اور زبان میں کرنا مشکل ہے۔ کیونکہ کسی اور مذہب میں تسبیح کےوہ معنی پائے ہی نہیں جاتے جس کا ذکر قرآن میں ہے۔ اس لیے کہ ہر مذہب میں کسی نہ کسی شکل میں شرک پایا جاتا ہے اور تسبیح میں شرک کے خلاف اللہ کے ایک ہونے کا ذکرہے۔ اس لیےسمجھنے کے لیے اس کا مطلب ہے کہ ہر طرح کے شرک سےپاک ہوکر اللہ کی پاکی اور عظمت کا ذکر کرنا۔ چونکہ وہ ساری کائنات کا خالق ہے، اس لیے کسی نہ کسی طرح سے ساری کائنات ہی اس کی تسبیح کررہی ہے۔اس کی تعریف اور اس کی بڑائی بیان کررہی ہے۔\n§فرشتوں کی زبان سےاللہ کی تسبیح:\n۱- ﴿وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَٰٓئِكَةِ إِنِّي جَاعِلࣱ فِي ٱلۡأَرۡضِ خَلِيفَةࣰۖ قَالُوٓاْ أَتَجۡعَلُ فِيهَا مَن يُفۡسِدُ فِيهَا وَيَسۡفِكُ ٱلدِّمَآءَ وَنَحۡنُ نُسَبِّحُ بِحَمۡدِكَ وَنُقَدِّسُ لَكَۖ قَالَ إِنِّيٓ﴾ [البقرة: ۳۰] \"اورجب تمھارے رب نے فرشتوں سے کہا:میں دنیا میں ایک خلیفہ بنانے والا ہوں۔انهوں نے کہا:کیا اس میں تو اسے منتخب کرے گا جو اس میں بگاڑ پیداکرےگا اور خوں ریزی کرےگا؟ جب کہ ہم تیری تعریف کے ساتھ تیری تسبیح کرتے ہیں اور تیری پاکی بیان کرتے ہیں\"۔\n۲- ﴿وَتَرَى ٱلۡمَلَٰٓئِكَةَ حَآفِّينَ مِنۡ حَوۡلِ ٱلۡعَرۡشِ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡۚ وَقُضِيَ بَيۡنَهُم بِٱلۡحَقِّۚ وَقِيلَ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ﴾ [الزمر: ۷۵] \"(قیامت کے دن )تم فرشتوں کو دیکھوگے کہ وہ عرش (اللہ کے تخت ) کے چاروں طرف گھیرا بنائے ہوےہیں۔ اپنے رب کی تعریف کے ساتھ تسبیح کر رہے ہیں\"۔\n۳- ﴿وَإِنَّا لَنَحۡنُ ٱلصَّآفُّونَ وَإِنَّا لَنَحۡنُ ٱلۡمُسَبِّحُونَ﴾ [الصافات: ۱۶۵-۱۶۶] \"اور ہم قطار میں کھڑے ہوے ہیں اور اس کی تسبیح کررہے ہیں\"۔\nبادلوں کی تسبیح:ارشادباری تعالیٰ ہے: ﴿وَيُسَبِّحُ ٱلرَّعۡدُ بِحَمۡدِهِۦ وَٱلۡمَلَٰٓئِكَةُ مِنۡ خِيفَتِهِۦ وَيُرۡسِلُ ٱلصَّوَٰعِقَ فَيُصِيبُ بِهَا مَن يَشَآءُ وَهُمۡ يُجَٰدِلُونَ فِي ٱللَّهِ وَهُوَ شَدِيدُ ٱلۡمِحَالِ﴾ [الرعد: ۱۳] \"گرجتے بادل اور خوف کھائے ہوے فرشتے اس کی تعریف کے ساتھ تسبیح کررہے ہیں\"۔\nپہاڑوں کی تسبیح:ارشادباری تعالیٰ ہے: ﴿إِنَّا سَخَّرۡنَا ٱلۡجِبَالَ مَعَهُۥ يُسَبِّحۡنَ بِٱلۡعَشِيِّ وَٱلۡإِشۡرَاقِ﴾ [ص: ۱۸] \"ہم نے پہاڑوں کو اس (داود) کے ساتھ لگا دیا تھا کہ شام کے وقت اور صبح کے وقت تسبیح کرتے رہیں\"۔\nپرندوں کی تسبیح:ارشادباری تعالیٰ ہے: ﴿أَلَمۡ تَرَ أَنَّ ٱللَّهَ يُسَبِّحُ لَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلطَّيۡرُ صَٰٓفَّٰتࣲۖ كُلࣱّ قَدۡ عَلِمَ صَلَاتَهُۥ وَتَسۡبِيحَهُۥۗ وَٱللَّهُ عَلِيمُۢ بِمَا يَفۡعَلُونَ﴾ [النور: ۴۱] \"کیا تم نے دیکھا نہیں کہ جو چیز بھی آسمانوں اور زمین میں ہے، اللہ کی تسبیح(تعریف)کررہی ہےاورپر پھیلائے ہوے پرندے بھی؟ ہر ایک اپنی بندگی اور تسبیح سے واقف ہے اور اللہ جانتا ہے جو کچھ وہ کرتے ہیں\"۔\nحقیقت یہ ہے کہ ساری کائنات اللہ کی \"تسبیح\" کر رہی ہے، لیکن ہم ان کی تسبیح کو سمجھتے نہیں۔\nارشادباری تعالیٰ ہے: ﴿تُسَبِّحُ لَهُ ٱلسَّمَٰوَٰتُ ٱلسَّبۡعُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ وَإِن مِّن شَيۡءٍ إِلَّا يُسَبِّحُ بِحَمۡدِهِۦ وَلَٰكِن لَّا تَفۡقَهُونَ تَسۡبِيحَهُمۡۚ إِنَّهُۥ كَانَ حَلِيمًا غَفُورࣰ ا﴾ [الإسراء: ۴۴] \"ساتوں آسمان اور زمین اور جو کچھ ان کے درمیان ہے سب اس کی تسبیح (بڑائی) کرتے ہیں اور ایسی کوئی چیزنہیں جو اس کی تعریف کے ساتھ تسبیح نہ کرتی ہو، مگر تم ان کی تسبیح کو سمجھتے نہیں ہوبےشک وہ بہت ہی برداشت کرنے والا اور معاف کرنے والا ہے\"۔\n\"تسبیح\" کو قرآن اور صحیح احادیث میں ہماری حقیقی منزل بتایا گیا ہے: ﴿رِجَالࣱ لَّا تُلۡهِيهِمۡ تِجَٰرَةࣱ وَلَا بَيۡعٌ عَن ذِكۡرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِيتَآءِ ٱلزَّكَوٰةِ يَخَافُونَ يَوۡمࣰ ا تَتَقَلَّبُ فِيهِ ٱلۡقُلُوبُ وَٱلۡأَبۡصَٰرُ﴾ [النور: ۳۷] \"ان گھروں میں،جن کو اونچا کرنے اور جن میں اپنے نام کو یاد کرنے کا اللہ نے حکم دیا ہے۔ ایسے لوگ صبح کے وقت اور شام کے وقت اللہ کی تسبیح کرتے ہیں۔جنھیں اللہ کی یاد اور نماز قائم کرنے اور زکاة دینے سے نہ تو تجارت غافل کرتی ہے نہ خرید وفروخت۔ وہ اس دن سے ڈرتے ہیں جس دن دل اور آنکھیں سب کام کرنا بند کر دیں گے\"۔\nگھروں کو بلند کرنے کےمعنی ہیں مسجدیں بنانا، جہاں عبادت کے ساتھ اللہ کی تسبیح کی جاتی ہے۔ یہ تو ان متقیوں کابیان ہے، جن کے دل ہر وقت اللہ کی یاد میں لگے رہتے ہیں اور اس کی تسبیح بیان کرتے ہیں جو یہ ہے: ’سبحان اللہ،سبحان اللہ‘اللہ پاک ہے،اللہ پاک ہے، ساری پاکی اورعظمت صرف اللہ کے لیے ہے۔کوئی اس کا شریک نہیں ہے۔لیکن جو لوگ اس کی پاکی اور عظمت کو نہیں پہچانتے اور اس کا احساس نہیں کرپاتے وہ کسی نہ کسی مخلوق کو اس کاشریک بنا بیٹھتے ہیں جیسے کسی نے کسی کو اس کا بیٹا بنادیا۔ قرآن مجیدمیں ہے:\n۱-﴿يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لَا تَغۡلُواْ فِي دِينِكُمۡ وَلَا تَقُولُواْ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ إِنَّمَا ٱلۡمَسِيحُ عِيسَى ٱبۡنُ مَرۡيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلۡقَىٰهَآ إِلَىٰ مَرۡيَمَ وَرُوحࣱ مِّنۡهُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرُسُلِهِۦۖ وَلَا تَقُولُواْ ثَلَٰثَةٌۚ ٱنتَهُواْ خَيۡرࣰ ا لَّكُمۡۚ إِنَّمَا ٱللَّهُ إِلَٰهࣱ وَٰحِدࣱۖ سُبۡحَٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدࣱۘ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَكَفَىٰ بِٱللَّهِ وَكِيلࣰ ا﴾ [النساء: ۱۷۱] \"وہ اس سے پاک ہے کہ اس کی کوئی اولاد ہو، اسی کے لیے ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے اور اللہ کافی ہے کام بنانے واسطے\"۔\n۲- ﴿وَقَالُواْ ٱتَّخَذَ ٱلرَّحۡمَٰنُ وَلَدࣰ اۗ سُبۡحَٰنَهُۥۚ بَلۡ عِبَادࣱ مُّكۡرَمُونَ﴾ [الأنبیاء: ۲۶] \"وہ کہتے ہیں کہ اللہ اولادرکھتاہے۔ بے نیاز ہے وہ۔بلکہ وہ فرشتے تو اس کے معزز بندے ہیں\"۔\nمطلب یہ ہے کہ جن کو یہ لوگ اللہ کے بیٹے سمجھ بیٹھےہیں وہ تو اس کے معزز فرشتے ہیں جو اس کی تسبیح میں لگے ہوےہیں، ان گمراہوں نے اسی کو کافی نہیں سمجھا، بلکہ اللہ کی بیٹیاں بھی بنا ڈالی، قرآن میں ہے: ﴿وَيَجۡعَلُونَ لِلَّهِ ٱلۡبَنَٰتِ سُبۡحَٰنَهُۥ وَلَهُم مَّا يَشۡتَهُونَ﴾ [النحل: ۵۷] \"وہ اللہ کے لیے بیٹیاں ٹھہراتے ہیں۔ جب کہ عظیم اور بے نیاز ہے وہ\"۔\nمشرکین عرب خود اپنے لیےتوبیٹیاں پسند نہیں کرتے تھے۔لیکن انھوں نے اللہ کی بیٹیاں بنا رکھی تھیں جن کی وہ عبادت کرتے تھے۔ اللہ تو بڑا ہی عظمت والا اور پاک ہےاس بات سے کہ وہ اپنے لیے بیٹے اور بیٹیاں بنا کررکھے، جب ایسی بات ہے تو اللہ کی تسبیح ہر وقت کرنی چاہیے، اس سے بے خبر نہیں رہنا چاہیے۔اس لیے قرآن میں بار بار اس کے لیے خبردار کیا گیا ہے(دیکھیے: سورہ آل عمران: ۴۱، سورہ طہ: ۱۳۰؛ سورہ المومن: ۵۵ وغیرہ)\nاسی لیے مسلمان ہر نماز میں رکوع کی حالت میں \"سُبْحَانَ رَبِّيَّ الْعَظِيمٍ\" اور سجدے کی حالت میں \"سُبْحَانَ رَبِّيَّ الأَعْلَی\"کہتے ہیں۔ اس کا مطلب ہے کہ میں عظیم رب کی تسبیح بیان کرتا ہوں۔ اس طرح تسبیح کے ذریعے سے اللہ نے شرک کے تمام دروازے بند کر دیے،کیونکہ تسبیح بھی عبادت ہے اور یہ تسبیح بھی صرف اللہ کےلیے ہی کی جاسکتی ہے۔اللہ نے مختلف موقعوں پر اپنے نبی کو بھی تسبیح کا حکم دیا ہے۔قرآن مجیدمیں ہے: ﴿إِذَا جَآءَ نَصۡرُ ٱللَّهِ وَٱلۡفَتۡحُ وَرَأَيۡتَ ٱلنَّاسَ يَدۡخُلُونَ فِي دِينِ ٱللَّهِ أَفۡوَاجࣰ ا فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَٱسۡتَغۡفِرۡهُۚ إِنَّهُۥ كَانَ تَوَّابَۢا﴾ [النصر: ۱-۳] \"جب اللہ کی مدد آجائے اور فتح حاصل ہو اور تم دیکھو کہ لوگ جھنڈ کے جھنڈ اللہ کے دین میں داخل ہو رہے ہیں تو تعریف کے ساتھ اپنے رب کی تسبیح کرو اور اس سے مغفرت طلب کرو۔ بے شک وہ توبہ قبول کرنے والا ہے\"۔\nیہ سورہ فتح مکہ کے بعد نازل ہوئی۔یہ وہی مکہ ہے جہاں سے سخت دل لوگوں نے نبی کواس لیے نکال دیا تھا کہ آپ ان کو ایک اللہ کی عبادت کی طرف بلاتے تھے۔آج اللہ کی مدد سے آپ فتح یاب ہو کر اپنے محبوب شہر کو واپس آئے ہیں اور لوگ گروہوں میں اسلام قبول کررہے ہیں۔ ایسے موقعے پر آپ کو حکم دیا جارہا ہے کہ اللہ کی تعریف کے ساتھ اس کی تسبیح کریں جس نے آپ کو فتح عطا کی۔ مخالفین اسلام کو شکست کا منہ دکھایا۔ اس لیے آپ صرف اس عظیم ہستی کی تسبیح کریں۔صحیح احادیث میں بھی تسبیح کی بہت اہمیت بتائی گئی ہے:\n۱- ابوہریرہ رضی اللہ عنہ سےمروی حدیث میں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «مَنْ قَالَ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ. فِی يَوْمٍ مِائَةَ مَرَّةٍ حُطَّتْ خَطَايَاهُ، وَإِنْ کَانَتْ مِثْلَ زَبَدِ الْبَحْرِ» (صحیح البخاری ۶۴۰۵، صحیح مسلم: ۲۶۹۱) \"جس نے ہر دن سوبار کہا: \"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ\" اس کے تمام گناہ مٹ جائیں گے چاہے وہ سمندر کی جھاگ کے برابر ہی کیوں نہ ہوں\"۔\n۲- ابوہریرہ رضی اللہ عنہ سےمروی حدیث میں نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «کَلِمَتَانِ حَبِيبَتَانِ إِلَی الرَّحْمَنِ، خَفِيفَتَانِ عَلَی اللِّسَانِ، ثَقِيلَتَانِ فِی الْمِيزَانِ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ». (صحیح البخاری: ۷۵۶۳، صحیح مسلم: ۲۶۹۴) \"دو لفظ جو پڑھنے میں بہت آسان ہیں، لیکن میزان میں وزنی ہیں اور رحمن کے نزدیک بہت پسندیدہ ہیں، وہ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ سُبْحَانَ اللَّهِ الْعَظِيمِہیں\"۔\nاس لیے مسلمانوں کو چاہیے کہ صبح و شام اور نماز کےبعد اللہ کی زیادہ سے زیادہ تسبیح بیان کریں۔ سبحان اللہ، سبحان اللہ کہیں تاکہ اللہ اس سے خوش ہو اور تسبیح کی برکتیں ہمیں اس زندگی میں اور اس زندگی کے بعد بھی حاصل ہوتی رہیں۔ یونس علیہ السلام اگر اللہ کی تسبیح نہ کرتے تو قیامت تک مچھلی کے پیٹ میں پڑے رہتے۔ قرآن مجیدمیں ہے: ﴿فَٱلۡتَقَمَهُ ٱلۡحُوتُ وَهُوَ مُلِيمࣱ فَلَوۡلَآ أَنَّهُۥ كَانَ مِنَ ٱلۡمُسَبِّحِينَ لَلَبِثَ فِي بَطۡنِهِۦٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ﴾ [الصافات: ۱۴۲-۱۴۴] \"تو پھر انھیں مچھلی نے نگل لیا اور وہ اپنے آپ کو ملامت کر رہے تھے۔ تو اگر وہ تسبیح کرنے والوں میں سے نہ ہوتے تو لوگوں کے اٹھائے جانے کے دن تک مچھلی کے پیٹ میں ہوتے (یعنی قیامت تک مچھلی کے پیٹ میں ہی پڑے رہتے)\"۔\nاور ان کی تسبیح اور دعا کا ذکر بھی قرآن مجیدمیں آیا ہے: ﴿وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبࣰ ا فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَيۡهِ فَنَادَىٰ فِي ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّٰلِمِينَ فَٱسۡتَجَبۡنَا لَهُۥ وَنَجَّيۡنَٰهُ مِنَ ٱلۡغَمِّۚ وَكَذَٰلِكَ نُـۨجِي ٱلۡمُؤۡمِنِينَ﴾ [الأنبیاء: ۸۷-۸۸] \"اورمچھلی والے کو یاد کرو جب وہ غصہ ہوکر چل پڑااور سمجھا کہ ہم اسے نہ پکڑیں گے۔ آخرکار اس نے اندھیرے میں سے پکارا الٰہی تیرے سوا کوئی عبادت کے لائق نہیں، تو پاک ہے،بےشک میں ہی گناہ گاروں میں سے ہوں۔تو ہم نے اس کی دعا قبول کرلی اور اس کو پریشانی سے آزاد کیا اور ہم اسی طرح ایمان والوں کو بچالیا کرتے ہیں\"۔\nاس سےمعلوم ہوا کہ سابق انبیاورسل بھی اللہ کی تسبیح بیان کیا کرتے تھےجیسے موسیٰ علیہ السلام (الاعراف:۱۴۳) اورعیسیٰ علیہ السلام۔ (المائدہ:۱۱۶)\nاور سب سے بڑھ کر یہ کہ جنت میں جانے والوں کے میں سے سبحان اللہ ہی کی آواز نکلے گی۔(یونس:۱۰)\nصحیح احایث میں بھی آیا ہے کہ ان کے دل ایک ہوں گے اور صبح و شام وہ اللہ کی تسبیح بیان کریں گے۔(دیکھیے: صحیح مسلم:۳۸۳۴)\nایک دوسری حدیث میں آیا ہے: وہ تسبیح اس طرح کریں گے جیسے لگاتار سانس کا اندر اور باہر آنا جانا لگارہتا ہے۔ (دیکھیے: صحیح مسلم: ۳۸۳۸)اسی لیے کسی مسلمان کو اللہ کی تسبیح سے غافل اوربے خبر نہیں رہنا چاہیے۔","",{}],[165,"§تشدد\nدیکھیے: ظلم","",{}],[166,"§تعزير\nتعزیر کا مطلب ہے روکنا یا کسی کام سے کسی کو منع کرنا۔ یہاں تعزیر سے مراد ایسے جرائم کی روک تھام کے لئے دی جانے والی سزاہے، جن کے لیے اسلامی شریعت میں کوئی متعین حکم نہیں دیا گیا ہے۔ ایسے جرائم کو روکنے کے لیے عدالت جو سزا مقرر کرتی ہے اس کو تعزیر کہتے ہیں۔اس سزا کے بارے میں عدالت ہی فیصلہ کرسکتی ہے کہ کیا ہونی چاہیے۔ اس سے اسلا می شریعت کی وسعت کا پتا چلتا ہے۔\nابوبردہ رضی اللہ عنہ سےمروی ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «لاَ يُجْلَدُ فَوْقَ عَشْرِ جَلَدَاتٍ إِلاَّ فِی حَدٍّ مِنْ حُدُودِ اللَّهِ».(صحیح البخاری: ۶۸۴۸، صحیح مسلم: ۱۷۰۸) \"دس کوڑےسے زیادہ کی سزا کسی کو نہیں دی جاسکتی۔ سوائے اللہ کی طے کی ہوئی حدود کے\"۔\nاس حدیث کےبارے میں ہم یہی کہہ سکتے ہیں کہ یہ کسی مخصوص حالت کے متعلق ہے۔ کیونکہ تعزیر کے ذریعےسےکسی کوقتل، پھانسی اورعمرقیدتک کی سزا بھی دی جاسکتی ہے۔جیسےجاسوس جن کی وجہ سے ملک کے تحفظ کو خطرہ درپیش ہوجائے یا نشیلی اشیا کے تاجر جن کی وجہ سے معاشرے کے تحفظ کو خطرہ پیداہوجائے وغیرہ۔ اس طرح کی کچھ مثالیں ہمیں صحابہ کرام رضی اللہ عنہم کے یہاں ملتی ہیں کہ انھوں کچھ جرائم میں دس کوڑے سے زیادہ کی سزا دی ہے۔","",{}],[167,"§تقوی\nتقویٰ کےلفظی معنی ڈرنے کے ہیں۔ یہ لفظ قرآن مجیدمیں اللہ سے ڈرنے کےلیے استعمال ہوا ہے، جس کا مطلب اللہ اور اس کے رسول کی بتائی ہوئی راہ پر چلنا۔ اس میں اوامرپر حکم بجا لانا اورنواہی پر ان سے دور رہنا دونوں شامل ہیں۔اوامر واحکام جیسے: نمازکی ادائی، زکاة نکالنی،ماہ رمضان میں روزے رکھنا، حج کرنے کی استطاعت ہو تو حج کرنا،ایک دوسرے کی مدد، رشتے دارو ں کے ساتھ اچھا سلوک اور غریبوں کی مددوغیرہ شامل ہیں۔ نواہی (ممنوع کاموں)میں زنا، چوری،ناحق قتل، جھوٹی گواہی اورنارواظلم وزیادتی وغیرہ افعال شامل ہیں۔اللہ کے نزدیک اس سے زیادہ ڈرنے والا شخص ہی اعلی ہے، قرآن مجیدمیں ہے:﴿إِنَّ أَكۡرَمَكُمۡ عِندَ ٱللَّهِ أَتۡقَىٰكُمۡۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرࣱ‏﴾ [الحجرات: ۱۳] \"حقیقت میں اللہ کے یہاں تم میں سب سے اعلیٰ وہ ہے جو تم میں سب سے زیادہ(اللہ کا) ڈر رکھتا ہے۔ یقیناً اللہ سب کچھ جاننے والا اور خبر رکھنے والا ہے\"۔\nقرآن مجیدسےصرف متقی (اللہ سے ڈرنے والے)لوگ ہی فائدہ اٹھا سکتے ہیں:﴿ذَٰلِكَ ٱلۡكِتَٰبُ لَا رَيۡبَۛ فِيهِۛ هُدࣰ ى لِّلۡمُتَّقِينَ﴾ [البقرة: ۲] \"یہ وہی کتاب ہے(جس کا وعدہ کیا گیا تھا) جس میں کوئی شک نہیں، اس میں رہنمائی ان لوگوں کے لیے ہے جو اللہ سے ڈرنے والے ہیں\"۔\nجولوگ اللہ کاتقویٰ (ڈر) رکھتے ہیں ان سے اللہ کا وعدہ ہےکہ ان کے لیے وہ راستے کھول دے گا: ﴿فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ فَارِقُوهُنَّ بِمَعۡرُوفࣲ وَأَشۡهِدُواْ ذَوَيۡ عَدۡلࣲ مِّنكُمۡ وَأَقِيمُواْ ٱلشَّهَٰدَةَ لِلَّهِۚ ذَٰلِكُمۡ يُوعَظُ بِهِۦ مَن كَانَ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مَخۡرَجࣰ ا﴾ [الطلاق: ۲] \"جوکوئی اللہ کا ڈر رکھے گا، اس کو وہ (پریشانی) سے نکلنے کی راہ پیدا کردے گا؟\"۔\nمزیدفرمایا: ﴿وَٱلَّٰٓـِٔي يَئِسۡنَ مِنَ ٱلۡمَحِيضِ مِن نِّسَآئِكُمۡ إِنِ ٱرۡتَبۡتُمۡ فَعِدَّتُهُنَّ ثَلَٰثَةُ أَشۡهُرࣲ وَٱلَّٰٓـِٔي لَمۡ يَحِضۡنَۚ وَأُوْلَٰتُ ٱلۡأَحۡمَالِ أَجَلُهُنَّ أَن يَضَعۡنَ حَمۡلَهُنَّۚ وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مِنۡ أَمۡرِهِۦ يُسۡرࣰ ا﴾ [الطلاق: ۴] \"جو کوئی اللہ کا ڈر رکھے گا اس کے معاملے میں وہ آسانی پیدا کر دے گا\"۔\nاللہ سے ڈرنے والے ہی کامیاب ہوں گے:﴿وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ وَيَخۡشَ ٱللَّهَ وَيَتَّقۡهِ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَآئِزُونَ﴾ [النور: ۵۲] \"جو کوئی اللہ اور اس کے رسول کے احکام کی اطاعت کرے اور اللہ سے ڈرے، تو ایسے ہی لوگ کامیابی حاصل کرنے والے ہیں\"۔\nخلاصہ یہ کہ متقی اورپرہیزگار وہ لوگ ہیں،جو اللہ کے بتائے ہوےراستے پر چلتے ہیں اور رسول نے جو کچھ حکم دیا ہےاس کو قبول کرتے ہیں: ﴿مَّآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنۡ أَهۡلِ ٱلۡقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِ كَيۡ لَا يَكُونَ دُولَةَۢ بَيۡنَ ٱلۡأَغۡنِيَآءِ مِنكُمۡۚ وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمۡ عَنۡهُ فَٱنتَهُواْۚ وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ﴾ [الحشر: ۷] \"اوررسول جو بھی تمھیں حکم دے اس پر عمل کرو اور جس سے تمھیں روکے رک جاؤ اور اللہ کا ڈر رکھو،یقیناً اللہ کا عذاب بہت سخت ہے\"۔","",{}],[168,"§تقویم\nدیکھیے: ہجری","",{}],[169,"§تکبر\nتکبرعربی کا لفظ ہے، جس کے معنی فخر اور گھمنڈ کےہیں۔تکبر ایک ایسی بیماری ہےجو اگر کسی انسان کو لگ جائے تو وہ حق وباطل اورسچ اورجھوٹ میں فرق نہیں کر سکتا۔ اسی لیےاللہ تعالیٰ متکبرشخص کو ناپسند کرتاہے،قرآن مجیدمیں ہے:﴿لَا جَرَمَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡتَكۡبِرِينَ﴾ [النحل: ۲۳] \"(اللہ کو ) ایسے لوگ پسند نہیں ہیں جو اپنے آپ کو بڑا سمجھتے ہوں ( یعنی متکبرہوں)\"۔\nاس کےبرعکس اللہ تعالیٰ نے ان لوگوں کی تعریف کی ہے جو متکبر نہیں ہیں۔ قرآن مجیدمیں ایک جگہ ارشاد ہے: ﴿لَتَجِدَنَّ أَشَدَّ ٱلنَّاسِ عَدَٰوَةࣰ لِّلَّذِينَ ءَامَنُواْ ٱلۡيَهُودَ وَٱلَّذِينَ أَشۡرَكُواْۖ وَلَتَجِدَنَّ أَقۡرَبَهُم مَّوَدَّةࣰ لِّلَّذِينَ ءَامَنُواْ ٱلَّذِينَ قَالُوٓاْ إِنَّا نَصَٰرَىٰۚ ذَٰلِكَ بِأَنَّ مِنۡهُمۡ قِسِّيسِينَ وَرُهۡبَانࣰ ا وَأَنَّهُمۡ لَا يَسۡتَكۡبِرُونَ﴾ [المائدة: ۸۲] \"تم ایمان والوں کی دشمنی میں سب لوگوں سے بڑھ کریہودیوں اور مشرکوں کو پاؤ گےاور ایمان والوں کی دوستی میں سب سے قریب ان لوگوں کو پاؤ گے، جنھوں نے کہا کہ ہم نصاری ہیں۔یہ اس وجہ سےکہ ان میں بہت سے مذہب پر چلنے اور دنیا ترک کرنے والے (رہبان ) پائے جاتے ہیں اور اس وجہ سے کہ وہ تکبر نہیں کرتے\"۔\nخلاصہ یہ کہ جب ان کو حق بات بتائی جاتی ہے، تووہ اسےقبول کر لیتےہیں۔لیکن اس کا یہ مطلب نہیں کہ یہودیوں میں کوئی حق قبول کرنے والانہیں تھا۔ ان میں بہت سے لوگ ایسے تھے، جنھوں نے حق کو قبول کیا۔\nیہودیوں کے ایک عالم عبداللہ بن سلام تھے۔قبول اسلام کے بعد ان کی تعریف کرتے ہوےقرآن پاک میں کہا گیاہے: ﴿قُلۡ أَرَءَيۡتُمۡ إِن كَانَ مِنۡ عِندِ ٱللَّهِ وَكَفَرۡتُم بِهِۦ وَشَهِدَ شَاهِدࣱ مِّنۢ بَنِيٓ إِسۡرَٰٓءِيلَ عَلَىٰ مِثۡلِهِۦ فَـَٔامَنَ وَٱسۡتَكۡبَرۡتُمۡۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ﴾ [الأحقاف: ۱۰] \"بنی اسرائیل میں سے ایک گواہ نے ایسی ہی کتاب کی گواہی بھی دے دی۔ اور وہ ایمان بھی لے آیا اور تم تکبر میں پڑے رہ گئے\"۔\nایک صحیح حدیث میں سعد بن ابی وقاص رضی اللہ عنہ کہتے ہیں: «مَا سَمِعْتُ النبی صلی اللہ علیہ وسلم يَقُولُ لأَحَدٍ يَمْشِي عَلَی الأَرْضِ إِنَّهُ مِنْ أَهْلِ الْجَنَّةِ إِلا لِعَبْدِ اللَّهِ بْنِ سَلامٍ، قَالَ: وَفِيهِ نَزَلَتْ هَذِهِ الآيَةُ: [آیت] (صحیح البخاری:۳۸۱۲، وصحیح مسلم:۲۲۸۳) \"میں نے زمین پر چلنے والے کسی شخص کے بارے میں یہ نہیں سنا کہ نبی اکرم صلی اللہ علیہ وسلم اس کو جنتی کہتے ہوں سوائے عبد اللہ بن سلام کےاُنهی کے بارے میں قرآن کی سورہ الاحقاف کی مذکور بالا آیت نازل ہوئی\"۔\nاللہ نےتکبر کرنے والوں کی سخت مذمت کی ہے۔سب سے پہلا متکبر توابلیس تھا،جس کو اللہ نے فرشتوں کے ساتھ آدم کے آگے جھکنے کا حکم دیا، اس کےسوا سب جھک گئے۔ اس نے جھکنے سے انکار کردیا، تکبر کیا اور وہ نافرمانوں میں سے ہوگیا۔(البقرہ:۳۴)\nاور اسی تکبر کے وجہ سے اس کوذلیل کر کے جنت سے زمین پر بھیج دیاگیا۔ (الاعراف:۱۳)\nتکبر کرنے والے جہاں بھی ہوں گے ذلیل ہی ہوں گے۔ اعلی مرتبہ کے مالک تو وہ لوگ ہوں گے جو اللہ کے لیے نرمی اپنائیں گے، جس کی توثیق صحیح حدیث سے بھی ہوتی ہے: جو اللہ کے لیےنرمی اختیارکرے گا اللہ اس کو اونچا درجہ عطا کرے گا۔\nایک دوسری صحیح حدیث میں اس طرح آیا ہے: بنی مجاشع کے بھائی عیاض بن حمار رضی اللہ عنہ کہتے ہیں کہ ایک دن رسول اللہ صلی اللہ علیہ وسلم خطبہ دینے کے لیے ہمارے درمیان کھڑے ہوے۔ آپ نے فرمایا: «إِنَّ اللَّهَ أَوْحَی إِلَيَّ أَنْ تَوَاضَعُوا حَتَّی لا يَفْخَرَ أَحَدٌ عَلَی أَحَدٍ وَلا يَبْغِ أَحَدٌ عَلَی أَحَدٍ». (صحیح مسلم: ۲۸۶۵/۶۴) \"اللہ نے میری طرف یہ وحی کی ہے کہ لوگو! نرمی اختیار کرو،ایک دوسرے پر تکبر نہ کرو اور نہ کسی پر ظلم کرو\"۔\nقرآن مجیدمیں بہت سے تکبر کرنےوالوں کا بیان ہوا ہے، اس میں ایک فرعون بھی ہے:﴿وَٱسۡتَكۡبَرَ هُوَ وَجُنُودُهُۥ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَظَنُّوٓاْ أَنَّهُمۡ إِلَيۡنَا لَا يُرۡجَعُونَ فَأَخَذۡنَٰهُ وَجُنُودَهُۥ فَنَبَذۡنَٰهُمۡ فِي ٱلۡيَمِّۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ﴾ [القصص: ۳۹-۴۰] \"اس نے اور اس کی فوجوں نے دنیامیں بغیرکسی حق کےتکبرکیااور سمجھا کہ انھیں ہماری طرف لوٹنا نہیں ہوگا، تو ہم نے اسے اور اس کے لشکر کو پکڑ لیااور انھیں دریا میں ڈبو دیا۔اب دیکھ لو ان ظالموں کا کیسا انجام ہوا\"۔\nقرآن مجیدمیں تین بڑےتکبر کرنے والوں کا بیان ایک ہی آیت میں آیا ہے۔ پھر ان کا انجام بھی بتایا گیا ہے: ﴿وَقَٰرُونَ وَفِرۡعَوۡنَ وَهَٰمَٰنَۖ وَلَقَدۡ جَآءَهُم مُّوسَىٰ بِٱلۡبَيِّنَٰتِ فَٱسۡتَكۡبَرُواْ فِي ٱلۡأَرۡضِ وَمَا كَانُواْ سَٰبِقِينَ فَكُلًّا أَخَذۡنَا بِذَنۢبِهِۦۖ فَمِنۡهُم مَّنۡ أَرۡسَلۡنَا عَلَيۡهِ حَاصِبࣰ ا وَمِنۡهُم مَّنۡ أَخَذَتۡهُ ٱلصَّيۡحَةُ وَمِنۡهُم مَّنۡ خَسَفۡنَا بِهِ ٱلۡأَرۡضَ وَمِنۡهُم مَّنۡ أَغۡرَقۡنَاۚ وَمَا كَانَ ٱللَّهُ لِيَظۡلِمَهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ﴾ [العنکبوت: ۳۹-۴۰] \"قارون،فرعون اور ہامان کو ہم نے نیست ونابودکردیا۔موسیٰ ان کے پاس اللہ کا کلام لےکرآئے،لیکن انھوں نے دنیا میں تکبر کیا، حالانکہ وہ بازی لے جانےوالے نہ تھے۔ تو ہر ایک کو ہم نے اس کے اپنے گناہ کے سبب پکڑ لیا۔ پھر ان میں سے کچھ کے اوپر تو ہم نے پتھربرسانے والی ہوا بھیجی اور ان میں سے کچھ کو ایک زوردار دھماکے نے آدبوچا اور ان میں سے کچھ کو ہم نے زمین میں دھنسادیا اور ان میں سے کچھ کو ڈبودیا۔ اللہ ایسا نہ تھا کہ ان پر ظلم کرتا، لیکن وہ خوداپنے آپ پر ظلم کرتے تھے\"۔\nاسی طرح جب نبی اکرم محمد صلی اللہ علیہ وسلم نے اللہ کی طرف لوگوں کو بلایا تو قریش کے سرداروں میں سے ایک ولید بن مغیرہ بھی تھا،جس نے تکبر کیا۔ اس پر یہ آیت نازل ہوئی:﴿ذَرۡنِي وَمَنۡ خَلَقۡتُ وَحِيدࣰ ا﴾ [المدثر: ۱۱] \"چھوڑدو مجھے اور اس کو جسے میں نے اکیلا پیدا کیا\"۔\nاللہ تعالیٰ اپنی نعمتوں کا ذکرکرنے کے بعد کہتاہے:﴿ثُمَّ أَدۡبَرَ وَٱسۡتَكۡبَرَ فَقَالَ إِنۡ هَٰذَآ إِلَّا سِحۡرࣱ يُؤۡثَرُ إِنۡ هَٰذَآ إِلَّا قَوۡلُ ٱلۡبَشَرِ سَأُصۡلِيهِ سَقَرَ وَمَآ أَدۡرَىٰكَ مَا سَقَرُ لَا تُبۡقِي وَلَا تَذَرُ لَوَّاحَةࣱ لِّلۡبَشَرِ﴾ [المدثر: ۲۳-۲۹] \"پھر پیٹھ پھیری اور تکبرکیا۔ پھر کہا:یہ قرآن تو ایک جادوہے،جو ہوتا چلاآرہا ہے۔یہ تو انسان کا ہی قول ہے۔میں جلد ہی اسے سقر(دہکتی آگ) میں ڈال دوں گا۔ اورتمھیں کیا معلوم یہ سقرکیا ہے؟ یہ وہ آگ ہے جو نہ ترس کھائے گی اور نہ چھوڑے گی۔ وہ کھال کو جلا کر کالا کر دے گی\"۔\nیہ ولید بن مغیرہ قریش کے ان سرداروں میں سے ایک تھا جونبی اکرم صلی اللہ علیہ وسلم کامذاق اڑایا کرتے تھے،جن کے بارے میں یہ آیت نازل ہوئی:﴿إِنَّا كَفَيۡنَٰكَ ٱلۡمُسۡتَهۡزِءِينَ﴾ [الحجر: ۹۵] \"ہنسی اڑا نے والوں کے لیے ہم تمھاری طرف سے کافی ہیں\"۔\nپھراس کی موت اس طرح ہوئی کہ ایک تیر جو اس کے پیر میں دو سال پہلے لگ گیا تھا، اس سے زہر پیداہوگیا۔ وہ اس دنیا سے ایسا گیا کہ اس کو یاد کرنے والا بھی کوئی نہیں رہا۔ بلکہ اس کے کچھ بیٹوں نےاسلام قبول کرلیا۔ان میں سے ایک خالد بن ولید ہیں،جواسلامی افواج کےقائدبنےاورمختلف جگہوں پر جہاد کیا اوراسلام کےدشمنوں کو شکست دی۔اسلامی تاریخ میں ان کا نام سنہرے الفاظ میں لکھا ہواہے جب کہ ان کے متکبر باپ کی ملامت کی جاتی ہے۔","",{}],[170,"§تلاش حق\nدیکھیے: مجاہدہ","",{}],[171,"§تہذیب اخلاق\nدیکھیے: قرآن میں اخلاق کی تعلیم","",{}],[172,"§تہمت\nدیکھیے: قذف","",{}],[173,"§تھوہڑ=زقوم\n***","",{}],[174,"§تواب\nدیکھیے: اسماے حسنی","",{}],[175,"§توبہ\nتوبہ کےمعنی افسوس کرنے، پلٹنے،ندامت کرنےیا رجوع کرنے کرنے کے ہوتے ہیں۔اسلامی تعلیمات میں اس کی بڑی اہمیت ہے۔کیونکہ انسان اپنی فطرت میں توسچاہےلیکن روزمرہ کی زندگی میں بہت ظالم، نافرمان اورمتکبر ہے۔ قرآن مجیدمیں آیا ہے:\n۱- ﴿وَءَاتَىٰكُم مِّن كُلِّ مَا سَأَلۡتُمُوهُۚ وَإِن تَعُدُّواْ نِعۡمَتَ ٱللَّهِ لَا تُحۡصُوهَآۗ إِنَّ ٱلۡإِنسَٰنَ لَظَلُومࣱ كَفَّارࣱ‏﴾ [إبراهیم: ۳۴] \"اس نے تمھیں تمھاری مطلوبہ سبھی چیزیں دے رکھی ہیں۔اگر تم اللہ کی نعمتوں کا شمار کرنا چاہوتو انھیں پوری طرح شمار نہیں کرسکتے۔حقیقت میں انسان بہت ظالم اور نا شکر گزار ہے\"۔\n۲- ﴿إِنَّا عَرَضۡنَا ٱلۡأَمَانَةَ عَلَى ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلۡجِبَالِ فَأَبَيۡنَ أَن يَحۡمِلۡنَهَا وَأَشۡفَقۡنَ مِنۡهَا وَحَمَلَهَا ٱلۡإِنسَٰنُۖ إِنَّهُۥ كَانَ ظَلُومࣰ ا جَهُولࣰ ا﴾ [الأحزاب: ۷۲] \"ہم نے اس امانت(قرآن) کو آسمانوں، زمین اور پہاڑوں پر پیش کیا لیکن کوئی بھی اس کو اٹھانے کے لیے راضی نہ ہوا، بلکہ اس سے ڈر گئے، لیکن انسان نے اسے اٹھا ليا۔یقیناً وہ بہت ظالم اور بے وقوف ہے\"۔\nانسان کے ظالم اور بے وقوف ہونے میں شیطان کا بھی بہت دخل ہے: ﴿ٱلشَّيۡطَٰنَ لِلۡإِنسَٰنِ عَدُوࣱّ مُّبِينࣱ‏﴾ [یوسف: ۵] \"یقیناً شیطان انسان کا کھلا ہوا دشمن ہے\"۔\nایک طرف انسان خود ظالم اور بے وقوف ہے۔کیونکہ اس نے اس امانت کو قبول کر لیا جس کو آسمانوں،زمینوں اور پہاڑوں نے نامنظور کردیا تھا، دوسری طرف شیطان بھی اس کےپیچھے لگا ہوا ہےتاکہ اس کو گمراہ کرتا رہے۔جب ایسی صورت ہےتو انسان سے گناہ کا عمل ہونا کوئی تعجب کی بات نہیں، کیونکہ قدم قدم پر شیطان اس کو اللہ کا نافرمان بنانے پر لگاہواہے، یہاں تک کہ اس نے آدم علیہ السلام کوبھی نہیں بخشا اور ان سےبھی اللہ کی نافرمانی کرواہی دی: ﴿فَوَسۡوَسَ إِلَيۡهِ ٱلشَّيۡطَٰنُ قَالَ يَٰٓـَٔادَمُ هَلۡ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلۡخُلۡدِ وَمُلۡكࣲ لَّا يَبۡلَىٰ فَأَكَلَا مِنۡهَا فَبَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۚ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ﴾ [طه: ۱۲۰-۱۲۱] \"لیکن شیطان نے اسے شک میں ڈال دیا۔ اس نے (آدم سے)کہا: میں تجھے دائمی زندگی کا درخت اور بادشاہت بتلاؤں جو کبھی پرانی نہ ہو؟چنانچہ ان دونوں نے اس درخت سےکھا لیا،پس ان کے ستر کھل گئے، وہ جنت کے پتے اپنے اوپرڈھانپنے لگے۔آدم نے اپنے رب کی نافرمانی کی تو وہ راستے سے گمراہ ہوگیا\"۔\nجب انسان کی یہ حالت ہے تواللہ تعالیٰ نے اپنی رحمت ومہربانی سے توبہ کا دروازہ کھول دیا اور اپنے بندوں سے کہا : ﴿قُلۡ يَٰعِبَادِيَ ٱلَّذِينَ أَسۡرَفُواْ عَلَىٰٓ أَنفُسِهِمۡ لَا تَقۡنَطُواْ مِن رَّحۡمَةِ ٱللَّهِۚ إِنَّ ٱللَّهَ يَغۡفِرُ ٱلذُّنُوبَ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ﴾ [الزمر: ۵۳] \"کہہ دو:اے میرے بندو!جنھوں نے خودپرظلم کیے ہیں۔ تم اللہ کی رحمت سے مایوس مت ہو۔ بےشک اللہ سارے گناہوں کو معاف کردیتا ہے۔ حقیقت میں وہ بہت توبہ قبول کرنے والا اور مہربان ہے\"۔\nایک جگہ اللہ تعالیٰ مسلمانوں کو توبہ کرنے کاحکم دیتا ہے: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ تُوبُوٓاْ إِلَى ٱللَّهِ تَوۡبَةࣰ نَّصُوحًا عَسَىٰ رَبُّكُمۡ أَن يُكَفِّرَ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَيُدۡخِلَكُمۡ جَنَّٰتࣲ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ يَوۡمَ لَا يُخۡزِي ٱللَّهُ ٱلنَّبِيَّ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥۖ نُورُهُمۡ يَسۡعَىٰ بَيۡنَ أَيۡدِيهِمۡ وَبِأَيۡمَٰنِهِمۡ يَقُولُونَ رَبَّنَآ أَتۡمِمۡ لَنَا نُورَنَا وَٱغۡفِرۡ لَنَآۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ‏﴾ [التحریم: ۸] \"اے ایمان والو! اللہ کے آگے سچے دل سے توبہ کرو، بہت ممکن ہے تمھارا رب تم سےتمھاری برائیاں دور کردے اور تمھیں ایسی جنتوں میں داخل کر دے جن کے نیچے نہریں بہہ رہی ہوں گی\"۔\nآیت میں عربی لفظ توبۃ النصوح(خالص توبہ) استعمال ہوا ہے،جس کا مطلب ہے: سچے دل سے کی گئی توبہ،اس کے لیے مندرجہ ذیل شرائط کا ہونا لازم ہے:\n۱- انسان جس گناہ سے توبہ کررہا ہے، اسے ہمیشہ کے لیے ترک کردے اور دل میں یہ عہد کرے کہ اب دوبارہ اس گناہ کے قریب اُسے نہیں جانا ہے۔\n۲- اپنے کیے ہوے گناہ کےلیے اللہ کے سامنے شرمندہ ہو۔\n۳- اگر اس گناہ کا تعلق بندوں سے ہو تو ان سے معافی مانگے اور کسی کا اس کے پاس مال ہو تو اس کو لوٹا دے۔\nاس طرح توبہ کرنے کوتوبۃ النصوح(خالص توبہ) کہتےہیں۔یقیناً جس نے اس طرح توبہ کرلی پھر وہ کبھی گناہ نہیں کرسکتا اور اگرغلطی سے ہو بھی جائے تو فوراً توبہ کرلے گا۔ قرآن مجیدمیں ہے: ﴿وَإِذَا جَآءَكَ ٱلَّذِينَ يُؤۡمِنُونَ بِـَٔايَٰتِنَا فَقُلۡ سَلَٰمٌ عَلَيۡكُمۡۖ كَتَبَ رَبُّكُمۡ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَ أَنَّهُۥ مَنۡ عَمِلَ مِنكُمۡ سُوٓءَۢا بِجَهَٰلَةࣲ ثُمَّ تَابَ مِنۢ بَعۡدِهِۦ وَأَصۡلَحَ فَأَنَّهُۥ غَفُورࣱ رَّحِيمࣱ‏﴾ [الأنعام: ۵۴] \"تم میں سے کسی نے غلطی سے گناہ کرلیا اور توبہ کرکے اپنی اصلاح کرلی تو اللہ غفورورحیم (بہت معاف کرنے والا اور مہربان) ہے\"۔\nتوبہ انبیاورسل کا عمل ہے۔ جیسے آدم علیہ السلام نے توبہ کی:﴿فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتࣲ فَتَابَ عَلَيۡهِۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ﴾ [البقرة: ۳۷] \"پھر آدم نے اپنے رب سے کچھ الفاظ سیکھ کر معافی مانگی تو اللہ نے اس کی توبہ قبول کرلی۔بے شک وہ تواب ورحیم (توبہ قبول کرنے والا اور رحم کرنے والا) ہے\"۔\nابراہیم علیہ السلام بھی توبہ کرنے والوں میں سے تھے۔ قرآن مجید میں ہے:﴿رَبَّنَا وَٱجۡعَلۡنَا مُسۡلِمَيۡنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةࣰ مُّسۡلِمَةࣰ لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبۡ عَلَيۡنَآۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ﴾ [البقرة: ۱۲۸] \"(اے ہمارے رب)ہمیں حج کرنے کا طریقہ بتا اور ہماری توبہ قبول کر۔بے شک تو توبہتواب ورحیم (توبہ قبول کرنے والا اور رحم کرنے والا)ہے\"۔\nموسی علیہ السلام نے بھی توبہ کی تھی:﴿وَلَمَّا جَآءَ مُوسَىٰ لِمِيقَٰتِنَا وَكَلَّمَهُۥ رَبُّهُۥ قَالَ رَبِّ أَرِنِيٓ أَنظُرۡ إِلَيۡكَۚ قَالَ لَن تَرَىٰنِي وَلَٰكِنِ ٱنظُرۡ إِلَى ٱلۡجَبَلِ فَإِنِ ٱسۡتَقَرَّ مَكَانَهُۥ فَسَوۡفَ تَرَىٰنِيۚ فَلَمَّا تَجَلَّىٰ رَبُّهُۥ لِلۡجَبَلِ جَعَلَهُۥ دَكࣰّ ا وَخَرَّ مُوسَىٰ صَعِقࣰ اۚ فَلَمَّآ أَفَاقَ قَالَ سُبۡحَٰنَكَ تُبۡتُ إِلَيۡكَ وَأَنَا۠ أَوَّلُ ٱلۡمُؤۡمِنِينَ﴾ [الأعراف: ۱۴۳] \"پس جب اللہ نے اپنی تجلی پہاڑ پر ڈالی تو وہ ریزہ ریزہ ہوگیا اورموسیٰ بے ہوش ہوکر گرپڑے، پھرجب ہوش میں آئے تو پکار اٹھے:عظمت ہے تیری، میں تیرے سامنے توبہ کرتا ہوں اور سب سے پہلے ایمان لانے والوں میں ہوں\"۔\nاللہ تعالیٰ سارے مسلمانوں کو بھی توبہ کرنے کا حکم دیتا ہے: ﴿وَقُل لِّلۡمُؤۡمِنَٰتِ يَغۡضُضۡنَ مِنۡ أَبۡصَٰرِهِنَّ وَيَحۡفَظۡنَ فُرُوجَهُنَّ وَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنۡهَاۖ وَلۡيَضۡرِبۡنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّۖ وَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوۡ ءَابَآئِهِنَّ أَوۡ ءَابَآءِ بُعُولَتِهِنَّ أَوۡ أَبۡنَآئِهِنَّ أَوۡ أَبۡنَآءِ بُعُولَتِهِنَّ أَوۡ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ أَخَوَٰتِهِنَّ أَوۡ نِسَآئِهِنَّ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُنَّ أَوِ ٱلتَّٰبِعِينَ غَيۡرِ أُوْلِي ٱلۡإِرۡبَةِ مِنَ ٱلرِّجَالِ أَوِ ٱلطِّفۡلِ ٱلَّذِينَ لَمۡ يَظۡهَرُواْ عَلَىٰ عَوۡرَٰتِ ٱلنِّسَآءِۖ وَلَا يَضۡرِبۡنَ بِأَرۡجُلِهِنَّ لِيُعۡلَمَ مَا يُخۡفِينَ مِن زِينَتِهِنَّۚ وَتُوبُوٓاْ إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلۡمُؤۡمِنُونَ لَعَلَّكُمۡ تُفۡلِحُونَ﴾ [النور: ۳۱] \"اے ایمان والو! تم سب مل کر اللہ سے توبہ کرو تاکہ تم کامیاب ہوجاؤ\"۔\nتوبہ کرنا بھی ایک طرح کی عبادت ہے۔اس لیےیہ بھی صرف اللہ کے لیے ہے۔ کسی اور کے سامنے توبہ کرنا اللہ کے ساتھ اس کو شریک ٹھہرانا ہے۔ قرآن مجیدمیں ہے:\n۱- ﴿أَلَمۡ يَعۡلَمُوٓاْ أَنَّ ٱللَّهَ هُوَ يَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَيَأۡخُذُ ٱلصَّدَقَٰتِ وَأَنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ﴾ [التوبة: ۱۰۴] \"کیا وہ جانتے نہیں کہ اللہ ہی ہے جو اپنے بندوں کی توبہ قبول کرتا ہے اور وہی صدقات کو قبول کرتا ہے اور اللہ تواب ورحیم (بڑاتوبہ قبول کرنے والا اور رحم کرنے والا)ہے\"۔\n۲- ﴿وَهُوَ ٱلَّذِي يَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَيَعۡفُواْ عَنِ ٱلسَّيِّـَٔاتِ وَيَعۡلَمُ مَا تَفۡعَلُونَ﴾ [الشوری: ۲۵] \"وہی ہے جو اپنے بندوں کی توبہ قبول کرتا ہے اور برائیوں کو معاف کردیتا ہے اور وہ جانتا ہے جو کچھ تم کرتے ہو\"۔\nان آیتوں سے واضح ہوتا ہے کہ جس طرح تمام عبادتیں اللہ تعالیٰ کے لیےخاص ہیں، اسی طرح توبہ بھی اسی کے لیےخاص ہے۔اسی سے توبہ کرنی چاہیے۔وہی توبہ قبول کرنے والا اور گناہوں سے پاک کرنے والا ہے۔اس کا کوئی شریک نہیں۔اسی لیے جس نے بھی توبہ کرنے میں کسی کو اللہ کا شریک بنایا اور اللہ کے سوا کسی اور کے سامنے توبہ کی اس نے شرک کیا اور شرک گناہ عظیم میں سے ایک ہے جو ہرگز معاف نہیں کیا جائے گا۔","",{}],[176,"§توحيد\nتوحید کےمعنی ایک اللہ کی الوہیت پر یقین کےہیں۔مذہب اسلام کی یہ بنیادی اور اہم تعلیم ہے۔ تمام انبیاورسل نے اسی کی تعلیم دی۔لیکن ان کی قوموں نے توحید کی تعلیم کو یا تو بھلادیا تھا یا اس کی شکل بدل دی اور گمراہ ہوگئی تھیں۔ اسی لیےاسلام قیامت تک کے لیے آخری، خالص اور صحیح مذہب بن کرپوری انسانیت کی رہنمائی اور نجات کے لیے بھیجاگیاہے۔قرآن اور احادیث میں اس کا تفصیلی بیان ہےتاکہ پھر کہیں انسان راہ سے بھٹک نہ جائے۔\nیہاں توحید کے مختلف اقسام کا قرآن اور حدیث کی روشنی میں تفصیلی بیان پیش کیا جارہا ہے:\n§توحید کی تین قسمیں یاحقیقتیں:\n۱- توحیدربوبیت: توحیدکی پہلی قسم:توحید ربوبیت کا مطلب یہ یقین ہےکہ اس دنیا کوصرف ایک اللہ نے پیدا کیا ہے۔اس کام میں اس کا کوئی شریک اورساجھی نہیں ہے۔وہی اس کوچلا رہا ہے۔ وہی ہمارا اور ساری مخلوق کامربی ہے اور پھر وہی اس دنیا کا خاتمہ بھی کرسکتا ہے اور اس کائنات میں جو کچھ بھی ہورہا ہے وہ سب اللہ کے حکم کے مطابق ہورہا ہے، قرآن مجیدمیں ہے:\n۱-﴿إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامࣲ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ يُغۡشِي ٱلَّيۡلَ ٱلنَّهَارَ يَطۡلُبُهُۥ حَثِيثࣰ ا وَٱلشَّمۡسَ وَٱلۡقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتِۭ بِأَمۡرِهِۦٓۗ أَلَا لَهُ ٱلۡخَلۡقُ وَٱلۡأَمۡرُۗ تَبَارَكَ ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ﴾ [الأعراف: ۵۴] \"حقیقت میں تمھارا رب(حقیقی معبود) وہی اللہ ہے، جس نےآسمانوں اور زمین کی چھے دن میں تخلیق کی اور پھر عرش پربلند ہو گیا۔ وہ رات کو دن پر ایسے ڈھانکتا ہے، جو تیز رفتاری سے اس کا پیچھا کرنےمیں کار فرماہے۔اسی نےسورج، چاند اور ستاروں کو پیدا کیا جو اس کے حکم کےمطابق کام میں لگےہوے ہیں۔ جان لو اور خبردار رہو، اسی کی تخلیق ہے اور اسی کا حکم اللہ جو پوری دنیا کا رب ہے بہت برکت والاہے\"۔\n۲- ﴿قُلِ ٱللَّهُمَّ مَٰلِكَ ٱلۡمُلۡكِ تُؤۡتِي ٱلۡمُلۡكَ مَن تَشَآءُ وَتَنزِعُ ٱلۡمُلۡكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُۖ بِيَدِكَ ٱلۡخَيۡرُۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ‏﴾ [آل عمران: ۲۶] \"کہو: اے اللہ تمام جہان کے مالک! تو جسے چاہے حکمرانی عطا کرے اور جس سے چاہے چھین لےاور جسےچاہےعزت بخشے اور جسے چاہے بے عزت کرے۔ تیرے ہی ہاتھ میں بھلائی ہے۔بےشک تجھے ہر چیز کی پوری قدرت ہے\"۔\nاللہ تعالیٰ قرآن مجیدمیں کہتا ہے کہ پوری کائنات کی تخلیق کرنے والا تو میں ہوں۔ اس میں میرا کوئی شریک نہیں ہے۔بتاؤ دوسروں نےکیا پیدا کیا ہے! ﴿هَٰذَا خَلۡقُ ٱللَّهِ فَأَرُونِي مَاذَا خَلَقَ ٱلَّذِينَ مِن دُونِهِۦۚ بَلِ ٱلظَّٰلِمُونَ فِي ضَلَٰلࣲ مُّبِينࣲ‏﴾ [لقمان: ۱۱] \"یہ (پوری دنیا) اللہ کی بنائی ہوئی ہے۔اب ذرا مجھے دکھاؤ جو کچھ کہ دوسروں نے بنایا ہے۔نہیں بلکہ یہ گمراہ کھلی گمراہی میں پڑے ہوے ہیں\"۔\nیہ توحید جس کو ہم ایک اللہ پر ایمان رکھنا کہتے ہیں۔حقیقت میں ہماری فطرت میں بسی ہے۔کیونکہ جب اللہ نے آدم کو پیدا کیا تو اسی وقت اس نے ہماری روحوں سے یہ قسم لے لی تھی کہ میں ہی تمھارا رب اورحقیقی معبودہوں اور پھر اس نے دنیا میں اپنے خالق ہونے کی بے شمارنشانیاں چھوڑدیں،جن کو دیکھ کر ہرشخص آسانی کےساتھ رب عزوجل کےخالق ہونے کی گواہی دےسکتا ہے۔یہی وجہ ہے کہ مکہ میں مخالفین اسلام سے جب پوچھا گیا:﴿وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ لَيَقُولُنَّ ٱللَّهُۚ قُلِ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ﴾ [لقمان: ۲۵] \"آسمانوں اور زمین کو کس نے پیدا کیا تو وہ بول پڑے:اللہ نے۔کہوساری تعریفیں اللہ کے لیے ہیں، لیکن ان میں زیادہ تر لوگ اس بات کو نہیں جانتے\"۔\nاوراگرکسی نے اس کےرب ہونے کا انکار کیا تو یہ صرف اس کے بھٹکے ہوے خیال ہیں،حقیقت میں وہ اپنےدل سے کبھی اس کا انکار نہیں کرسکتا۔قرآن کریم انھی لوگوں کی طرف اشارہ کرتے ہوے کہتا ہے: ﴿وَجَحَدُواْ بِهَا وَٱسۡتَيۡقَنَتۡهَآ أَنفُسُهُمۡ ظُلۡمࣰ ا وَعُلُوࣰّ اۚ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ﴾ [النمل: ۱۴] \"اس لیے انھوں نے گمراہی اورغرور کے سبب اس کاانکار کردیا۔ حالانکہ ان کے دل اس کا یقین کرچکے تھے۔ تو دیکھو ان فسادیوں کا انجام کیا ہوا\"۔\nپھر قرآن کریم ایسے لوگوں سے سوال کرتا ہے :﴿أَمۡ خُلِقُواْ مِنۡ غَيۡرِ شَيۡءٍ أَمۡ هُمُ ٱلۡخَٰلِقُونَ أَمۡ خَلَقُواْ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۚ بَل لَّا يُوقِنُونَ﴾ [الطور: ۳۵-۳۶] \"کیا یہ لوگ کسی (پیداکرنے والے) کےبغیر خود ہی پیدا ہوگئے ہیں؟ یا وہ خود پیدا کرنے والے ہیں؟ یا انھوں نے آسمانوں اور زمین کو پیدا کیا؟ نہیں!بلکہ یہ لوگ یقین نہیں کرتے\"۔\nعرب کی ثقافت میں یہ ضرب المثل بہت مشہور ہے کہ ایک بدو (اونٹ چرانے والا) کہتا ہے کہ اونٹ کی مینگنی اس کے وجود کا ثبوت ہے اور اس کے پیروں کے نشان راہ دکھاتے ہیں تو کیا یہ برجوں والاآسمان اور پھیلی ہوئی زمین اللہ کے وجود کا ثبوت نہیں ہے۔\nاللہ تعالیٰ نے قرآن کریم میں اپنی ربوبیت اورقدرت وکمالات کاتذکرہ جگہ جگہ تفصیلی طورپرکرکے انسانوں کواس بات کی طرف دعوت دی ہے کہ صرف اللہ تعالیٰ کی ذات ہی عبادت کے لائق ہے، ساری مخلوقات اس کا گن گاتی اور اس کی پاکی بیان کرتی ہے، اس لیے توحیدربوبیت کو صحیح طورپر سمجھنے کا لازمی نتیجہ صرف ایک اللہ کی عبادت ہےاوراس کے ساتھ مخلوق کی شرکت اورساجھی داری کا کھلم کھلا انکارواعتراف ہے، یہی وجہ ہے کہ جگہ جگہ قرآن کریم میں آتاہےکہ اے انسانو! اس رب کی عبادت کرو جس نے تم پیدا کیاہے، گویاربوبیت کےاعتراف اور اس پر ایمان کا لازمی تقاضایہ ہے کہ آدمی صرف اللہ تعالیٰ کی عبادت کرے اور اس کے ساتھ شرک کی ہرصورت سے دور ہو۔\nتوحیدربوبیت میں شرک: ربوبیت میں شرک یہ ہےکہ اللہ تعالیٰ کے افعال میں سے کسی چیز کو غیراللہ کے خاص کیا جائے اس کی دوقسمیں ہیں: ایک شرک تعطیل یعنی ربوبیت کے خصائص کا انکار اور اللہ تعالیٰ کے رب العالمین ہونے کا انکار، فرعون کا شرک اسی قبیل کا تھا، جس کا تذکرہ اللہ تعالیٰ نے قرآن مجیدمیں اس طرح کیاہے :\n۱-﴿وَقَالَ فِرۡعَوۡنُ يَٰٓأَيُّهَا ٱلۡمَلَأُ مَا عَلِمۡتُ لَكُم مِّنۡ إِلَٰهٍ غَيۡرِي فَأَوۡقِدۡ لِي يَٰهَٰمَٰنُ عَلَى ٱلطِّينِ فَٱجۡعَل لِّي صَرۡحࣰ ا لَّعَلِّيٓ أَطَّلِعُ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُۥ مِنَ ٱلۡكَٰذِبِينَ﴾ [القصص: ۳۸] \"فرعون کہنے لگا: اے درباریو! میں تو اپنے سوا کسی کو تمھارا معبود نہیں جانتا۔ سن اے ہامان! تو میرے لیے مٹی کو آگ سے پکوا پھر میرے لیے ایک محل تعمیر کر تو میں موسیٰ کے معبود کو جھانک لوں اسے میں جھوٹوں میں سے ہی گمان کر رہا ہوں\"۔\n۲-﴿وَقَالَ فِرۡعَوۡنُ يَٰهَٰمَٰنُ ٱبۡنِ لِي صَرۡحࣰ ا لَّعَلِّيٓ أَبۡلُغُ ٱلۡأَسۡبَٰبَ أَسۡبَٰبَ ٱلسَّمَٰوَٰتِ فَأَطَّلِعَ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُۥ كَٰذِبࣰ اۚ وَكَذَٰلِكَ زُيِّنَ لِفِرۡعَوۡنَ سُوٓءُ عَمَلِهِۦ وَصُدَّ عَنِ ٱلسَّبِيلِۚ وَمَا كَيۡدُ فِرۡعَوۡنَ إِلَّا فِي تَبَابࣲ‏﴾ [غافر: ۳۶-۳۷] \"فرعون نے کہا اے ہامان! میرے لئے ایک بالا خانہ بنا شاید کہ میں آسمان کے جو دروازے ہیں(ان) دروازوں تک پہنچ جاؤں اور موسیٰ کے معبود کو جھانک لوں اور بیشک میں سمجھتا ہوں وہ جھوٹا ہے\"۔\n۳- ﴿وَجَحَدُواْ بِهَا وَٱسۡتَيۡقَنَتۡهَآ أَنفُسُهُمۡ ظُلۡمࣰ ا وَعُلُوࣰّ اۚ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ﴾ [النمل: ۱۴] \"اس لیے انھوں نے گمراہی اور غرور کےسبب اس کاانکار کردیا۔حالانکہ ان کے دل اس کا یقین کرچکے تھے۔تو دیکھو ان فسادیوں کا انجام کیا ہوا\"۔\nصوفیوں کا ایک غالی فرقہ وحدۃ الوجود کے عقیدے کا قائل ہے، اس کا شرک یہ ہے کہ وہ خالق کو عین مخلوق مانتے ہیں اوررب اوربندے کے درمیان فرق نہیں کرتے، یہ تمام موجودات کواللہ تعالیٰ کا ایک وجودمانتے اورماسوا اللہ کے وجود کو محض اعتباری سمجھتے ہیں۔\nشرک تمثیل: تمثیلی شرک یہ ہے کہ ربوبیت کے خصائص وامتیاز میں سے کسی چیز میں مخلوق کو خالق کےبرابر قراردیاجائےیاربوبیت کے خصائص وامتیازات کی غیراللہ کی طرف نسبت کی جائے، قبرپرستوں کا شرک یہی ہے کہ وہ اولیااور بزرگوں کی ارواح کے بارے میں یہ گمان کرتے ہیں کہ یہ موت کے بعد تصرف کرتی ہیں اور لوگوں کی حاجات پوری کرتی ہیں اور ان کی مشکلات کوحل کرتی ہیں۔\n۲- توحیداسماءوصفات: توحیدکی دوسری قسم توحید اسماء و صفات ہے۔ اس کا مطلب یہ ہےکہ اللہ تعالیٰ کو اس کے ان ناموں اورصفات وخصوصیات میں ایک ماننا جو اس کے لیےقرآن و حدیث میں آئے ہیں اور ان میں کسی کوشریک نہ کرنا اور نہ اللہ سے کسی کی برابری کرنا۔بس جو نام اللہ نے اپنے لیے استعمال کیے ہیں اور رسولوں نے جو نام اس کے لیے استعمال کیے ہیں ان کو اسی طرح بغیر تاویل وتحریف کے قبول کر لینا۔ اسی طرح اللہ تعالیٰ نے اپنے لیے جوصفات وخصوصیات بتائی ہیں یا رسول اللہ صلی اللہ علیہ وسلم نے جو صفات وخصوصیات اللہ تعالیٰ کے لیے بتائی ہیں، ان کو بنا کسی ردوبدل اور تحریف کے قبول کرنا توحید اسماء وصفات کہلاتا ہے۔قرآن مجیدمیں اللہ نے اپنے بارے میں فرمایا ہے: ﴿فَاطِرُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجࣰ ا وَمِنَ ٱلۡأَنۡعَٰمِ أَزۡوَٰجࣰ ا يَذۡرَؤُكُمۡ فِيهِۚ لَيۡسَ كَمِثۡلِهِۦ شَيۡءࣱۖ وَهُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ﴾ [الشوری: ۱۱] \"وہ(اللہ)آسمانوں اور زمین کا پیدا کرنے والا ہے،اس نے تمھارے لیےتمھاری اپنی جنس کے جوڑے بنائے اور چوپائے کے جوڑے بھی۔ وہ تمھیں اسی طرح پھیلاتا اور بڑھاتا ہے۔ اس جیسا کوئی نہیں اور وہ سمیع وبصیر(بڑا سننے والا اور دیکھنے والا) ہے\"۔\nاللہ تعالیٰ کے وجود اوراس کی صفات وخصوصیات میں کسی کی مثال نہیں دی جا سکتی۔اس کا کوئی شریک نہیں، اس جیسا کوئی نہیں۔ قرآن مجیدمیں ہے: ﴿وَلِلَّهِ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ فَٱدۡعُوهُ بِهَاۖ وَذَرُواْ ٱلَّذِينَ يُلۡحِدُونَ فِيٓ أَسۡمَٰٓئِهِۦۚ سَيُجۡزَوۡنَ مَا كَانُواْ يَعۡمَلُونَ﴾ [الأعراف: ۱۸۰] \"اور اچھے اچھے نام اللہ ہی کے لیے ہیں، تو تم انھیں کےذریعے اسے یاد کرو اور ان لوگوں کو چھوڑ دو جو اس کے ناموں کے بارے میں کج روی اختیار کرتے ہیں۔ وہ جو کچھ وہ کرتے ہیں اس کا پھل وہ بہت جلد پائیں گے\"۔\nرب عزوجل کااسم ذاتی تو صرف ایک \"اللہ\" ہے، لیکن اس کے صفاتی نام بے شمار ہیں۔اس لیے اکثر علما کا خیال ہے کہ اللہ تعالیٰ کے ناموں اور صفات کے صحیح شمار کا علم صرف اللہ ہی کو ہے،ان میں سے کچھ نام ہمیں اللہ تعالیٰ نے بتادیے ہیں۔\nاسماءوصفات میں شرک کا مطلب یہ ہے کہ اللہ تعالیٰ کے ناموں اور صفتوں میں سے کسی کو مخلوق کے لیے صرف کیا جائے۔اس کی تین قسمیں ہیں: شرک تمثیل، شرک تعطیل، شرک انداد۔شرک تمثیل کا مطلب یہ ہے کہ مخلوق کی صفات کی طرح اللہ کے لیے صفات کو ثابت کیاجائے اورشرک تعطیل یہ ہےکہ خالق عزوجل کو اس کے فضل وکمالات سے معطل کردیاجائے جیسے غالی جہمی فرقے کے لوگوں نے اللہ تعالیٰ کے اسماءوصفات کا انکارکردیااورشرک انداد یہ ہے کہ اللہ تعالیٰ کی صفات کو مخلوق کے لیے ثابت کیاجائے۔\nاسماءوصفات باری تعالیٰ میں شرک کی مختلف صورتیں ہیں،شرک کی ایک صورت اللہ تعالیٰ کے ناموں سےباطل معبودوں کے نام کااشتقاق ہے۔ جیسےعرب کے بت پرستوں نے اللہ کے نام عزیز سے عزّی نامی بت بنالیا اور اس کی عبادت کرنے لگے۔ اسی طرح اللہ کے ناموں میں منان ہےجس سےبت پوجنے والوں نے منات نامی بت بنالیا اور اس کی عبادت کرنے لگے۔\nبعض گمراہ فرقوں کا بعض مردوں اورزندوں کے بارے میں یہ اعتقاد کہ وہ ان کی پکارکوہرجگہ اور ہروقت سنتے ہیں۔\nاللہ تعالیٰ کومخلوق سے تشبیہ دیناجیسے یہ کہناکہ میراہاتھ اللہ کے ہاتھ کی طرح ہےیامیرا سننا اللہ کے سننے کی طرح ہے یا میرا استوااللہ کےاستواکی طرح ہے۔یہ ساری صورتیں شرک باللہ کی ہیں۔اللہ تعالیٰ کا ارشادہے: ﴿كَمِثۡلِهِۦ شَيۡءࣱۖ وَهُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ﴾ [الشوری: ۱۱] \" اس (اللہ)جیسا کوئی نہیں اور وہ سمیع وبصیر(بڑا سننے والا اور دیکھنے والا) ہے\"۔\nکسی انسان کے حق میں علم غیب کادعویٰ یایہ اعتقاد کہ غیراللہ کے پاس علم غیب ہے۔یہ بھی شرک ہے۔ہروہ چیز جس سےمخلوق آگاہ نہیں ہے اورحواس خمسہ کے ذریعے سے بھی وہ چیزنہیں جانی جاسکتی اسےعلم غیب کہتے ہیں۔اس لیےکسی مخلوق کے بارے میں علم غیب کا دعویٰ آدمی کو شرک اکبرمیں ڈالنے والاہے،جودین اسلام سےخارج کرنے والی چیزہے۔اس لیے کہ اس میں اللہ تعالیٰ کی صفت علم غیب میں مخلوق کی مشارکت کادعویٰ ہےاورعلم غیب کے دعوے سے شرک کی مثالوں میں سے یہ اعتقادہےکہ انبیاورسل یابعض صلحاءعلم غیب کوجانتے ہیں، یہ شرک غالی صوفیوں اورغالی شیعوں کے یہاں پایاجاتاہے۔یہی وجہ ہے کہ وہ گزرے ہوے انبیاوصالحین سےمددمانگتے اوراُن کو پکارتےہیں اور اُن کو اس بات کا اعتقادہوتاہےکہ یہ لوگ ان کے حالات کو جانتے اور ان کی باتوں کو سنتے ہیں۔یہ ساری باتیں شرک اکبر ہیں اوراس سے آدمی مرتداوردین سے خارج ہوجاتاہے۔\nاسی طرح اللہ کی صفات وخصوصیات میں سے ایک یہ ہے کہ وہی پیدا کرتا ہے،وہی رزق اور دیگر نعمتیں دیتا ہے۔ وہی مارتا اور زندہ کرتا ہے۔ان صفات وخصوصیات کو اللہ کے سوا کسی اور کے ساتھ جوڑنا شرک ہے۔\nہندستان میں ہندوؤں کے اعتقادکے مطابق مختلف دیوتا ایک ہی دیو کی مختلف شکلیں ہیں۔لیکن نادان لوگ ہر دیوتا کو اللہ کی شکل دے کر اس کی پوجا اور عبادت کرنے لگے۔ اس طرح بہت سارے دیوی دیوتاؤں کا رواج ہندستانی تہذیب میں شامل ہوگیا۔ اندر،ورن، وشنو اور پرجاپتی وغیرہ دیوتا اور اللہ بن بیٹھے،پھر ان کی پوجا ہونے لگی۔ رگ وید سے لےکر اپنشد اور مہابھارت کا ایک برہما جو مختلف خوبی والا ہے، وحدانیت کا مظہر اور علامت بن گیا۔ قرآن مجیدہی اللہ کی تنہا کتاب ہے،جس نے توحید کو واضح طور سے بیان کیا ہےاور جہاں بھی شرک ہونے کا شبہ ہوا فوراً خبردار کیا۔ تاکہ زمین پر ایک اللہ کو چھوڑ کر کسی اور کی عبادت نہ کی جائے اور یہ دنیا کبھی توحید والوں سے خالی نہ ہو۔ اس بارے میں مختلف جگہوں پر ذکر کیا گیا ہے۔ یہاں توصرف توحید کی تین قسمیں بیان کی گئی ہیں۔\nامت اسلامیہ میں بھی توحید اسماء وصفات کے بارے میں گمراہیاں وجود پذیر ہوئیں۔ کسی نے تو ان کا بالکلیہ انکار کردیا۔جیسے معطلہ اور کسی نے کچھ کا اقرار کیا اور کچھ کا انکار کردیا یا خوبصورت تاویل کرلی۔ جیسےاشاعرہ اور ماتریدیہ اور کچھ نےاللہ کے ان اسما وصفات کو بالکل انسانوں کے اسماء وصفات کے مشابہ قرار دے دیا۔ جیسے مشبّہہ اور کچھ نے ان اسما وصفات کو اللہ کے لیے خاص مانا مگر ان کے ظاہری معانی ومطالب اللہ کے حوالے کردیے جیسے مفوّضہ۔ صحابہ کرام اور سارے سلف کا اس بار میں صحیح مسلک یہ ہے کہ ان کے ظاہری معانی ومطالب بھی ہمیں معلوم ہیں۔ مگر یہ اللہ کے لیےاسی کی شان وجلالت کے اعتبار سے ثابت ہیں۔ نہ تو ان کا انکار کرنا ہے اور نہ ان کا انسانوں کے مشابہ قرار دینا ہے۔ (کتب عقائد سلفیہ)\n۳- توحید الوہیت:توحیدکی تیسری قسم توحید الوہیت ہے۔اس کےمعنی یہ ہیں کہ صرف اللہ تعالیٰ ہی عبادت کے لائق ہے۔ کسی اور کی عبادت کرنا سب سے بڑا گناہ ہے،جس کو شرک کہتے ہیں۔ اس برے کام کو اللہ ہرگز معاف نہیں کرتا۔انبیاورسل کی تعلیمات کاخلاصہ اورمقصد یہی توحیدالوہیت ہے۔قرآن مجیدمیں ہے:\n۱- ﴿وَلَقَدۡ بَعَثۡنَا فِي كُلِّ أُمَّةࣲ رَّسُولًا أَنِ ٱعۡبُدُواْ ٱللَّهَ وَٱجۡتَنِبُواْ ٱلطَّٰغُوتَۖ فَمِنۡهُم﴾ [النحل: ۳۶] \"ہم نے ہر قوم میں کوئی نہ کوئی رسول بھیجا کہ لوگو! صرف اللہ کی عبادت کرو اور طاغوت کی عبادت سے بچو\"۔\n۲- ﴿وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٍ إِلَّا نُوحِيٓ إِلَيۡهِ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدُونِ﴾ [الأنبیاء: ۲۵] \"ہم نے تم سے پہلے جو رسول بھی بھیجے ان سب کی طرف یہی وحی کی کہ میرے سوا کوئی سچا معبود نہیں تو تم صرف میری ہی عبادت کرو\"۔\nنوح،ہود، صالح، شعیب،موسیٰ،عیسیٰ علیہم السلام اور محمد صلی اللہ علیہ وسلم سبھی نبیوں اوررسولوں نے اپنی اقوام کو سب سے پہلے اسی توحیدالوہیت وعبادت کی دعوت دی تھی۔قرآن مجیدمیں ہے:\n۱- ﴿لَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظِيمࣲ‏﴾ [الأعراف: ۵۹] \"ہم نے نوح کو اس کی قوم کی طرف بھیجا تو اس نے کہا: اے میری قوم! صرف ایک اللہ کی عبادت کرو اس کے سوا تمھارا کوئی معبود(عبادت کے لائق رب)نہیں (اگر تم نے ایسا نہ کیا)تو تمھارے لیےایک بڑے دن کے عذاب سے ڈرتا ہوں\"۔\n۲- ﴿وَإِلَىٰ عَادٍ أَخَاهُمۡ هُودࣰ اۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ﴾ [الأعراف: ۶۵] \"اور عاد کی طرف ان کے بھائی ہود کو بھیجا اس نے کہا: اے میری قوم! صرف اللہ کی عبادت کرو اس کے سوا کوئی معبودبرحق نہیں، کیا تم ڈرتے نہیں\"۔\n۳- ﴿وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحࣰ اۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةࣱ مِّن رَّبِّكُمۡۖ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةࣰۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءࣲ فَيَأۡخُذَكُمۡ عَذَابٌ أَلِيمࣱ‏﴾ [الأعراف: ۷۳] \"اور ثمود کی طرف اس کے بھائی صالح کو بھیجا، اس نے کہا: اے میری قوم! صرف اللہ کی عبادت کرو اس کے سوا تمھارا کوئی معبودبرحق نہیں\"۔\nیہی توحیدالوہیت وتوحید عبادت تمام انبیاورسل کی دعوت کی بنیادی تعلیم تھی، کیونکہ ہمارے اعمال کا دارو مدار اسی توحید پر ہے۔ اگر توحید نہ رہے گی تو شرک پیدا ہوگا، جو سارے اعمال کو برباد کردے گا۔ قرآن مجیدمیں ہے: ﴿وَلَقَدۡ أُوحِيَ إِلَيۡكَ وَإِلَى ٱلَّذِينَ مِن قَبۡلِكَ لَئِنۡ أَشۡرَكۡتَ لَيَحۡبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ﴾ [الزمر: ۶۵] \"اور بےشک تمھاری طرف اور ان کی طرف جو تم سے پہلے تھے یہ وحی کی جاچکی ہے کہ اگر تم نے شرک کیا تو تمھارے سارے اعمال بےکار ہوجائیں گے اور یقیناً ہی تم نقصان اٹھانے والوں میں ہوجاؤ گے\"۔\nتوحید الوہیت میں شرک یہ ہےکہ اللہ تعالیٰ کے افعال میں سے کسی چیزکو غیراللہ کے لیے ثابت کیاجائے۔ اس کی کئی قسمیں ہیں:\n۱- دعاکاشرک: غیراللہ کو ایسی چیزمیں مدد کے لیے پکارنا، جس پر اللہ تعالیٰ کے لیے علاوہ کوئی اورقادر نہیں ہے۔\n۲- شفاعت (سفارش) کاشرک: باطل معبودوں سےتقرب حاصل کرنا اس اعتقادکے ساتھ کہ یہ اللہ تعالیٰ کے یہاں شفاعت کریں گے اور اس سے قربت کا سبب بنیں گے۔\n۳- نیت، قصداورارادے کا شرک: آدمی عبادت کا کام کرتاہے، لیکن وہ یہ کام ریاکاری میں کرتاہے یا دنیاوی مقصداورمنفعت کاحصول اسے سامنے ہوتاہے، یہ عمل مومن کامل سے نہیں صادر ہوتاہے۔واضح رہے کہ ریاونمود کےلیے کوئی دینی کام کرنا، اس طورپر کہ آدمی اصل آدمی عبادت واطاعت کا کام دنیاوی مقاصدکے لیے کرے، اللہ کے لیے نہ ہوتو یہ شرک اکبرہےاوراگرآدمی عبادت کا کام کررہا ہو اور درمیان میں ریاونمودکا جذبہ پیدا ہوجائے اور لوگوں کو دکھانے کے لیے اس کام کو عمدہ طریقے پر اداکرنے لگے تو یہ شرک اصغرہے۔\n۴- اطاعت کا شرک: آدمی اللہ تعالیٰ کے سواکسی اور کو شارع اورقانون ساز بنالے یا قانون سازی میں ماسوا اللہ کو شریک کرلے اور اس کے فیصلے پر راضی ہو اورحرام وحلال میں اس کو اپنا مرجع بنائے۔\n۵- محبت کاشرک : مخلوق میں سے کسی کو آدمی اللہ کا شریک بنائےاوران سے ایسی محبت کرے جیسے اللہ سے کی جاتی ہےاوران کی اطاعت کو اللہ تعالیٰ کی اطاعت پر ترجیح دے اور زبان پران کاذکرجاری رکھے اورانھیں پکارے۔\n۶- خوف کا شرک: غیراللہ سے اس طرح ڈرناکہ وہ ان چیزوں میں اثرانداز ہوگا یا اس کو پالے گا جس پراللہ تعالیٰ کے علاوہ کوئی دوسرا قادرنہیں ہے۔\n(اورشرک میں بعض صورتیں شرک اکبرکی ہیں اوربعض صورتیں شرک اصغرکی۔شرک اکبریہ ہےکہ اللہ کےحقوق کوغیراللہ کے لیے ثابت کیاجائے اورشرک اصغرکی تعریف کے بارے میں علماء کے مابین بڑا اختلاف ہے، بعض لوگوں نے اس کی یہ تعریف کی ہے کہ اللہ کے کسی حق کو ماسوااللہ کے ثابت کیاجائے لیکن اس سے بندہ دین سے نہ خارج ہو۔ایک تعریف یہ بھی کی گئی ہے کہ نصوص کتاب وسنت میں جس کو شرک کہا گیاہو، لیکن وہ شرک خارج عن الملۃ کے درجے تک نہ پہنچتاہو، جیسے: ریا)۔","",{}],[177,"§تورات\nتورات سے مراد یہودیوں اور عیسائیوں کی تاریخ میں مذکور بائبل کی درج ذیل پانچ کتابیں ہیں:\n۱- پيدایش(GENESIS)\n۲- خروج(EXODUS)\n۳- احبار(LEVITICUS)\n۴- تعداد(NUMBERS)\n۵- استثناء(DEUTERONOMY)\nعلماےاہل کتاب کا خیال ہےکہ عہد عتیق (OLDTESTAMENT) کی یہ پانچ کتابیں موسیٰ علیہ السلام پر اللہ کی طرف سے نازل کی گئی ہیں۔ لیکن ان کتابوں کے مطالعے سے معلوم ہوتا ہے کہ یہ خیال صحیح نہیں ہے۔ کیونکہ ان میں کہیں کہیں ان تاریخی واقعات کا ذکر بھی آگیا ہے، جو موسیٰ علیہ السلام کے بعد واقع ہوےہیں۔ جیسے: کتاب استثناکے آخر میں موسیٰ علیہ السلام کی وفات کا ذکر۔اس سے ظاہرہوتا ہےکہ یہ کتاب موسیٰ علیہ السلام پر نہیں اتری، بلکہ بعد میں کسی شخص نے لکھ کر اس میں شامل کردی۔ اس لیے اب بعض علما یہ کہنے لگے ہیں کہ تورات سے مراد وہ دس الہی پیغام اور احکام ہیں جو پتھر کی تختی پرلکھ کر موسیٰ علیہ السلام کودیےگئے اور پھر چالیس سال تک موسیٰ علیہ السلام کو جو پیغام اللہ کی طرف سے دیے گئے وہ سبھی عہد عتیق میں پھیلے ہوے ہیں۔یہی وجہ ہے کہ قرآن کریم نے کہیں بھی ان پانچ کتابوں کی گواہی نہیں دی ہے۔ وہ صرف یہ کہتا ہے کہ ہم نے موسیٰ اور ہارون کو کتاب دی:\n۱- ﴿وَءَاتَيۡنَٰهُمَا ٱلۡكِتَٰبَ ٱلۡمُسۡتَبِينَ﴾ [الصافات: ۱۱۷] \"ہم نے ان دونوں (موسیٰ اورہارون) کو ظاہر کتاب دی\"۔\n۲- ﴿وَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓ إِذۡ قَالُواْ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرࣲ مِّن شَيۡءࣲۗ قُلۡ مَنۡ أَنزَلَ ٱلۡكِتَٰبَ ٱلَّذِي جَآءَ بِهِۦ مُوسَىٰ نُورࣰ ا وَهُدࣰ ى لِّلنَّاسِۖ تَجۡعَلُونَهُۥ قَرَاطِيسَ تُبۡدُونَهَا وَتُخۡفُونَ كَثِيرࣰ اۖ وَعُلِّمۡتُم مَّا لَمۡ تَعۡلَمُوٓاْ أَنتُمۡ وَلَآ ءَابَآؤُكُمۡۖ قُلِ ٱللَّهُۖ ثُمَّ ذَرۡهُمۡ فِي خَوۡضِهِمۡ يَلۡعَبُونَ﴾ [الأنعام: ۹۱] \"کہو! وہ کتاب کس نے اتاری،جس کو لےکر موسیٰ آئے،جس میں لوگوں کے لیے روشنی اوررہنمائی ہے جسے تم الگ الگ صفحات کی شکل میں رکھتے ہو، جنھیں تم دکھاتے ہو، لیکن بہت کچھ چھپاتے ہو\"۔\nصرف اسی کتاب کا نام تورات ہے، جس کا قرآن مجیدمیں باربارذکر آیا ہے اور اس نے کئی جگہ پر اشارہ کیا ہے کہ یہودی علما نے تورات میں کس طرح تحریف اور ردوبدل کا کام کیا۔لیکن اب بھی اس میں کلام الہی کے کچھ ٹکڑے موجود ہیں،جن کو قرآن مجیدنے نور اور ہدایت کہا ہے اور انھی جگہوں کی گواہی دیتاہے۔نہ کہ ان پانچ کتابوں کی جن کو یہودی اور عیسائی موسی علیہ السلام سےمنسوب کرتے ہیں۔چونکہ قرآن کریم اللہ تعالیٰ کی نازل کردہ آخری کتاب ہے، اس لیے جو کچھ بھی اس کے خلاف اورمتعارض ہے سب بے بنیاداورقابل رد ہے۔\nباقی چونتیس(۳۴)کتابیں جو عہد عتیق میں پائی جاتی ہیں، ان کے بارے میں تو خود یہودی اورنصرانی علمابھی اس بات پر متفق ہیں کہ یہ مختلف اوقات میں لکھی گئی تھیں۔’عزراکاہن‘ نے سب کو ایک جگہ جمع کر دیا۔چونتیس کتابیں یہ ہیں:\nیشوع، قضاة، روت،سموئیل۱، سموئیل۲، سلاطین۱، سلاطین۲، تواریخ۱، تواریخ۲، عزرا، نحمیاہ، آستر، ایوب، زبور،امثال، واعظ، غزل الغزلات، یسعیاہ، یرمیاہ، نوحہ، حزقی ایل، دانی ایل، ہوسیع، یو ایل، عاموس، عبدیاہ، یوناہ، میکاہ، ناحوم، حبقوق، صفنیاہ، حجی، زکریاہ، ملاکی۔اس طرح پہلی پانچ کتابوں کو ملانے سے عہد عتیق کی کل تعدادانتالیس ہوتی ہے۔","",{}],[178,"§تيمم\nتیمم: وضو کا بدل ہے۔ اگر پانی نہ ہو یا کسی وجہ سے پانی استعمال نہ کیا جاسکتا ہو تو تیمم کرکے نماز ادا کی جائے گی۔ جیسا کہ قرآن مجیدمیں آیا ہے:﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قُمۡتُمۡ إِلَى ٱلصَّلَوٰةِ فَٱغۡسِلُواْ وُجُوهَكُمۡ وَأَيۡدِيَكُمۡ إِلَى ٱلۡمَرَافِقِ وَٱمۡسَحُواْ بِرُءُوسِكُمۡ وَأَرۡجُلَكُمۡ إِلَى ٱلۡكَعۡبَيۡنِۚ وَإِن كُنتُمۡ جُنُبࣰ ا فَٱطَّهَّرُواْۚ وَإِن كُنتُم مَّرۡضَىٰٓ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَآءَ أَحَدࣱ مِّنكُم مِّنَ ٱلۡغَآئِطِ أَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ فَلَمۡ تَجِدُواْ مَآءࣰ فَتَيَمَّمُواْ صَعِيدࣰ ا طَيِّبࣰ ا فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُم مِّنۡهُۚ مَا يُرِيدُ ٱللَّهُ لِيَجۡعَلَ عَلَيۡكُم مِّنۡ حَرَجࣲ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمۡ وَلِيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ﴾ [المائدة: ۶] \"اے ایمان والو! جب تم نماز کے لیے اٹھو تو اپنے منہ اور اپنے ہاتھوں کوکہنیوں سمیت دھولو اور اپنے سروں کا مسح کرو اور اپنے پاؤں کوٹخنوں سمیت دھولو اور اگر تم جنابت کی حالت میں ہو تو غسل کرو اوراگر بیمار ہویا سفر میں ہویا تم میں سے کوئی بیت الخلاء سے آیا ہےیا تم نے عورت کو ہاتھ لگایا ہو (اس سے ہمبستری کی ہو) پھر پانی نہ پاؤ تو پا ک مٹی سے تیمم کرلو، اسے اپنے منھ اور ہاتھوں پر مسح کرلو، اللہ تعالی تمھیں کسی مشکل میں نہیں ڈالنا چاہتا۔ بل کہ اس کا ارادہ تمھیں پاک کرنے کااور تمھیں اپنی پھر پور نعمت دینے کا ہے، تاکہ تم شکر ادا کرتے رہو\"۔\nاحادیث میں تیمم کا جو طریقہ بیان ہوا ہے، اس سے معلوم ہوتاہے کہ ایک بار پاک مٹی پر اپنا ہاتھ مارے اور اسے منھ اور ہتھیلیوں پر پھیر لے۔\nجیساکہ قرآن کی مذکور بالا آیت سے ظاہر ہوتاہے،اس تیمم سے اسی طرح نمازادا کی جائے گی،جس طرح وضو سے اداکی جاتی ہے۔ خواہ نماز پڑھنے والے نے ہمبستری کی ہو یا وہ بیمار ہو اور پانی سے ڈرتا ہو کہ کہیں مرض بڑھ نہ جائے وغیرہ۔لیکن جب پانی مل جائے یا اس کے استعمال سے کوئی نقصان نہ ہو تو تیمم ختم ہوجاتا ہے۔پھر نماز کے لیے وضو کرنا لازم ہوجاتا ہے۔","",{}],[179,"§تین آدمی جن کی توبہ دیرسے قبول ہوئی\nدیکھیے: الثَّلاثَةِالَّذِينَ خُلِّفُوا","",{}],[180,"§تين\nانجیرجس کوعربی میں \"تین\"کہتے ہیں۔انجیرکےدرخت زیادہ ترشام اور فلسطین میں پائےجاتے ہیں۔یہ پانچ میٹر سے لےکر دس میٹر تک لمبےہوتے ہیں۔اس کی شاخیں زمین سے ہی پھلنے لگتی ہیں۔ کہاجاتا ہے کہ یہ ایسا درخت ہےجس کا پھل پتوں سے پہلے ہی نکل آتا ہے۔ انجیرکوتازہ اور خشک دونوں طریقوں سے کھایا جاتاہے۔حکماء اس کے ذریعے سے مختلف امراض کا علاج کرتے ہیں۔ خاص کر یہ معدے کے امراض میں بہت مفیدہے۔بائبل کے مطابق نبی یسعیاہ نے حزقیاہ کے زخموں کاعلاج اسی سے کیاتھا۔ (دیکھیے: کتاب بادشاہ:۲۰:۷)\nااللہ تعالیٰ انجیرکی انہیں خصوصیات کی بنا پر اس کی قسم کهاکر کہتا ہے:﴿وَٱلتِّينِ وَٱلزَّيۡتُونِ وَطُورِ سِينِينَ وَهَٰذَا ٱلۡبَلَدِ ٱلۡأَمِينِ لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِيٓ أَحۡسَنِ تَقۡوِيمࣲ‏﴾ [التین: ۱-۴] \"قسم ہے انجیر، زیتون اور طورسینا کی اور پرسکون شہر (مکہ)کی بےشک۔ہم نے انسانوں کوسب سے بہترین صورت میں پیدا کیا\"۔","",{}],[181,"§ٹڈی\nدیکھیے: جراد","",{}],[182,"§ثانی اثنین\nثانی اثنین سےمرادابو بکرصدیق رضی اللہ عنہ ہیں،جونبی اکرم صلی اللہ علیہ وسلم کے سب سے معززومکرم صحابی تھے۔ ان کانام بظاہرقرآن میں نہیں آیا ہے۔لیکن سورہ التوبہ میں ثانی اثنین (دومیں کا دوسرا) سے مراد ابو بکر صدیق رضی اللہ عنہ ہی ہیں: ﴿إِلَّا تَنصُرُوهُ فَقَدۡ نَصَرَهُ ٱللَّهُ إِذۡ أَخۡرَجَهُ ٱلَّذِينَ كَفَرُواْ ثَانِيَ ٱثۡنَيۡنِ إِذۡ هُمَا فِي ٱلۡغَارِ إِذۡ يَقُولُ لِصَٰحِبِهِۦ لَا تَحۡزَنۡ إِنَّ ٱللَّهَ مَعَنَاۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيۡهِ وَأَيَّدَهُۥ بِجُنُودࣲ لَّمۡ تَرَوۡهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُواْ ٱلسُّفۡلَىٰۗ وَكَلِمَةُ ٱللَّهِ هِيَ ٱلۡعُلۡيَاۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ﴾ [التوبة: ۴۰] \"اگرتم ان(نبی اکرم صلی اللہ علیہ وسلم )کی مدد نہ کرو توااللہ ہی نے ان کی مدد کی اس وقت جب کہ انھیں کافروں نے(دیس سے) نکال دیا تھا،دو میں سے دوسرا جب کہ وہ دونوں غار میں تھے، جب یہ اپنے ساتھی سے کہہ رہے تھے کہ غم نہ کر،االلہ ہمارے ساتھ ہے۔ پس جناب باری نے اپنی طرف سے تسکین اس پر نازل فرماکر ان لشکروں سے اس کی مددکی جنھیں تم نے دیکھا ہی نہیں۔ اس نے کافروں کی بات پست کردی اور بلند وعزیز تو االلہ کا کلمہ ہی ہے۔ االلہ عزیزوحکیم (غالب،حکمت والا)ہے\"۔\nمفسرین کااس بات پر اتفاق ہےکہ یہاں \"ثانی اثنین\" سے مراد ابوبکر صدیق ہیں۔ انھیں کو ثانی اثنین کہاگیا ہے۔کیوں کہ ہجرت کےوقت نبی اکرم صلی اللہ علیہ وسلم کے ساتھ صرف وہی تھے اور آپ کومعلوم تھا کہ مکہ کےاسلام دشمن ہمارا تعاقب کریں گے۔اس لیے دونوں نے غارثور میں پناہ لے لی۔تین روز تک اسی غار میں پوشیدہ رہے۔دشمن دونوں کوتلاش کرتے ہوے،اس غار کے دہانے تک آپہنچے۔ابوبکر رضی اللہ عنہ ڈرگئے کہ کہیں انھوں نے ان لوگوں کودیکھ لیاتو کیا ہوگا؟لیکن نبی اکرم صلی اللہ علیہ وسلم ذرا بھی خوفزدہ نہیں ہوے،اس لیے کہ آپ االلہ کے حکم سے ہی گھر سے نکلے تھے۔اس وقت آپ نے ابوبکر رضی اللہ عنہ کوتسلی دی کہ فکر مت کرو۔االلہ ہمارے ساتھ ہے۔پھر االلہ تعالیٰ نے دل سے خوف کو دور کرنے کے لیے آپ صلی اللہ علیہ وسلم پر سکینت نازل فرمائی۔\nسورہ توبہ کی آیت ۴۰ میں اسی واقعےکی جانب اشارہ ہے۔امرواقع یہ ہے کہ ابوبکر صدیق رضی اللہ عنہ اسلامی تاریخ میں دوکا دوسرا بن گئے۔چنانچہ نبی اکرم صلی اللہ علیہ وسلم نےاپنی حیات مبارکہ میں ہی انھیں اپنا خلیفہ بنانے کااشارہ دےدیا تھا۔ مسلمانوں نے آپ کی وفات کے بعد ابوبکر رضی اللہ عنہ کے ہاتھ پر بیعت کی۔\nاس طرح وہ مسلمانوں کے پہلے خلیفہ ہوے،وہ نبی اکرم صلی اللہ علیہ وسلم سےدوسال چھوٹے تھے۔ان کی وفات آپ کی وفات کے ٹھیک دوسال بعدہوئی۔اس طرح ان کی عمر وفات کے وقت آپ صلی اللہ علیہ وسلم کی عمر مبارک کے برابر تھی۔ان کو آپ کے پہلو میں حجرہ عائشہ میں دفن کیا گیا۔","",{}],[183,"§ثعبان\nدیکھیے: حیۃ","",{}],[184,"§الثَّلاثَةِ الَّذِينَ خُلِّفُوا\nسورہ التوبہ کی آیت ۱۱۸ میں ان تین صحابۂ کرام کا ذکر ہے،جن کی توبہ اللہ تعالیٰ نے غزوۂ تبوک (۹ھ)کے موقع پردیر سےقبول کی۔ان کے نام یہ ہیں : کعب بن مالک،ہلال بن امیہ اورمرارہ بن ربیع۔\nاس واقعے کو کعب بن مالک رضی اللہ عنہ نےبڑی تفصیل سےبیان کیاہے،جو صحیح مسلم میں یوں آیا ہے : \"میں تبوک کی جنگ میں پیچھے رہ گیا، جب کہ اس سے پہلے کسی بھی جنگ میں پیچھے نہیں رہا۔ تبوک کی جنگ کے وقت میں بالکل تندرست تھا۔ مجھے کسی طرح کی کوئی پریشانی نہیں تھی۔ صرف سستی کی وجہ سے میں شامل نہ ہوسکا یہاں تک کہ اللہ کےرسول تبوک سے واپس آگئے۔ پیچھے رہ جانے والے،جن کی تعداد اسی سے کچھ زیادہ تھی، مختلف طرح کے عذر (بہانے) لے کر آپ کی خدمت میں حاضر ہوئے جن کی طرف قرآن کریم نے اس طرح اشارہ کیا ہے: ﴿يَحۡلِفُونَ لَكُمۡ لِتَرۡضَوۡاْ عَنۡهُمۡۖ فَإِن تَرۡضَوۡاْ عَنۡهُمۡ فَإِنَّ ٱللَّهَ لَا يَرۡضَىٰ عَنِ ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ﴾ [التوبة: ۹۶] \"وہ تمھارے سامنے قسمیں کھائیں گے۔ تاکہ تم ان سے راضی ہوجاؤ۔ پس اگر تم ان سے راضی بھی ہوگئے تو اللہ کبھی بھی ایسے لوگوں سے راضی نہیں ہوگا، جو نافرمان ہیں\"۔اس لیے کعب بن مالک نے صاف بتادیا کہ اے اللہ کے نبی میرے پاس کوئی عذر نہیں ہے۔ اس پر آپ نے فرمایا کہ اس نے سچ کہا۔ اب جاؤ تمھارا فیصلہ اللہ کرے گا اور مسلمانوں کو حکم دے دیا کہ کوئی ان تین آدمیوں سےگفتگو اور سلام بھی نہ کرے اور اگریہ سلام کریں تو جواب بھی نہ دیا جائے۔ ہلال بن امیہ اور مرارہ بن ربیع نے تو اپنے آپ کو گھر میں بند کرلیا اورروتے رہے۔ جب کہ میں اِدھر اُدھر مدینہ کی گلیوں میں گھومتا پھرتا تھا اسی حالت میں چالیس دن گزر گئے تو ہماری بیویوں کو حکم ہوا کہ وہ بھی ہم سے دور ہوجائیں۔ گویاہم پر زندگی تنگ ہوگئی جیسا کہ قرآن نے بیان کیا ہے: ﴿وَعَلَى ٱلثَّلَٰثَةِ ٱلَّذِينَ خُلِّفُواْ حَتَّىٰٓ إِذَا ضَاقَتۡ عَلَيۡهِمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ وَضَاقَتۡ عَلَيۡهِمۡ أَنفُسُهُمۡ وَظَنُّوٓاْ أَن لَّا مَلۡجَأَ مِنَ ٱللَّهِ إِلَّآ إِلَيۡهِ ثُمَّ تَابَ عَلَيۡهِمۡ لِيَتُوبُوٓاْۚ إِنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ﴾ [التوبة: ۱۱۸] \"اور تین شخصوں کے حال پر بھی جن کا معاملہ ملتوی چھوڑ دیا گیا تھا یہاں تک کہ جب زمین باوجود اپنی فراخی کے ان پر تنگ ہونے لگی اور وہ خود اپنی جان سے تنگ آگئے اور انھوں نے سمجھ لیا کہ اللہ سے کہیں پناہ نہیں مل سکتی سواے اس کے کہ اسی کی طرف رجوع کیا جائے پھر ان کے حال پر توجہ فرمائی تاکہ وہ آیندہ بھی توبہ کرسکیں بےشک اللہ تعالیٰ بہت توبہ قبول کرنے والا بڑا رحم والا ہے\"۔میں اسی حالت میں تھا کہ غسان کے بادشاہ کا جو عیسائی تھا ایک خط آیا،اس نے مجھے یہ کہہ کر کہ تمھارے نبی نے تمھارے ساتھ بہت سخت برتاؤ کیا ہے، تم میرے پاس آجاؤ، بہت امن و سکون سے رہوگے،میں نے اس خط کو یہ کہہ کر آگ میں جلا دیا کہ یہ دوسرا امتحان ہے۔آخر جب پچاس دن گزرگئے تو اللہ تعالیٰ کی طرف سے ہماری توبہ کی قبولیت کا حکم آیا : ﴿لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِيِّ وَٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ ٱلَّذِينَ ٱتَّبَعُوهُ فِي سَاعَةِ ٱلۡعُسۡرَةِ مِنۢ بَعۡدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقࣲ مِّنۡهُمۡ ثُمَّ تَابَ عَلَيۡهِمۡۚ إِنَّهُۥ بِهِمۡ رَءُوفࣱ رَّحِيمࣱ وَعَلَى ٱلثَّلَٰثَةِ ٱلَّذِينَ خُلِّفُواْ حَتَّىٰٓ إِذَا ضَاقَتۡ عَلَيۡهِمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ وَضَاقَتۡ عَلَيۡهِمۡ أَنفُسُهُمۡ وَظَنُّوٓاْ أَن لَّا مَلۡجَأَ مِنَ ٱللَّهِ إِلَّآ إِلَيۡهِ ثُمَّ تَابَ عَلَيۡهِمۡ لِيَتُوبُوٓاْۚ إِنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ﴾ [التوبة: ۱۱۷-۱۱۸] \"اللہ نبی پر مہربان ہوگیا اور ان مہاجرین اور انصار پر بھی، جنھوں نے مشکل لمحات میں نبی کا ساتھ دیا۔ گرچہ ان میں سے ایک گروہ کا دل تزلزل کی طرف جھک جانے کے قریب تھا۔ پھر وہ ان پر مہربا ن ہوا۔ بےشک وہ ان لوگوں کےلیے رحمن اور رحیم ہے اور ان تینوں پر بھی (مہربان ہوگیا ) جو پیچھے چھوڑ دیے گئے تھے۔ یہاں تک کہ دنیا کشادہ ہوتے ہوئے بھی ان پر تنگ ہوگئی اور ان کی جانیں ان پر مشکل ہوگئیں۔ اور انھوں نےسمجھا کہ اللہ کی پکڑ سے بچنے کےلیے کہیں اور پناہ نہیں مل سکتی،مل سکتی ہے تو بس اسی کے یہاں تو وہ اپنی مہربانی سے ان کی طرف متوجہ ہوا، تاکہ وہ اس کی طرف پلٹ جائیں بےشک اللہ توبہ قبول کرنے والا رحم والاہے\"۔کعب بن مالک کا کہنا ہے کہ اللہ کی نعمتوں میں سے اسلام کے بعد یہ سب سے بڑی نعمت ہے کہ میں نے اللہ کے رسول کے سامنے سچ بولا اگر میں بھی جھوٹ بول جاتا تو ان دوسرے لوگوں کی طرح بھی برباد ہوجاتا جو جھوٹ بول کر برباد ہوئے، جن کو اللہ نے ناپاک کہا۔ (سورہ التوبہ :۹۵، صحیح البخاری: ۴۴۱۸ و صحیح مسلم : ۲۷۶۹) (مزید معلومات کے لیے دیکھیے : تبوک)","",{}],[185,"§ثواب\nثواب کا مطلب ہے بدلہ۔ یہ بدلہ اچھا بھی ہو سکتا ہے اور برا بھی۔ لیکن قرآن میں یہ لفظ صرف اچھے بدلے کے لیے استعمال ہوا ہے:﴿وَمَا كَانَ لِنَفۡسٍ أَن تَمُوتَ إِلَّا بِإِذۡنِ ٱللَّهِ كِتَٰبࣰ ا مُّؤَجَّلࣰ اۗ وَمَن يُرِدۡ ثَوَابَ ٱلدُّنۡيَا نُؤۡتِهِۦ مِنۡهَا وَمَن يُرِدۡ ثَوَابَ ٱلۡأٓخِرَةِ نُؤۡتِهِۦ مِنۡهَاۚ وَسَنَجۡزِي ٱلشَّٰكِرِينَ﴾ [آل عمران: ۱۴۵] \"دنیا کی چاہت والوں کو ہم کچھ دنیا دے دیتے ہیں اور آخرت کا ثواب چاہنے والوں کو ہم وہ بھی دیں گے اور احسان ماننے والوں کو ہم بہت جلد نیک بدلہ دے دیں گے\"۔\nاللہ تعالیٰ ان لوگوں کو جو اب تک ایمان نہیں لائے، خطاب کرکےفرماتا ہے:﴿وَلَوۡ أَنَّهُمۡ ءَامَنُواْ وَٱتَّقَوۡاْ لَمَثُوبَةࣱ مِّنۡ عِندِ ٱللَّهِ خَيۡرࣱۚ لَّوۡ كَانُواْ يَعۡلَمُونَ﴾ [البقرة: ۱۰۳] \"کتنا اچھا ہوتا اگر وہ ایمان لاتے، اور اللہ کے متقی بندے بنتے،اللہ کے یہاں جو ان کو بدلہ ملتا وہ بہت ہی بہتر ہوتا، اگر وہ اس کو جانتے\"۔\nاس سے پتا چلتا ہے کہ اللہ کے یہاں بہتر بدلہ پانے کے لیےایمان اور دین داری(تقوی) دونوں کا ہونا ضروری ہے۔صرف ایمان ہی کافی نہیں۔کیوں کہ عمل ایمان کا حصہ ہے،جس کے بغیر ایمان صحیح نہیں ہوسکتا۔\nثواب ہی کے معنی میں ایک لفظ قرآن کریم میں اور استعمال ہوا ہے جس کو اجر (نتیجۂ عمل) کہتے ہیں۔اس کامطلب ہے: مزدور کی مزدوری۔ اللہ نیک عمل کرنے والوں کے عمل کو یوں ہی اکارت نہیں ہونے دیتا۔ بلکہ اس کے عمل کا نتیجہ اسی طرح دیتا ہے جس طرح ایک مزدور کو دیا جاتا ہے۔ ارشادباری تعالیٰ ہے :\n۱- ﴿يَسۡتَبۡشِرُونَ بِنِعۡمَةࣲ مِّنَ ٱللَّهِ وَفَضۡلࣲ وَأَنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُؤۡمِنِينَ﴾ [آل عمران: ۱۷۱] \"اوراللہ مومنوں کے عمل کا اجر اکارت(ضائع) نہیں کرے گا\"۔\n۲- ﴿وَٱلَّذِينَ يُمَسِّكُونَ بِٱلۡكِتَٰبِ وَأَقَامُواْ ٱلصَّلَوٰةَ إِنَّا لَا نُضِيعُ أَجۡرَ ٱلۡمُصۡلِحِينَ﴾ [الأعراف: ۱۷۰] \"اور جو لوگ کتاب کے پابند ہیں اور نمازکی پابندی کرتے ہیں۔یقیناً ہم ایسے لوگوں کا جو اپنی اصلاح کریں، اجر(ثواب)ضائع(اکارت)نہیں کریں گے\"۔\n۳- ﴿مَا كَانَ لِأَهۡلِ ٱلۡمَدِينَةِ وَمَنۡ حَوۡلَهُم مِّنَ ٱلۡأَعۡرَابِ أَن يَتَخَلَّفُواْ عَن رَّسُولِ ٱللَّهِ وَلَا يَرۡغَبُواْ بِأَنفُسِهِمۡ عَن نَّفۡسِهِۦۚ ذَٰلِكَ بِأَنَّهُمۡ لَا يُصِيبُهُمۡ ظَمَأࣱ وَلَا نَصَبࣱ وَلَا مَخۡمَصَةࣱ فِي سَبِيلِ ٱللَّهِ وَلَا يَطَـُٔونَ مَوۡطِئࣰ ا يَغِيظُ ٱلۡكُفَّارَ وَلَا يَنَالُونَ مِنۡ عَدُوࣲّ نَّيۡلًا إِلَّا كُتِبَ لَهُم بِهِۦ عَمَلࣱ صَٰلِحٌۚ إِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ﴾ [التوبة: ۱۲۰] \"یقیناًاللہ تعالیٰ نیکوکاروں کا اجر ضائع نہیں کرتا\"۔\nتاہم اس کے لیے ضروری ہےکہ آدمی :\n۱-ایمان کے ساتھ عمل صالح کرنے والا ہو۔ (دیکھیے: حم السجدہ:۸)\n۲-اللہ سے ڈرنے والا اور صبرکرنےوالا ہو۔(دیکھیے: یوسف:۹۰)\n۳-کسی عمل صالح کا اجر دنیاوالوں سے نہ مانگیں بلکہ اللہ پر چھوڑ دیں۔ (دیکھیے: سورہ یوسف:۱۰۴)\nوہ جو بھی نیک عمل کررہا ہو اس میں اللہ کی رضا مقصود ہو۔اسی لیے جتنے بھی رسول آئے انھوں نے بڑے واضح طور پر یہ اعلان کردیا کہ ہماری دعوت کا مقصد صرف اور صرف اللہ کی رضا و خوشنودی ہے۔ ہم تم سے کوئی اجر نہیں مانگتے، بلکہ ہم تو صرف تمھیں راہ مستقیم (ہدایت) دکھانے آئے ہیں۔اب یہ تم پرمنحصر ہے کہ اس کو قبول کرتے ہو یا نہیں۔","",{}],[186,"§ثوم\nلہسن ایک طرح کی سبزی ہے، جو کچی اور پکا کر کھائی جاتی ہے۔اسے کچا کھانے کے بعد منہ سے بدبو نکلتی ہے۔ اس لیے اسے کهاکر مسجد میں آنا منع ہے۔\nاسی طرح سے ایک سبزی کراث ہے، جس کو اردو میں گندناکہتے ہیں۔یہ لہسن کی جنس سے ہے اور لہسن سے مشابہ ہے،جو پیاز کے پتوں کی طرح ہوتی ہے اورعرب ممالک میں اس کو کھانے کے ساتھ کچا کھاتے ہیں۔ عرب ممالک میں یہ بہت پیدا ہوتا ہے۔ چونکہ لہسن کھانے کےبعد کھانے والوں کے منہ سے بدبو آتی ہے اس لیے اس کو کھانے کے بعد مسجدمیں جانے سے منع کیا گیا ہے۔ اس کا بیان قرآن میں تو نہیں ہے، لیکن صحیح حدیثوں میں آتا ہے۔(مزیددیکھیں: بصل=پیاز)","",{}],[187,"§جادو\nدیکھیے: سحر","",{}],[188,"§جادوگر\nدیکھیے: سحر","",{}],[189,"§جاسوسی\nدیکھیے: تجسس","",{}],[190,"§جالوت\nاس کو بائبل میں جولیت کہا گیاہے۔ یہ فلسطینی تھا جو چھے ہاتھ(تقریباًنو فٹ) لمبا تھا۔ (دیکھیے : اول سمویل: ۱۷:۴) فلسطینی اس کو اپناسپہ سالار مانتے تھےاور اسی کی قیادت میں بنی اسرائیل سے جنگ کیا کرتے تھے۔ قرآن مجیدمیں جالوت کا نام تین بار آیا ہے :\nاول :جب طالوت نےاپنی فوج کا امتحان لیا۔ارشادباری تعالیٰ ہے:﴿فَلَمَّا فَصَلَ طَالُوتُ بِٱلۡجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبۡتَلِيكُم بِنَهَرࣲ فَمَن شَرِبَ مِنۡهُ فَلَيۡسَ مِنِّي وَمَن لَّمۡ يَطۡعَمۡهُ فَإِنَّهُۥ مِنِّيٓ إِلَّا مَنِ ٱغۡتَرَفَ غُرۡفَةَۢ بِيَدِهِۦۚ فَشَرِبُواْ مِنۡهُ إِلَّا قَلِيلࣰ ا مِّنۡهُمۡۚ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ قَالُواْ لَا طَاقَةَ لَنَا ٱلۡيَوۡمَ بِجَالُوتَ وَجُنُودِهِۦۚ قَالَ ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ ٱللَّهِ كَم مِّن فِئَةࣲ قَلِيلَةٍ غَلَبَتۡ فِئَةࣰ كَثِيرَةَۢ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ﴾ [البقرة: ۲۴۹] \"جب طالوت لشکر لے کر نکلے تو انھوں نے لشکریوں سے کہا: سنو! اللہ تعالیٰ تمھیں ایک نہر سے آزمانے والا ہے۔ پس جو شخص اس نہر کا پانی پیے گا وہ ہم سے نہیں ہوگا۔میرا ساتھی صرف وہ ہے جو اس سے اپنی پیا س نہ بجھائے۔ہاں ایک آده چلو کوئی پی لے تو پی لے، لیکن کچھ لوگوں کےسوا سب نے اس نہر سے اپنی پیاس بجھائی۔پھر جب طالوت اور اس کے ساتھی ایمان والے ندی پار کر گئے تو انھوں نے طالوت سے کہہ دیا: آج ہم میں جالوت اور اس کی فوج کا مقابلہ کرنے کی طاقت نہیں ہے\"۔\nدوم: جو تھوڑے بہت ایمان والے طالوت کے ساتھ رہ گئے تھے اور جن کا یہ یقین تھا کہ ہمیں ایک دن اللہ سے ملنا ہے،ان کاسامنا جالوت کی فوج سے ہوا جب دونوں کی فوج روبرو ہوئی تو طالوت کے ساتھیوں نے کہا:﴿وَلَمَّا بَرَزُواْ لِجَالُوتَ وَجُنُودِهِۦ قَالُواْ رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرࣰ ا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ﴾ [البقرة: ۲۵۰] \"اے ہمارے رب تو ہمیں زیادہ سے زیادہ صبر عطا کر اور ہمارے قدموں کوثابت رکھ اور بے دین لوگوں پر ہمیں فتح عطا کر\"۔\nسوم:جب طالوت کی فوج کا مقابلہ جالوت کی فوج سےہورہا تھا توطالوت کی فوج کے ایک عظیم جنگ جو داود(جو بعد میں نبی بھی ہوئے)نےجالوت کو ہلاک کردیا۔قرآن مجیدمیں آیا ہے:﴿تِلۡكَ ءَايَٰتُ ٱللَّهِ نَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۚ وَإِنَّكَ لَمِنَ ٱلۡمُرۡسَلِينَ﴾ [البقرة: ۲۵۲] \"اُنهوں (طالوت کی فوج ) نے اللہ کے حکم سے انھیں شکست دی اور داود نے جالوت کو ہلاک کردیا\"۔(البقرہ:۲۵۱) (مزیددیکھیے :بائبل،اول سمویل:۱۵:۱۷)\nجالوت سر سے پاؤں تک فوجی لباس میں تھا۔داود علیہ السلام نے تین پتھر اس کی پیشانی پر مارےجس کی وجہ سے وہ بے ہوش ہوکر زمین پرگر پڑا۔ پھر اسی کی تلوار سے اس کو قتل کردیا۔یہ دیکھ کرفلسطینیوں میں افرا تفری پهیل گئی۔ طالوت کی فوج نے ان کاپیچھاکیا۔جو بھی ہاتھ آیا اس کوقتل کردیا۔اس طرح جالوت کی ہلاکت کے سبب فلسطینی شکست کھا گئے۔","",{}],[191,"§جان سے ماردینا\nدیکھیے: قتل","",{}],[192,"§جاندار\nدیکھیے: حی","",{}],[193,"§جانور\nدیکھیے: دابہ","",{}],[194,"§جبار\nدیکھیے: اسماے حسنی","",{}],[195,"§جبرئيل علیہ السلام\nجبرئیل سریانی زبان کا لفظ ہے۔ اس کےمعنی اللہ کے بندے کے ہیں۔ پھریہ لفظ ایک خاص فرشتے کے لیے بولا جانے لگا، جو اللہ تعالیٰ کی طرف سے وحی لےکرآتے تھے۔\nبائبل اور قرآن میں جبرئیل علیہ السلام کا ذکر باربار آیا ہے۔ جیسے بائبل میں دانیال نبی کومشاہدہ کا معنی سمجھانا اور سترہفتوں کی نبوت دینا۔ (دیکھیے: دانیال:۹:۲۱:۲۷)\nاسی طرح زکریا علیہ السلام کویحیی کی پیدایش کی خوش خبری سنانا۔ (دیکھیے: لوقا: ۲۱ـ۱۱:۱)\nاور مریم علیہا السلام کو عیسیٰ علیہ السلام کی خوش خبری دینا۔ (دیکھیے: لوقا:۲۷ـ۲۶:۱)\nیہی وہ جبریل ہیں جو محمد صلی اللہ علیہ وسلم کے پاس اللہ تعالیٰ کی طرف سے پہلی بار حرا نامی غار میں وحی لے کر آئے۔اکثر وہ ایک انسان کی شکل میں آیا کرتے تھے۔لیکن دوبار اپنی اصلی شکل میں نبی اکرم صلی اللہ علیہ وسلم کے سامنےآئے،جس کا ذکر قرآن مجیدمیں اس طرح آیا ہے: ﴿عَلَّمَهُۥ شَدِيدُ ٱلۡقُوَىٰ ذُو مِرَّةࣲ فَٱسۡتَوَىٰ وَهُوَ بِٱلۡأُفُقِ ٱلۡأَعۡلَىٰ ثُمَّ دَنَا فَتَدَلَّىٰ فَكَانَ قَابَ قَوۡسَيۡنِ أَوۡ أَدۡنَىٰ فَأَوۡحَىٰٓ إِلَىٰ عَبۡدِهِۦ مَآ أَوۡحَىٰ مَا كَذَبَ ٱلۡفُؤَادُ مَا رَأَىٰٓ أَفَتُمَٰرُونَهُۥ عَلَىٰ مَا يَرَىٰ﴾ [النجم: ۵-۱۲] \"اسےعظیم طاقت ور نے تعلیم دی جو بہت حکمت والا ہے۔پھر سامنےآکھڑا ہوا جب کہ وہ افق کے اعلیٰ درجے پر تھا، پھر وہ نزدیک ہوا اور اتر گیا۔ یہاں تک کہ دو کمانوں کے برابر یا اس سے بھی زیادہ نزدیک ہوگیا۔ تب اس نے اللہ کے بندے کی طرف وحی کی جو وحی کرنی تھی۔دل نے کوئی جھوٹ نہیں کہاجو کچھے اس نے دیکھا۔اب کیا تم اس سے اس چیز پر جھگڑتے ہو جسے وہ دیکھ رہا ہے؟\"۔\nپہلی بار نبی اکرم صلی اللہ علیہ وسلم نے جبرئیل علیہ السلام کو ان کی اصلی شکل میں دیکھا، جن کے چھ سو (۶۰۰) پرتھے، جو مشرق کی طرف سےظاہر ہوےاور دیکھتے ہی دیکھتے مغربی افق پر چھاگئے۔دوسری مرتبہ آپ نے انھیں اس وقت دیکھا جب آپ نے آسمان کا سفر کیا، جس کو معراج کا سفر کہتے ہیں۔قرآن مجیدمیں اسی کی طرف اس طرح اشارہ کیا گیا ہے: ﴿وَلَقَدۡ رَءَاهُ نَزۡلَةً أُخۡرَىٰ عِندَ سِدۡرَةِ ٱلۡمُنتَهَىٰ عِندَهَا جَنَّةُ ٱلۡمَأۡوَىٰٓ إِذۡ يَغۡشَى ٱلسِّدۡرَةَ مَا يَغۡشَىٰ مَا زَاغَ ٱلۡبَصَرُ وَمَا طَغَىٰ لَقَدۡ رَأَىٰ مِنۡ ءَايَٰتِ رَبِّهِ ٱلۡكُبۡرَىٰٓ﴾ [النجم: ۱۳-۱۸] \"اس نے اس (جبرئیل)کو ایک بار سدرة المنتہی کے نزدیک اترتے ہوے دیکھا۔جس کےقریب جنۃ الماوی (سکونت والی جنت) ہے۔جب کہ سدرہ کو چھے پارہی تھی وہ چیز جو اس پر چھے پارہی تھی۔نہ نظر ادھر ادھر ہٹی اور نہ ہی بڑھی۔ یقیناً اس نے اپنے رب کی بڑی بڑی نشانیاں دیکھیں\"۔\nعبداللہ بن مسعود رضی اللہ عنہ کہتےہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے جبرئیل کو اصلی شکل میں دیکھا جن کے چھ سو پر تھے۔ (صحیح البخاری: ۴۸۵۶و صحیح مسلم: ۲۸۰/۱۷۴)\nام المومنین عائشہڤکاقول ہےکہ پورےآسمان کا کنارہ چھپ گیا تھا۔ (صحیح البخاری: ۳۷۳۵ وصحیح مسلم: ۲۸۷/۱۷۷)\nام المومنین عائشہڤنے ان لوگوں کی باتوں کی تردید بھی کی ہے جنھوں نے ان آیات کے ذریعے سےاللہ کے دیدار اور ملاقات کو ثابت کرنے کی کوشش کی ہے۔ (صحیح البخاری: ۳۲۳۴)\nابوذر رضی اللہ عنہ نےخودنبی اکرم صلی اللہ علیہ وسلم سےپوچھ لیا تھاکہ کیا آپ نے اللہ کو دیکھاہے؟جواب میں نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"وہ تو ایک نور ہے، اسے کیسے دیکھا جاسکتا ہے?\" (صحیح مسلم: ۲۹۱/۱۷۸)\nمطلب یہ کہ جب بھی جبرئیل علیہ السلام آتے تھے تو کسی انسان کی شکل میں ہوتے تھے۔ ابوہریرہ رضی اللہ عنہ کہتے ہیں: «أَتَی جِبْرِيلُ النبی صلی اللہ علیہ وسلم فَقَالَ: يَا رَسُولَ اللَّهِ! هَذِهِ خَدِيجَةُ قَدْ أَتَتْ مَعَهَا إِنَاءٌ فِيهِ إِدَامٌ أَوْ طَعَامٌ أَوْ شَرَابٌ، فَإِذَا هِيَ أَتَتْکَ فَاقْرَأْ عَلَيْهَا السَّلامَ مِنْ رَبِّهَا وَمِنِّي وَبَشِّرْهَا بِبَيْتٍ فِي الْجَنَّةِ مِنْ قَصَبٍ لا صَخَبَ فِيهِ وَلانَصَبَ».(صحیح البخاری: ۳۸۲۰، صحیح مسلم: ۲۴۳۲) \"ایک بار جبرئیل علیہ السلام نے نبی اکرم صلی اللہ علیہ وسلم سے کہا:ابھی کچھ دیر کے بعد خدیجہڤآپ کے لیےکھانا لےکر آنے والی ہیں۔ جب وہ آئیں تو ان کے رب کی طرف سے اور میری جانب سے ان کوسلام سنادیں اور یہ خوش خبری بھی دے دیں کہ ان کے لیے جنت میں ایک ایسا گھر بنایا گیا ہے کہ اس میں رہنے سے نہ تو کوئی شورشرابہ ہوگا اور نہ تھکاوٹ ہوگی\"۔\nایک مرتبہ نبی اکرم صلی اللہ علیہ وسلم نے عائشہڤسے کہا: دیکھو، یہ جبرئیل ہیں تمھیں سلام کر رہے ہیں۔ عائشہ ڤنے کہا: \"ان کو بھی میرا سلام پھرکہاکہ وہ دیکھ سکتے ہیں اور میں نہیں دیکھ سکتی\" (صحیح البخاری: ۳۲۱۷،و صحیح مسلم: ۹۱/۲۴۴۷)\nحسان بن ثابت رضی اللہ عنہ بہت بڑے شاعر تھے۔نبی اکرم صلی اللہ علیہ وسلم کی تعریف اور قریش کی ہجومیں اشعار کہا کرتے تھے۔ایک مرتبہ نبی اکرم صلی اللہ علیہ وسلم نے ان سے کہا: قریش کی ہجومیں مزید اشعارکہو۔تمھارےساتھ جبرئیل ہیں۔(صحیح البخاری: ۳۲۱۳ وصحیح مسلم: ۱۵۳/۲۴۸۰)\nاسامہ بن زید رضی اللہ عنہما کہتے ہیں: جبریل ایک مرتبہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور آپ سے باتیں کرتے رہے۔ اس وقت رسول اللہ صلی اللہ علیہ وسلم کے پاس ام المومنین ام سلمہ بیٹھی ہوئی تھیں۔ جب جبریل چلے گئے تو رسول اللہ صلی اللہ علیہ وسلم نے ام سلمہ سے فرمایا: معلوم ہےیہ کون صاحب تھے؟ یا ایسے ہی الفاظ ارشادفرمائے۔ ام سلمہ نے جواب دیا کہ یہ دحیہ کلبی تھے۔اللہ کی قسم میں سمجھے بیٹھی تھی کہ وہ دحیہ کلبی ہیں۔ آخر جب میں نے رسول اللہ صلی اللہ علیہ وسلم کا خطبہ سنا جس میں آپ جبریل (کی آمد ) کی خبر دے رہے تھے تو میں سمجھی کہ وہ جبریل ہی تھے۔ (صحیح البخاری: ۳۶۳۳، وصحیح مسلم: ۲۴۵۱/۱۰۰)\nدیگراحادیث سے بھی معلوم ہوتا ہے کہ جبرئیل علیہ السلام دحیہ کلبی رضی اللہ عنہ کی شکل میں آتے اور وحی سنا کر چلے جاتے تھے۔صحیح حدیث سے معلوم ہوتا ہے کہ جبرئیل علیہ السلامایک بار صحابہ رضی اللہ عنہم کی مجلس میں اسلام کی بنیادی تعلیم دینے کے لیے تشریف لائے اور نبی اکرم صلی اللہ علیہ وسلم سےایمان، اسلام،احسان اور قیامت کے بارےمیں سوالات کرتے رہےاور پھر اٹھ کر چلے گئے۔ان کے چلے جانے کے بعد نبی اکرم صلی اللہ علیہ وسلم نے صحابہ سے سوال کیا: \"جانتے ہو وہ کون تھے؟یہ جبرئیل تھے جو تمھیں دین کی بنیادی باتیں سکھانے کے لیے آئے تھے\"۔ (صحیح البخاری: ۵۰،و صحیح مسلم: ۸)\nاسی طرح صحیح احادیث سے معلوم ہوتا ہے کہ جبرئیل علیہ السلا م نے دو بار نبی اکرم صلی اللہ علیہ وسلم کو نمازیں ادا کرائیں تاکہ یہ بتائیں کہ نماز کا طریقہ اور وقت کیا ہوتا ہے۔جس سال نبی اکرم صلی اللہ علیہ وسلم کی وفا ت ہونے والی تھی،اس سال جبرئیل علیہ السلام نے دو مرتبہ پورا قرآن آپ کو سنایا۔(صحیح البخاری: ۶۲۸۵ و صحیح مسلم: ۲۴۵۰)\nسورہ تکویر میں جبرئیل علیہ السلام کی چھ عظیم صفات کا تذکرہ ملتا ہے۔ اللہ تعالی کا فرمان ہے:﴿إِنَّهُۥ لَقَوۡلُ رَسُولࣲ كَرِيمࣲ ذِي قُوَّةٍ عِندَ ذِي ٱلۡعَرۡشِ مَكِينࣲ مُّطَاعࣲ ثَمَّ أَمِينࣲ وَمَا صَاحِبُكُم بِمَجۡنُونࣲ‏﴾ [التکویر: ۱۹-۲۲] \"یقینا یہ ایک بزرگ پیغمبر کا قول ہے۔ جوبڑی طاقت والا ہے، عرش والےکے نزدیک بلند مرتبہ ہے۔ وہاں اس کا حکم مانا جاتا ہے۔اور وہ امانت دار ہے۔ اور تمہارا ساتھی یعنی نبی دیوانہ نہیں ہے۔\nان آیتوں میں جبرئیل علیہ السلام کے پانچ عظیم اوصاف کا ذکر ہے۔\nبزرگ پیغمبر جن کو قرآن میں \"رسول کریم\" کہا گیا ہے۔ اس کا مفہوم یہ ہے کہ وہ شرافت سے معمور ہے جس میں کوئی شیطانی نہیں۔\nصاحب قوت اور ایک مقام پر فرمایا:﴿عَلَّمَهُۥ شَدِيدُ ٱلۡقُوَىٰ﴾ [النجم: ۵] \"اسے پوری طاقت والے فرشتے نے سیکھا یا ہے\"۔ یعنی اس کی قوت کے سامنے شیاطین کبھی بھی ٹک نہیں سکتے اور وہ جو کلام الہی محمد صلی اللہ علیہ وسلم تک پہنچارہے ہیں اس میں دخل اندازی نہیں کرسکتے۔ بلکہ وہ تو جبرئیل علیہ السلام کو دیکھ کر بھاگ کھڑے ہوتے ہیں۔\nان کا مرتبہ اللہ کے پاس بہت بلند ہے۔ اس لئے جس نے جبرئیل علیہ السلام سے دشمنی کی گویا اس نے اللہ تعالی کو اپنا دشمن بنایا۔ اور جس نے ایسا کیا اسے ہلاک وبرباد ہونے سے بھلا کون روک سکتا ہے؟\nجبرئیل علیہ السلام کے ساتھ فرشتوں کی ایک جماعت ہے جو ان کی اطاعت کرتے ہیں اور ان کی توجیہات کو اپناتے ہیں۔ کیا مجال کہ ان میں سے کوئی جبرئیل علیہ السلام کی نافرمانی کرے۔\nوہ امانت دار ہے۔ یعنی اللہ کی طرف سے جو کچھ ان کو انبیاء کرام تک پہنچانے کا آرڈر ملتا ہے وہ اسے جوں کا توں پیغمبر تک پہنچاتے ہیں اور اس میں کسی بھی قسم کی تبدیلی نہیں کرتے۔ گویا کہ اللہ تعالی نے نبی اور اپنے درمیان کے راوی یعنی جبرئیل علیہ السلام کی خود توثیق فرمائی ہے۔\nسورہ تکویر ہی میں ان کی چھٹی صفت کا بھی ذکر ہے۔اللہ تعالی کا ارشاد ہے:﴿وَمَا هُوَ عَلَى ٱلۡغَيۡبِ بِضَنِينࣲ‏﴾ [التکویر: ۲۴] \"وہ غیب کی بات پہنچانے میں بخیلی نہیں کرتے\"۔ یعنی اللہ کی طرف سے نازل کردہ وحی کو چھپائے بغیر نیز اس میں کسی طرح کی کمی وبیشی کئے بغیر اسے نبی تک جوں کا توں پہنچادیتے ہیں۔\nجو فرشتہ ان اعلی اوصاف کا پیکر ہو کیا وہ کسی مجنون اور دیوانے کے پاس وحی لے کر اترے گا؟ کیا تم یہ معمولی بات سمجھ نہیں سکتے؟ جبرئیل علیہ السلام کے اوصاف کو بیان کرنےکے بعد رسول اللہ صلی اللہ علیہ وسلم کے جنون اور پاگل پن سے برأت کے اظہار کا یہ عمدہ طریقہ ہے اگر کفار ومشرکین میں ذرہ بھی عقل ہو۔\nجبرئیل علیہ السلام نبی اکرم صلی اللہ علیہ وسلم اوراللہ کے درمیان ایک سفیر تھے، جو اللہ کا پیغام لےکر آتے تھے اور آپ کو سناتے تھے۔لیکن اس کا یہ مطلب نہیں کہ جبرئیل علیہ السلام نبی اکرم صلی اللہ علیہ وسلم سے اعلیٰ درجے کے تھے۔ آپ صلی اللہ علیہ وسلم تو ساری مخلوقات میں افضل اور بالاتر تھے۔","",{}],[196,"§جحيم\nجحیم کا مطلب ہے دہکتی ہوئی آگ۔ یہاں ان لوگوں کو رکھا جائے گا، جنھوں نے اللہ اور اس کے احکام کا انکار کیا۔ قرآن میں ایک بہت بڑے درخت کا ذکر آیا ہے، جس کی جڑ جحیم میں ہے: ﴿أَذَٰلِكَ خَيۡرࣱ نُّزُلًا أَمۡ شَجَرَةُ ٱلزَّقُّومِ إِنَّا جَعَلۡنَٰهَا فِتۡنَةࣰ لِّلظَّٰلِمِينَ إِنَّهَا شَجَرَةࣱ تَخۡرُجُ فِيٓ أَصۡلِ ٱلۡجَحِيمِ﴾ [الصافات: ۶۲-۶۴] \"کیایہ مہمان نوازی اچھی ہے یا زقوم کا درخت جسے ہم نے ظالموں کے لیےسخت آزمایشبنادیا ہے۔بےشک وہ ایک درخت ہے جو جحیم کی جڑسے نکلتاہے\"۔","",{}],[197,"§جد وجہد\nدیکھیے: مجاہدہ (تلاش حق)","",{}],[198,"§جراد\nعربی میں جراد ٹڈی کوکہتے ہیں،یہ اڑنے والا ایک کیڑا ہے جو تقریباًدو انچ لمبا ہوتا ہے۔اس کے چار پر ہوتے ہیں۔ سامنے کے دو چھوٹے اورپیچھے کے دو بڑے اور چھے پیر ہوتے ہیں۔ چار چلنے کے لیے اور دو چھلانگ لگانے کے لیے۔اس کی غذا درختوں کے پتے اورکھیتوں میں اُگی ہوئی پھول پتیاں وغیرہ ہیں۔یہ بڑے بڑے جھنڈ کی شکل میں چلتی ہیں۔ جہاں سےبھی ان کا گزر ہوتا ہے، وہاں کی فصلیں اورساری ہریالی چاٹ جاتی ہیں۔اس لیے ان کےحملے سے بچنے کے لیے بہت پہلے سے انتظامات کرنے پڑتے ہیں۔قرآن مجیدمیں ان کا ذکر دومرتبہ آیا ہے۔\nپہلی بار: جب فرعون اور اس کی قوم نے موسیٰ علیہ السلام سے کہا کہ تم کوئی بھی نشانی لاؤ ہم تم پر ایمان لانےوالے نہیں ہیں، تو اللہ تعالیٰ نے متعدد نشانیاں بھیج دیں: ﴿فَأَرۡسَلۡنَا عَلَيۡهِمُ ٱلطُّوفَانَ وَٱلۡجَرَادَ وَٱلۡقُمَّلَ وَٱلضَّفَادِعَ وَٱلدَّمَ ءَايَٰتࣲ مُّفَصَّلَٰتࣲ فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمࣰ ا مُّجۡرِمِينَ﴾ [الأعراف: ۱۳۳] \"پھر ہم نے ان پر طوفان اور ٹڈیاں اور جوئیں اور مینڈک اورخون بھیجا، جو ظاہر نشانیاں تھیں، پھر بھی انھوں نے غرور کیا اور وہ مجرم لوگ تھے\"۔ (مزید معلومات کے لیے دیکھیں: موسیٰ علیہ السلام)\nدوسری بار: روزقیامت کفارکی قبرسےاٹھائےجانےکی حالت کی مثال ٹڈی سےدی گئی ہے: ﴿خُشَّعًا أَبۡصَٰرُهُمۡ يَخۡرُجُونَ مِنَ ٱلۡأَجۡدَاثِ كَأَنَّهُمۡ جَرَادࣱ مُّنتَشِرࣱ‏﴾ [القمر: ۷] \"یہ جھکی نظروں کے ساتھ قبروں سے اس طرح نکلیں گے جیسے بکھری ہوئی ٹڈیاں ہوں\"۔\nچوں کہ ٹڈیوں کی غذا گھاس اورسبزہ ہے۔اس لیے اس کا کھانا موسیڠ کے زمانے سے ہی حلال چلا آرہا ہے۔ (دیکھیے: بائیل:لاوی: ۱۱:۲۲)\nیحیی علیہ السلام کا پسندیدہ کھانا ٹڈیا ں اورجنگلی شہد تھا۔(دیکھیے: متی :۳:۴)\nعبداللہ بن عمر رضی اللہ عنہما سےمروی حدیث میں ہے : «أُحِلَّتْ لَنَا مَيْتَتَانِ وَدَمَانِ: الجَرَادُ والحِيتَانُ، والکَبِدُ والطِّحَالُ» \"ہمارے لیے دومردہ اور دو خون والی چیزیں حلال کی گئی ہیں۔مری ہوئی چیزوں میں سے ٹڈی اور مچھلی اور خون والی میں کلیجی اورتلی\"۔(السنن الکبری للبیہقی: ۱۱۲۸، اس کی سندصحیح ہے)\nٹڈی کےپکانے کا طریقہ یہ ہے کہ اس کے پیر، پر اور سر کو کاٹ دیتے ہیں اور آنتیں نکال دیتے ہیں،پھر باقی کو ہلکی آنچ پر بھونتےیا تیل میں تل لیتے ہیں۔","",{}],[199,"§جزیہ\nقرآن مجیدمیں جزیہ کا ذکر صرف ایک مرتبہ آیا ہے: ﴿قَٰتِلُواْ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱللَّهِ وَلَا بِٱلۡيَوۡمِ ٱلۡأٓخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ ٱللَّهُ وَرَسُولُهُۥ وَلَا يَدِينُونَ دِينَ ٱلۡحَقِّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ حَتَّىٰ يُعۡطُواْ ٱلۡجِزۡيَةَ عَن يَدࣲ وَهُمۡ صَٰغِرُونَ﴾ [التوبة: ۲۹] \"ان کتاب والوں سے جنگ کرو جو نہ اللہ پر ایمان لاتے ہیں اور نہ آخرت پر اور نہ اسے حرام جانتے ہیں جسےاللہ اور اس کے رسول نے حرام ٹھہرایا ہے اور نہ سچے مذہب کو اختیار کرتے ہیں یہاں تک کہ وہ ذلیل ہوکراپنے ہاتھ سے جزیہ دینے لگیں\"۔\nقرآن کریم کےمطابق جزیہ اہل کتاب سے لیا جائے گا اور احادیث کی روشنی میں مجوسیوں (آتش پرستوں) سےبھی جزیہ لیاجائےگا۔جزیہ ایک طرح کا حفاظتی محصول(سیکورٹی چارج ) ہے،جواسلامی ممالک میں رہنے والے غیرمسلم ذمی کودینا پڑتاہے۔اس وجہ سے کہ اس کی مذہبی آزادی اور اس کی جان و مال،عزت وآبرو کا تحفظ اسلامی حکومت کی ذمہ داری ہے۔یہ محصول اسی طرح ہے،جیسے ایک مسلمان سےاس کے واجب الادا مال سے سالانہ ڈھائی فیصدزکاۃ لی جاتی ہے،تاکہ اس کےذریعے سے معاشرے کےضرورت مندافرادکی مددکی جائے۔فرق یہ ہےکہ زکاۃ اسلام کا ایک بنیادی رکن اورایک اہم ترین عبادت ہے،جو مسلمان اپنی خوشی سےاللہ تعالیٰ کی رضااورخوشنودی حاصل کرنے کے لیے نکالتاہےاور جزیہ ایک ایسامحصول ہے جو غیرمسلم سے صرف اس کے تحفظ اور مذہبی آزادی کے بدلے میں لیاجاتا ہے۔ نہ تو اس میں اللہ کی خوشنودی ہے، نہ آخرت کا ثواب۔اس لیے جزیہ دینے والا اس بات پر ضرور غور کرے گاکہ کیوں نہ میں بھی سچا دین اختیار کرلوں اور جزیہ کے بدلے زکاۃدےکر اللہ تعالیٰ کی خوشنودی حاصل کرلوں۔جزیہ دینے والے کو جنگ میں شامل ہونے کی ضرورت نہیں ہوتی۔ اگروہ اپنی مرضی سےمسلم افواج کے ساتھ جنگ میں حصہ لیتا ہےتو اس سے جزیہ نہیں لیا جائےگا۔ اگرحکومت نے جزیہ لے لیا ہے اور کسی وجہ سےذمی کو تحفظ نہیں دے پاتی ہے تو وہ جزیہ واپس لوٹا دے گی۔ (دیکھیے: سورہ البقرہ: ۲۵۶)","",{}],[200,"§جلن\nدیکھیے: حسد","",{}],[201,"§جمعہ\nجمعہ ہفتے کا آخری دن ہے۔ اسلام سے قبل اس کو عروبہ کہتے تھے۔ جمعہ اسلامی نام ہے۔احادیث میں اس کی بڑی فضیلت آئی ہے۔ اللہ تعالیٰ نے اس دنیا کی تخلیق اتوار سے شروع کی اور چھے دنوں میں اسے جمعہ پرختم کیا۔پھر وہ عرش معلیٰ پرمستو ی ہوا۔ قرآن مجیدمیں ہے: ﴿إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامࣲ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ﴾ [الأعراف: ۵۴] \"حقیقت میں تمھارا رب تو اللہ ہی ہے، جس نے آسمانوں اور زمین کی چھے دن میں تخلیق کی اور پھر عرش معلیٰ پر بلند ہوگیا\"۔\nصحیح احادیث سےمعلوم ہوتا ہےکہ جمعہ ہی کو اللہ تعالیٰ نے آدم علیہ السلام کو پیدا کیا۔ اسی دن ان کو جنت میں داخل کیا۔اسی دن ان کو جنت سے باہر نکالا۔ اسی دن قیامت آئے گی۔ اس دن ایک ایسا بھی لمحہ ہے، جس میں اللہ تعالیٰ بندوں کی دعا قبول کرتاہے۔\nمطلب یہ ہے کہ جمعہ کے دن کی بہت سی خصوصیات اورفضیلتیں ہیں۔اسلام سے قبل جو لوگ ابراہیمڠ کے پیروکار تھے، وہ بھی اس دن کی خصوصیات اور فضیلتوں کو مانتے تھے۔ان میں خود موسیٰڠ بھی تھے۔لیکن بعد میں جب یہودیوں نے اللہ تعالیٰ کو ایک انسان کی شکل دے دی،جس کو وہ ’یہووا‘ کہتے ہیں تو انھوں نے جمعہ کوچھوڑکرہفتے کو اپنا لیا اور یہ کہنے لگے کہ چونکہ اللہ تعالیٰ نے چھے دنوں میں اس پوری کائنات کی تخلیق کی اورساتویں دن آرام کیا،اس لیےہم بھی ساتویں دن آرام کریں گے۔اس کےلیے انھوں نے اپنے انبیا اوردوسرے لوگوں سے منسوب بہت سارےاقوال کو بائبل میں داخل کرلیا۔پھرایسا ہو اکہ اللہ تعالیٰ نے ہفتے کےآرام کو ان پر لازم کردیا اور اس کےخلاف کام کرنےپر ان کو سخت سزا دی۔قرآن کریم اسی طرف اشارہ کرتے ہوے کہتاہے: ﴿إِنَّمَا جُعِلَ ٱلسَّبۡتُ عَلَى ٱلَّذِينَ ٱخۡتَلَفُواْ فِيهِۚ وَإِنَّ رَبَّكَ لَيَحۡكُمُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ﴾ [النحل: ۱۲۴] \"رہا ہفتے کا دن تو یہ ان لوگوں کے لیے لازم کردیا گیا جنھوں نے اس کے بارے میں اختلاف کیا۔بےشک تیرا رب قیامت کے دن اس میں تفریق پیدا کرنے والوں کے درمیان فیصلہ کر دے گا\"۔\nمطلب یہ ہے کہ اللہ تعالیٰ نے ان لوگوں پر ظاہر کردیاکہ حقیقت میں ابراہیم علیہ السلام کے دین میں توجمعے کی اہمیت تھی،لیکن تم لوگوں نے ہفتے کو اپنالیا اور پھر تم نےاپنے بنائے ہوےدستور کی ہی تحقیراور خلاف ورزی کی،جس کےسبب سخت عذاب کےمستحق ہوئے۔اسی کی طرف صحیح بخاری کی ایک حدیث میں اشارہ کیاگیا ہے۔ ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کو کہتے سنا: «نَحْنُ الآخِرُونَ السَّابِقُونَ يَوْمَ الْقِيَامَةِ، بَيْدَ أَنَّهُمْ أُوتُوا الْکِتَابَ مِنْ قَبْلِنَا، ثُمَّ هَذَا يَوْمُهُمُ الَّذِی فُرِضَ عَلَيْهِمْ فَاخْتَلَفُوا فِيهِ، فَهَدَانَا اللَّهُ، فَالنَّاسُ لَنَا فِيهِ تَبَعٌ، الْيَهُودُ غَدًا وَالنَّصَارَی بَعْدَ غَدٍ». (صحیح البخاری: ۸۷۶، صحیح مسلم: ۸۵۵) \"گرچہ ہم سب سے آخر میں آئے ہیں مگر قیامت کے دن ہم سب سے آگے ہوں گے حالاں کہ ان لوگوں کو ہم سے پہلے شریعت دی گئی تھی اور یہی جمعہ کا دن تھا جو ان پر لازم کیا گیا تھا۔لیکن وہ اس میں اختلاف کر بیٹھے۔بس اللہ نے ہماری ہدایت کی۔اس لیے لوگ ہمارے پیچھےے ہیں۔ یہودی ایک دن بعد (ہفتے کو) اور عیسائی اس کے ایک دن بعد (اتوار)\"۔\nیہودیوں نےہفتے کو اپنے لیے پاک دن ٹھہرایا۔ اس دن وہ کوئی کام نہیں کرتے تھے۔ان کے عالم صرف شریعت کا مطالعہ کرتے تھے۔ جب عیسیٰ ڠ آئے اور انھوں نے یہودیوں کی حالت دیکھی تو ان کی سخت مذمت کی اور کہا:\nسبت کا دن (ہفتے) انسان کے لیے بنایا گیاہے۔ نہ کہ انسان سبت کے دن کے لیے،اس لیے انسان کا بیٹا سبت کے دن کا بھی مالک ہے۔(بائیبل،مرقس:۲۷:۲)\nیہودی عیسیٰڠسے ایک بار اس لیےغصہ ہوگئےکہ انھوں نے ہفتے کو ایک سوکھے ہاتھ والے انسان کے ہاتھ کو ٹھیک کردیا۔ (بائبل، مرقس:۶ـ۳:۳)\nابتدامیں بعض نصرانیوں نےہفتے کو پاک مانا،لیکن پھر وہ ہفتے کو چھوڑ کر اتوار کو پاک ماننے لگے۔ کیونکہ ان کے خیال سےاتوارکو عیسیٰڠقبر سے باہر نکلے تھے،۳۶۴ عیسوی میں نصرانی مذہب کانفرنس نے ہمیشہ کے لیےہفتے کی جگہ اتوار کو مقدس طے کردیا۔ اس طرح یہ دونوں یہودی اور نصرانی اس مقدس دن کو نہیں پاسکے،جسے جمعہ کہتے ہیں۔اس مقدس دن جمعے کی طرف اللہ تعالیٰ نے نبی اکرم صلی اللہ علیہ وسلم کو راہ دکھائی۔\nجمعہ کا مطلب ہے اکٹھاہونا۔ اسلام میں اس کی اتنی زیادہ اہمیت اور فضیلت ہے کہ اللہ تعالیٰ نے اس نام کی ایک سورہ نازل کی،جس کو سورہ الجمعہ کہا جاتا ہے۔ اس سورہ کی نویں آیت میں اللہ تعالیٰ ارشادفرماتا ہے: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نُودِيَ لِلصَّلَوٰةِ مِن يَوۡمِ ٱلۡجُمُعَةِ فَٱسۡعَوۡاْ إِلَىٰ ذِكۡرِ ٱللَّهِ وَذَرُواْ ٱلۡبَيۡعَۚ ذَٰلِكُمۡ خَيۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ﴾ [الجمعة: ۹] \"اے ایمان والو! جب جمعہ کے دن تمھیں نماز کے لیے بلایا جائے تو تم اللہ کو یاد کرنے کےلیے دوڑ پڑو۔ اور کاروبار چھوڑدو۔یہ تمھارے لیے اچھا ہے۔ اگر تم علم رکھتے ہو\"۔\nیہاں اللہ کی یاد سے مراد جمعے کی نماز ہے،جس کی ادائی ہر مسلمان کے لیے لازم ٹھہرائی گئی ہے۔صحیح احادیث میں جمعہ ادا کرنے کی بڑی تاکید آئی ہے:\n۱-عبداللہ بن عمر اورابوہریرہ رضی اللہ عنہم کہتےہیں کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کو اپنے منبر کی لکڑیوں پر فرماتے سنا: «لَيَنْتَهِيَنَّ أَقْوَامٌ عَنْ وَدْعِهِمْ الْجُمُعَاتِ أَوْ لَيَخْتِمَنَّ اللَّهُ عَلَی قُلُوبِهِمْ ثُمَّ لَيَکُونُنَّ مِنْ الْغَافِلِينَ». (صحیح مسلم: ۴۰/۸۶۵) \"لوگ جمعہ کی نماز چھوڑنے سے باز آجائیں نہیں تو اللہ ان کے دلوں پرمہر لگا دےگا۔پھر وہ غافلوں میں سے ہوجائیں گے\"۔\n۲- جابربن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «مَنْ تَرَکَ الجُمُعَةَ ثَلاَثّا مِنْ غَيْرِ ضَرُورَةٍ طَبَعَ اللهُ عَلَی قَلْبِهِ». (سنن ابن ماجہ: ۱۱۲۶، ابن خزیمہ: ۱۸۵۶، مسند احمد: ۱۴۵۵۹) \"جو مسلمان تین جمعہ لگاتار اپنی سستی کی وجہ سے چھوڑے گا تو اللہ اس کے دل پر دھبّا لگا دےگا\"۔\nہاں مسافر، عورت، نابالغ بچے اور بیمار کے اوپر جمعہ کی نماز فرض نہیں ہے۔\n§جمعہ کے کچھ خاص آداب :\n۱-جمعے کے دن ہر مسلمان کو حتی المقدور غسل کرنا چاہیے۔\n۲-اچھے کپڑے پہننا اور خوشبو لگانا سنت ہے۔\n۳-جلد سےجلد مسجد پہنچنے کی کوشش کرنی چاہیے۔\n۴-مسجد میں داخل ہوتے وقت اس بات کا دھیان رکھنا چاہیے کہ کسی دوسرے شخص کو تکلیف نہ پہنچے اس لیے کسی کو پھلانگ کر آگے جانا منع ہے۔ بلکہ جہاں جگہ ملے وہیں بیٹھ جانا چاہیے۔\n۵-اگر کوئی شخص کسی خاص ضرورت سےمسجد سے باہر جاتاہے تواس کی جگہ کو خالی رکھنا چاہیے۔ کیونکہ اس جگہ پر اس کا زیادہ حق ہے۔\n۶-اگر دو نمازیوں کےدرمیان میں کچھ جگہ ہے اور کوئی تیسرا نمازی وہاں بیٹھنا چاہتاہے تو چاہیے کہ لوگ اِدھر اُدھر کھسک جائیں تاکہ اس کے لیے جگہ بن جائے۔\n۷-بیٹھنے سے قبل دورکعت نماز پڑھنی سنت ہے، جس کو تحیۃ المسجد (مسجد کا سلام) کہتے ہیں۔\n۸-جب امام خطبہ دے رہا ہو تواس کے خطبے کو غورسےسننا واجب ہے۔خطبےکے درمیان کسی سے بات چیت یا اپنےآپ کو کسی اور کام میں مصروف کرنا منع ہے۔\n۹- جمعہ کے دن نبی اکرم صلی اللہ علیہ وسلم پر زیادہ زیادہ سے درودو سلام بھی بھیجنا چاہیے۔\n۱۰- امام کو چاہیے کہ خطبہ لمبا نہ کرے۔ بلکہ جو کچھ کہنا ہو مختصر بیان کرے۔\n۱۱- جب امام خطبہ دینے کے لیے کھڑا ہوجائے تواس وقت کسی بھی طرح کا کام کرنا غلط ہے۔اس لیے ایسے وقت میں خریدوفروخت جائزنہیں ہے۔\n۱۲- جمعے کی نماز کے بعد شریعت کے مطابق کام اور خریدو فروخت وغیرہ کی جاسکتی ہے۔\nجمعہ حقیقت میں مسلمانوں کے لیے ہفتے کی عید ہے۔ اس لیے اس دن اچھےے کپڑے پہننا، غسل کرنا،اچھا کھانا کھانا،ایک دوسرے سے ملنا جلنا، بچوں کو گھمانا پھرانا یہ سب صحیح کام ہیں۔لیکن اسلامی تعلیمات کے خلاف کوئی کام کرنا صحیح نہیں۔ جیسے: فلم دیکھنا، مسلم عورتوں کا بناؤ سنگار کرکےبے پردہ باہر نکلنا وغیرہ۔","",{}],[202,"§جمل\nدیکھیے: ابل","",{}],[203,"§جمیل\nدیکھیے: اسماے حسنی","",{}],[204,"§جن\nاللہ تعالیٰ نے دو طرح کی پوشیدہ اور نہ نظر آنے والی مخلوق بنائی ہے۔ وہ ہیں:فرشتے اور جن۔ ایسی پوشیدہ مخلوق جو نیکی اور اچھائی کی مثال ہوتی ہیں، انھیں فرشتہ کہتے ہیں۔ (تفصیل کے لیےدیکھیں: لفظ فرشتہ)\nجن ایسی پوشیدہ مخلوق ہے،جس میں نیک وبددونوں قسم کے افراد ہوتے ہیں۔ عربی زبان میں لفظ ’جن ‘کےمعنی چھپنے اور پوشیدہ ہونے کےہیں۔\nاسی سےایک لفظ جنین ہے۔ ماں کے رحم میں چھپا بچہ جنین کہلاتاہے۔ اسی لفظ سے جنت بھی ہے، جس کےمعنی ایسے گھنے باغ کے ہیں، جو دنیا کو چھپالے۔\n’جن‘کے بارے میں جتنا تفصیلی بیان قرآن مجیدمیں آیا ہے اتنا کسی اور مذہبی کتاب میں نہیں ملتا۔شاید اس کی وجہ یہ ہوسکتی ہے کہ دوسرے مذاہب میں جنات کو کسی طرح کا کوئی حکم نہیں تھا۔ اس لیےان کے بارے میں مذہبی کتابوں میں کچھ زیادہ باتیں نہیں بتائی گئیں،لیکن محمد صلی اللہ علیہ وسلم انسانوں اور جنوں دونوں کے لیےنبی بناکر بھیجے گئے تھے۔ اس لیے ان کا تفصیلی ذکرہوا۔ یہاں قرآن مجید سے ماخوذ جن کے بارے میں کچھ خاص باتیں بیان کی جارہی ہیں۔ پہلے ان باتوں کا ذکر کیا جارہا ہے، جو انسانوں اور جنوں کے درمیان فرق کو ظاہر کرتی ہیں:\n۱-جن کو آگ سے پیدا کیا گیا،جب کہ انسانوں کو مٹی سے۔ قرآن مجیدمیں ہے: ﴿وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ مِن صَلۡصَٰلࣲ مِّنۡ حَمَإࣲ مَّسۡنُونࣲ وَٱلۡجَآنَّ خَلَقۡنَٰهُ مِن قَبۡلُ مِن نَّارِ ٱلسَّمُومِ﴾ [الحجر: ۲۶-۲۷] \"ہم نے انسانوں کو سڑی ہوئی مٹی کے سوکھے کھنکھناتے ہوئے ٹھیکرے سے بنایا اور جن کو اس سے قبل لو والی آگ کی لپٹ سے پیدا کیا\"۔\nاورفرمایا: ﴿خَلَقَ ٱلۡإِنسَٰنَ مِن صَلۡصَٰلࣲ كَٱلۡفَخَّارِ وَخَلَقَ ٱلۡجَآنَّ مِن مَّارِجࣲ مِّن نَّارࣲ‏﴾ [الرحمن: ۱۴-۱۵] \"انسان کو (ٹھیکرے)جیسی کھنکھناتی مٹی سے پیدا کیا اور’جن‘کو آگ کے شعلے سے پیدا کیا\"۔\nاسی وجہ سے ابلیس نے آدم کو سجدہ کرنے سے انکار کردیا کہا: ﴿قَالَ لَمۡ أَكُن لِّأَسۡجُدَ لِبَشَرٍ خَلَقۡتَهُۥ مِن صَلۡصَٰلࣲ مِّنۡ حَمَإࣲ مَّسۡنُونࣲ‏﴾ [الحجر: ۳۳] \"مجھ سےیہ نہیں ہوسکتا کہ میں اس انسان کو سجدہ کروں جس کو تو نے سڑی ہوئی مٹی اور سوکھے ہوئے گارے سے بنایا\"۔\nاس آیت سے یہ بھی معلوم ہوتا ہے کہ اس دنیا میں انسانوں سے پہلے جن آباد تھے۔پھر اللہ تعالیٰ نے انسانوں کو پیدا کیا۔\n۲-جنوں کو ایک خاص طرح کی طاقت دی گئی ہے جو انسانوں کو نہیں دی گئی۔ قرآن مجیدمیں ایک قوی ہیکل جن (عفریت) کا ذکر ہوا ہے، جس نےسلیمان علیہ السلام سے کہا کہ میں ملکہ سبا کا تخت آپ کے اپنی جگہ سےاٹھنے سے پہلے لاسکتا ہوں۔میں اس کام کےلیے طاقت ور اور بھروسا مند ہوں۔ (النمل:۳۹)\nسباجس کا دار السلطنت مآرب تھا موجودہ یمن کے دارالسلطنت صنعا سے پچپن میل دور شمال مشرق میں واقع ایک ملک تھا اور سلیمان علیہ السلام بیت المقدس (فلسطین)کےبادشاہ تھے۔ دونوں کے درمیان دوہزار میل سےبھی زیادہ کا فاصلہ ہے۔لیکن سلیمان علیہ السلام کے پاس ایک دوسرا جن بھی تھا جو \"عفریت\" سے بھی زیادہ طاقت ور تھا۔ اس نے کہا: ﴿قَالَ ٱلَّذِي عِندَهُۥ عِلۡمࣱ مِّنَ ٱلۡكِتَٰبِ أَنَا۠ ءَاتِيكَ بِهِۦ قَبۡلَ أَن يَرۡتَدَّ إِلَيۡكَ طَرۡفُكَۚ فَلَمَّا رَءَاهُ مُسۡتَقِرًّا عِندَهُۥ قَالَ هَٰذَا مِن فَضۡلِ رَبِّي لِيَبۡلُوَنِيٓ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ وَمَن شَكَرَ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيࣱّ كَرِيمࣱ‏﴾ [النمل: ۴۰] \"میں آپ کی پلک جھپکنے سے پہلے اسے لادوں گا۔پھر جب اس (سلیمان) نے اسے اپنے پاس رکھا ہوا دیکھاتو پکار اٹھا۔یہ میرے رب کی مہر بانی ہے۔ تاکہ وہ میرا متحان لے کہ میں شکرگزاری دکھا تاہوں یا کفر کرتا ہوں اور جس نے شکر گزاری کی تو اس نے خود اپنے فائدے کے لیے شکر گزاری کی، اور جس نے ناشکری کی تو میرارب غنی وکریم (بے نیاز اور کرم اورسخاوت والا)ہے\"۔\n۳-انسان فضامیں کسی سہارے کے بغیر چل پھرنہیں سکتا۔جب کہ جن فضامیں کسی سہارے کے بغیر گھوم پھر سکتے ہیں اور وہاں سے کچھ باتیں بھی اچک لیتے ہیں۔ ان میں اپنی طرف سے کچھ بڑھا کر لوگوں کو بتادیتے ہیں۔لیکن ملأ اعلیٰ، جو سب سے اعلیٰ دربار ہے،وہاں تک نہیں پہنچ سکتے۔ کیونکہ اس کے قریب پہنچتے ہی ہر طرف سے ان پر شعلوں کی بارش کر دی جاتی ہے۔ قرآن مجید میں ہے: ﴿لَّا يَسَّمَّعُونَ إِلَى ٱلۡمَلَإِ ٱلۡأَعۡلَىٰ وَيُقۡذَفُونَ مِن كُلِّ جَانِبࣲ دُحُورࣰ اۖ وَلَهُمۡ عَذَابࣱ وَاصِبٌ إِلَّا مَنۡ خَطِفَ ٱلۡخَطۡفَةَ فَأَتۡبَعَهُۥ شِهَابࣱ ثَاقِبࣱ‏﴾ [الصافات: ۸-۱۰] \"عالم بالا کے فرشتوں (کی باتوں) کو سننے کے لیے وہ کان بھی نہیں لگا سکتے، بل کہ ہر طرف سے وہ مارے جاتے ہیں۔بھگانے کے لیےاور ان کے لیے دائمی عذاب ہے۔مگر جو کوئی ایک آدھ بات اچک لے بھاگے تو(فورا ہی) اس کے پیچھے دہکتا ہوا شعلہ لگ جاتا ہے\"۔\n۴-\"انسان کو اللہ تعالیٰ نے ایک ہی شکل میں رہنے پر مجبور کیا ہے جب کہ جنوں کو اللہ نے یہ اختیار دیا ہے کہ وہ مختلف شکلوں میں انسان کے سامنے ظاہر ہوسکتےہیں اور بہت تیزی کے ساتھ مختلف جگہوں پر پہنچ سکتے ہیں\"۔ اس لیےنبی اکرم صلی اللہ علیہ وسلم نے ہمیں یہ تعلیم دی ہے کہ اگر ہم رات میں کہیں ٹھہریں تو یہ دعا پڑھلیں: «ٲعُوذُ بِکَلِمَاتِ اللهِ التَّامَّةِ مِنْ شَرِّ مَا خَلَقَ» (صحیح مسلم: ۲۷۰۸) \"میں اللہ کے مکمل کلمات کے ذریعے سے مخلوق کے نقصان پہنچانے سے پناہ مانگتا ہوں \"۔\nاس دعا کے پڑھنے کی وجہ سے اگر وہاں جن آباد ہیں تو وہ ہمیں نقصان نہیں پہنچا سکیں گے۔\n۵- انسانوں میں صرف سلیمان علیہ السلام کو ہی جنوں پر حکومت کا حق دیا گیا تھا: ﴿وَحُشِرَ لِسُلَيۡمَٰنَ جُنُودُهُۥ مِنَ ٱلۡجِنِّ وَٱلۡإِنسِ وَٱلطَّيۡرِ فَهُمۡ يُوزَعُونَ﴾ [النمل: ۱۷] \"سلیمان علیہ السلام کے لیے ان کی افواج جمع کی گئیں، جن میں جن بھی تھے اور انسان بھی اور پرندے بھی اور ہرقسم کی درجے بندی کردی گئی تھی\"۔\nسلیمان علیہ السلام نے اللہ سے صرف یہ دعا کی تھی: ﴿قَالَ رَبِّ ٱغۡفِرۡ لِي وَهَبۡ لِي مُلۡكࣰ ا لَّا يَنۢبَغِي لِأَحَدࣲ مِّنۢ بَعۡدِيٓۖ إِنَّكَ أَنتَ ٱلۡوَهَّابُ﴾ [ص: ۳۵] \"میرے رب! مجھے معاف کر دےاور مجھے وہ حکومت عطا کر جو میرے بعد کسی کے لیے مناسب نہ ہو۔ بے شک تو ہی سب سے بڑا دینے والا ہے\"۔\nابوہریرہ رضی اللہ عنہ سے مروی حدیث میں نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «إِنَّ عِفْرِيتًا مِنَ الْجِنِّ تَفَلَّتَ عَلَیَّ الْبَارِحَةَ لِيَقْطَعَ عَلَیَّ الصَّلاَةَ، فَأَمْکَنَنِی اللَّهُ مِنْهُ، فَأَرَدْتُ أَنْ أَرْبِطَهُ إِلَی سَارِيَةٍ مِنْ سَوَارِی الْمَسْجِدِ، حَتَّی تُصْبِحُوا وَتَنْظُرُوا إِلَيْهِ کُلُّکُمْ، فَذَکَرْتُ قَوْلَ أَخِی سُلَيْمَانَ رَبِّ هَبْ لِی مُلْکًا لاَ يَنْبَغِی لأَحَدٍ مِنْ بَعْدِی». (صحیح البخاری: ۴۶۱، صحیح مسلم: ۵۴) \"میں رات میں صلاۃِ تہجد پڑھ رہا تھا کہ ایک بڑا ہی طاقت ورعفریت جن میری نماز خراب کرنے کی جرأت کرنے لگا۔ لیکن اللہ تعالیٰ نے مجھے اس پر فتح دلائی۔ میں نے چاہا کہ اس کو مسجد کے ستون سے باندھ دوں تاکہ تم لوگ صبح ہونے پر اسے دیکھو،لیکن مجھے اپنے بھائی سلیمان علیہ السلام کی یہ بات یاد آگئی کہ اے اللہ مجھے ایسی حکومت عطا کرجو میرے بعد کسی کے لیے مناسب نہ ہو،تو میں نے اس ذلیل کوچھےوڑ دیا\"۔\nیہاں ایسی حکومت سے مراد ایسا ملک ہے، جس میں انسانوں کی طرح جنوں کی بھی فوج ہو اور وہ بھی انسانوں کی طرح کام کریں۔ قران مجیدمیں آیا ہے: ﴿يَعۡمَلُونَ لَهُۥ مَا يَشَآءُ مِن مَّحَٰرِيبَ وَتَمَٰثِيلَ وَجِفَانࣲ كَٱلۡجَوَابِ وَقُدُورࣲ رَّاسِيَٰتٍۚ ٱعۡمَلُوٓاْ ءَالَ دَاوُۥدَ شُكۡرࣰ اۚ وَقَلِيلࣱ مِّنۡ عِبَادِيَ ٱلشَّكُورُ﴾ [سبأ: ۱۳] \"سلیمان جو کچھ چاہتے وہ (جن) ان کے لیے تیار کردیتے۔جیسے بلند عبادت گاہیں، مجسمے اور پانی کے بڑے حوض جیسے تھال اور دیگیں جو ایک ہی جگہ پر جمی رہتی تھیں۔ اے آل داود! اس کے شکریے میں نیک عمل کرو، میرے بندوں میں سے شکر گزار بندے کم ہی ہوتے ہیں\"۔\nلیکن ایک دوسرا قول یہ بھی ہے کہ جس علاقے میں جو بھی نبی آتے تھے اس علاقے کے جن ان کی پیروی کرتے تھے تبھی تو وہ تورات سے باخبر تھے جیسا کہ سورہ الاحقاف کی آیت ۳۰ میں آیا ہے۔\n(۶) جن کے کاموں میں سے یہ کام بھی ہے کہ وہ لوگوں کے دلوں میں وسوسہ ڈالتے ہیں جیسا کہ قرآن کی سورہ الناس میں ہمیں یہ سبق دیا گیا ہے کہ ہم جنات کے وسوسے سے اللہ کی پناہ مانگیں۔\nاب ان باتوں کی طرف اشارہ کیا جاتا ہے۔ جو جن اور انسان دونوں میں یکساں طور پر پائی جاتی ہیں۔\n(۱) جنوں اور انسانوں کو اللہ تعالیٰ نے اپنی عبادت کے لیے پیدا کیا ہے۔(سورہ الذاریات: ۵۶) اس میں ان لوگوں کےاعتقاد کی تردید کی گئی ہے،جو جنات کو ہی اپنا معبودبنا بیٹھےتھے: ﴿وَيَوۡمَ يَحۡشُرُهُمۡ جَمِيعࣰ ا ثُمَّ يَقُولُ لِلۡمَلَٰٓئِكَةِ أَهَٰٓؤُلَآءِ إِيَّاكُمۡ كَانُواْ يَعۡبُدُونَ قَالُواْ سُبۡحَٰنَكَ أَنتَ وَلِيُّنَا مِن دُونِهِمۖ بَلۡ كَانُواْ يَعۡبُدُونَ ٱلۡجِنَّۖ أَكۡثَرُهُم بِهِم مُّؤۡمِنُونَ﴾ [سبأ: ۴۰-۴۱] \"جس دن وہ سب کو جمع کرے گا پھر فرشتوں سے کہے گا: کیا یہ لوگ تمھاری ہی عبادت کرتے تھے؟ وہ کہیں گے:تیری ذات پاک ہے! ہمارا تعلق تو تجھ سے ہے نہ کہ ان سے!بلکہ بات یہ ہے کہ وہ جنات کی عبادت کرتے تھے۔ ان میں سے زیادہ تر ان پر ایمان لائے ہوئے تھے\"۔اس لیے جہنم کو جہاں ایک طرف انسانوں سے بھرا جائے گا وہیں جنات سے بھی بھرا جائےگا۔(ہود: ۱۱۹، السجدہ: ۱۳)\n(۲) جنوں میں بھی انسانوں کی طرح فرماں بردار اور نافرمان پائے جاتے ہیں (الجن:۱۱)\n(۳) ان دونوں مخلوقات کو اللہ تعالیٰ نے کچھ اختیارات دےرکهے ہیں۔اس لیے اللہ تعالیٰ دونوں کو مخاطب کرتے ہوئے کہتا ہے: ﴿يَٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ إِنِ ٱسۡتَطَعۡتُمۡ أَن تَنفُذُواْ مِنۡ أَقۡطَارِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ فَٱنفُذُواْۚ لَا تَنفُذُونَ إِلَّا بِسُلۡطَٰنࣲ‏﴾ [الرحمن: ۳۳] \"اے انسانوں اور جنات کا گروہ! اگر تم میں طاقت ہے کہ آسمانوں اور زمین کی حدود کو پار کرسکو تو پار کرجاؤ: تم ہرگز پار نہیں کرسکتے غلبہ و طاقت کے بغیر\"۔\n(۴) جن بھی انسانوں کی طرح عورتوں سے جنسی تعلقات رکھتے ہیں: ﴿فِيهِنَّ قَٰصِرَٰتُ ٱلطَّرۡفِ لَمۡ يَطۡمِثۡهُنَّ إِنسࣱ قَبۡلَهُمۡ وَلَا جَآنࣱّ‏﴾ [الرحمن: ۵۶] \"ان (مہربانیوں) میں سےنگاہ نیچی رکھنے والی عورتیں بھی ہوں گی جنھیں ان سے پہلے نہ کسی انسان نے ہاتھ لگایا ہوگا نہ کسی جن نے\"۔\n(۵) انسانوں کی طرح جن کی طرف بھی رسول بھیجے گئے۔ارشاد باری تعالیٰ ہے : ﴿يَٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ أَلَمۡ يَأۡتِكُمۡ رُسُلࣱ مِّنكُمۡ يَقُصُّونَ عَلَيۡكُمۡ ءَايَٰتِي وَيُنذِرُونَكُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَاۚ قَالُواْ شَهِدۡنَا عَلَىٰٓ أَنفُسِنَاۖ وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَشَهِدُواْ عَلَىٰٓ أَنفُسِهِمۡ أَنَّهُمۡ كَانُواْ كَٰفِرِينَ﴾ [الأنعام: ۱۳۰] \"اے جنات اور انسانوں کے گروہ! کیا تمھارے پاس تم ہی میں سے رسول نہیں آئے تھے جو تمھیں میری آیات سناتے اور اس آج کے دن کےپیش آنے سے تمھیں ڈراتے تھے؟ وہ کہیں گے:کیوں نہیں! رسول آئے تھے ہم ہی خود اپنے خلاف گواہ ہیں۔ دنیوی زندگی نے اُنهیں دھوکے میں رکھا۔لیکن وہ اب خود اپنے خلاف گواہی دینے لگے کہ حقیقت میں وہ بددین تھے\"۔\n(۶) اب محمد صلی اللہ علیہ وسلم قیامت تک کے لیے ساری دنیا کے لیےنبی ورسول بناکر بھیجے گئے ہیں۔جس طرح سابق انبیاورسل کی تعلیمات منسوخ ہوگئیں، اسی طرح جنات کے نبیوں کی تعلیمات بھی منسوخ ہوگئیں۔اب جنوں کی کامیابی و کامرانی بھی اسی میں ہے کہ وہ انسانوں کی طرح محمد صلی اللہ علیہ وسلم کی نبوت کو قبول کریں۔\n(۷) انسانوں اور جنوں دونوں کو للکارا گیا کہ تم دونوں مل کر بھی قرآن مجیدجیسی کتاب نہیں لاسکتے۔(بنی اسرائیل: ۸۸)\nانسانوں کی طرح جن بھی غیب کا علم نہیں رکھتے، جب کہ یہ بات عام ہوگئی تھی اور آج بھی لوگ یقین رکھتے ہیں کہ جن غیب کا علم رکھتے ہیں۔ اس کی تردید قرآن مجیدنے یہ کہہ کرکردی ہے: ﴿فَلَمَّا قَضَيۡنَا عَلَيۡهِ ٱلۡمَوۡتَ مَا دَلَّهُمۡ عَلَىٰ مَوۡتِهِۦٓ إِلَّا دَآبَّةُ ٱلۡأَرۡضِ تَأۡكُلُ مِنسَأَتَهُۥۖ فَلَمَّا خَرَّ تَبَيَّنَتِ ٱلۡجِنُّ أَن لَّوۡ كَانُواْ يَعۡلَمُونَ ٱلۡغَيۡبَ مَا لَبِثُواْ فِي ٱلۡعَذَابِ ٱلۡمُهِينِ﴾ [سبأ: ۱۴] \"پھر جب ہم نے سلیمان کے لیے موت کا فیصلہ کردیا تو پھر ان جنات کو اس کی موت کا پتا بس زمین کے اس کیڑے نے دیا جو اس کی لاٹھی کو کھا رہا تھا۔پس جب سلیمان گر پڑے تو جنات نے کہا کہ اگر وہ غیب کا علم رکھتے تو اس ذلت والے عذاب میں نہ پھنسے رہتے\"۔\n§جنوں کا قرآن سننا:\nقرآن مجیدمیں جنوں کے قرآن سننے کا ذکر آیا ہے: ﴿قُلۡ أُوحِيَ إِلَيَّ أَنَّهُ ٱسۡتَمَعَ نَفَرࣱ مِّنَ ٱلۡجِنِّ فَقَالُوٓاْ إِنَّا سَمِعۡنَا قُرۡءَانًا عَجَبࣰ ا يَهۡدِيٓ إِلَى ٱلرُّشۡدِ فَـَٔامَنَّا بِهِۦۖ وَلَن نُّشۡرِكَ بِرَبِّنَآ أَحَدࣰ ا وَأَنَّهُۥ تَعَٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَٰحِبَةࣰ وَلَا وَلَدࣰ ا وَأَنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى ٱللَّهِ شَطَطࣰ ا وَأَنَّا ظَنَنَّآ أَن لَّن تَقُولَ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَى ٱللَّهِ كَذِبࣰ ا وَأَنَّهُۥ كَانَ رِجَالࣱ مِّنَ ٱلۡإِنسِ يَعُوذُونَ بِرِجَالࣲ مِّنَ ٱلۡجِنِّ فَزَادُوهُمۡ رَهَقࣰ ا وَأَنَّهُمۡ ظَنُّواْ كَمَا ظَنَنتُمۡ أَن لَّن يَبۡعَثَ ٱللَّهُ أَحَدࣰ ا وَأَنَّا لَمَسۡنَا ٱلسَّمَآءَ فَوَجَدۡنَٰهَا مُلِئَتۡ حَرَسࣰ ا شَدِيدࣰ ا وَشُهُبࣰ ا وَأَنَّا كُنَّا نَقۡعُدُ مِنۡهَا مَقَٰعِدَ لِلسَّمۡعِۖ فَمَن يَسۡتَمِعِ ٱلۡأٓنَ يَجِدۡ لَهُۥ شِهَابࣰ ا رَّصَدࣰ ا وَأَنَّا لَا نَدۡرِيٓ أَشَرٌّ أُرِيدَ بِمَن فِي ٱلۡأَرۡضِ أَمۡ أَرَادَ بِهِمۡ رَبُّهُمۡ رَشَدࣰ ا وَأَنَّا مِنَّا ٱلصَّٰلِحُونَ وَمِنَّا دُونَ ذَٰلِكَۖ كُنَّا طَرَآئِقَ قِدَدࣰ ا وَأَنَّا ظَنَنَّآ أَن لَّن نُّعۡجِزَ ٱللَّهَ فِي ٱلۡأَرۡضِ وَلَن نُّعۡجِزَهُۥ هَرَبࣰ ا وَأَنَّا لَمَّا سَمِعۡنَا ٱلۡهُدَىٰٓ ءَامَنَّا بِهِۦۖ فَمَن يُؤۡمِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخۡسࣰ ا وَلَا رَهَقࣰ ا وَأَنَّا مِنَّا ٱلۡمُسۡلِمُونَ وَمِنَّا ٱلۡقَٰسِطُونَۖ فَمَنۡ أَسۡلَمَ فَأُوْلَٰٓئِكَ تَحَرَّوۡاْ رَشَدࣰ ا وَأَمَّا ٱلۡقَٰسِطُونَ فَكَانُواْ لِجَهَنَّمَ حَطَبࣰ ا﴾ [الجن: ۱-۱۵] \"(اے محمد!لوگوں سے ) کَہ دیجیےمیری طرف وحی آئی ہے کہ جنات کے ایک گروہ نے (اس کتاب کو) سنا، تو انھوں نے کہا: ہم نے ایک عجیب قرآن سنا وہ سیدھی راہ دکھاتا ہے، تو ہم اس پر ایمان لے آئے اور ہم ہر گز کسی کو اپنے رب کا شریک نہ ٹھہرائیں گے اوریہ کہ ہمارے رب کی شان بہت اعلیٰ ہے۔اس نے نہ تو کسی کو اپنی بیوی بنایا اور نہ کسی کواپنی اولاد اور یہ کہ ہم میں سے کچھ بیوقوف اللہ کےتعلق سے بہت دور کی باتیں کہتے رہے ہیں اور یہ کہ ہم نےسمجھ رکھا تھاکہ انسان اور جن اللہ کے بارے میں ہرگز جھوٹی باتیں نہیں کہیں گےاور یہ کہ انسانوں میں سے کتنے ہی ایسے لوگ رہے ہیں جو جنات میں سے کتنی ہی لوگوں کی پناہ لیتے تھے تو انھوں نے انھیں سرکشی میں اور بڑھا دیا اور یہ کہ انھوں نے یہ سمجھ لیا تھا جیسے تم نے سمجھ لیا تھا کہ کسی نبی کو ہر گز نہیں بھیجے گا اور یہ کہ ہم نے آسمان کو ٹٹولا تو پایا کہ اسے سخت نگہبان اور آگ کے شعلوں سے بھر دیا گیا ہے اور یہ کہ ہم اس کے بیٹھنے کی جگہوں میں سننے کے لیے بیٹھا کرتےتھے۔لیکن اب کوئی سننے جائے تو وہ اپنے لیے ایک آگ کا شعلہ گھات میں لگا پائے گا۔ہم نہیں جانتےکہ ان لوگوں کے ساتھ جو دنیا میں ہیں برائی کا ارادہ کیا گیا ہے یا ان کے رب نے ان کے لیے بھلائی اور ان کی رہنمائی کا ارادہ کیا ہے اور یہ کہ ہم میں کچھ نیک لوگ ہیں اور ہم ہی میں دوسری طرح کے بھی، ہم الگ الگ راہوں پر تھے اور یہ کہ ہم نے سمجھ لیا کہ ہم نہ دنیا میں کہیں اللہ کے اختیارسے بھاگ سکتے ہیں اور نہ آسمان میں کہیں اس کے اختیارسے بھاگ سکتے ہیں اور یہ کہ ہم نے جب ہدایت کی بات سن لی تو اسے قبول کر لیا۔ اب جو کوئی اپنے رب پر ایمان لائے گا، اسے نہ تو کسی حق کے مارے جانے کا خوف ہوگا اور نہ کسی ظلم کا، اور یہ کہ ہم میں سے کچھ تو مسلم (فرماں بردار) ہیں اورہم میں سے کچھ راہ سے پھرے ہوے ہیں،تو جو مسلم ہوےانهوں نے تو کامیابی اورعقل مندی کی راہ اختیار کرلی۔ بچے وہ لوگ جو راہ سے پھرے ہوے ہیں تو وہ جہنم کا ایندھن ہوے\"۔\nآیت نمبر: ۸،۹، اور۱۰ سے ظاہر ہوتا ہے کہ جنوں کے ذریعے سےقرآن سننے کا واقعہ محمد صلی اللہ علیہ وسلم کے نبی ہونے کے ابتدائی وقت میں ہوا ہوگا۔ کیونکہ جب اللہ کی طرف سے وحی آنے لگی تو آسمان میں فرشتوں کو متعین کر دیا گیا۔ تاکہ کوئی جن یا شیطان وحی اُچک نہ لے اور پھر اس میں نقص و اضافہ نہ کردے۔\nاسی کی طرف آياتِ منقول میں اشارہ کیا گیا ہے: عبداللہ بن عباس رضی اللہ عنہما سےیہ حديث آئی ہے: «انْطَلَقَ رَسُولُ اللَّهِ صلی اللہ علیہ وسلم فِی طَائِفَةٍ مِنْ أَصْحَابِهِ عَامِدِينَ إِلَی سُوقِ عُکَاظٍ، وَقَدْ حِيلَ بَيْنَ الشَّيَاطِينِ وَبَيْنَ خَبَرِ السَّمَاءِ، وَأُرْسِلَتْ عَلَيْهِمُ الشُّهُبُ، فَرَجَعَتِ الشَّيَاطِينُ فَقَالُوا: مَا لَکُمْ؟ فَقَالُوا: حِيلَ بَيْنَنَا وَبَيْنَ خَبَرِ السَّمَاءِ وَأُرْسِلَتْ عَلَيْنَا الشُّهُبُ. قَالَ: مَاحَالَ بَيْنَکُمْ وَبَيْنَ خَبَرِ السَّمَاءِ إِلاَّ مَا حَدَثَ، فَاضْرِبُوا مَشَارِقَ الأَرْضِ وَمَغَارِبَهَا فَانْظُرُوا مَا هَذَا الأَمْرُ الَّذِی حَدَثَ؟ فَانْطَلَقُوا فَضَرَبُوا مَشَارِقَ الأَرْضِ وَمَغَارِبَهَا يَنْظُرُونَ مَا هَذَا الأَمْرُ الَّذِی حَالَ بَيْنَهُمْ وَبَيْنَ خَبَرِ السَّمَاءِ. قَالَ: فَانْطَلَقَ الَّذِينَ تَوَجَّهُوا نَحْوَ تهامَةَ إِلَی رَسُولِ اللَّهِ رضی اللہ عنہ بِنَخْلَةَ، وَهْوَ عَامِدٌ إِلَی سُوقِ عُکَاظٍ، وَهْوَ يُصَلِّی بِأَصْحَابِهِ صَلاَةَ الْفَجْرِ، فَلَمَّا سَمِعُوا الْقُرْآنَ تَسَمَّعُوا لَهُ فَقَالُوا: هَذَا الَّذِی حَالَ بَيْنَکُمْ وَبَيْنَ خَبَرِ السَّمَاءِ. فَهُنَالِکَ رَجَعُوا إِلَی قَوْمِهِمْ، فَقَالُوا: يَا قَوْمَنَا إِنَّا سَمِعْنَا قُرْآنًا عَجَبًا يَهْدِی إِلَی الرُّشْدِ فَآمَنَّا بِهِ، وَلَنْ نُشْرِکَ بِرَبِّنَا أَحَدًا. وَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ عَلَی نبيهِ﴿قُلۡ أُوحِيَ إِلَيَّ أَنَّهُ ٱسۡتَمَعَ نَفَرࣱ مِّنَ ٱلۡجِنِّ فَقَالُوٓاْ إِنَّا سَمِعۡنَا قُرۡءَانًا عَجَبࣰ ا﴾ [الجن: ۱] وَإِنَّمَا أُوحِیَ إِلَيْهِ قَوْلُ الْجِنِّ». (صحیح البخاری: ۴۹۲۱، صحیح مسلم: ۸۸۲) \" رسول اللہ صلی اللہ علیہ وسلم اپنے چند صحابہ کے ساتھ بازارِ عکاظ کی طرف چلے۔اس وقت شیطانوں کو آسمان پر جاکرخبریں لانے سے روک دیا گیا تھا اور آسمان پر جانے پر آگ کے شعلوں سے ان کو مارا جانے لگا تھا، انھوں نے آپس میں کہا: ایسا اس لیے ہوا ہے کہ کچھ معاملہ ہوا ہے،جاؤ مشرق ومغرب میں گھوم پھر کر دیکھو، تو کچھ ان میں سے نکلے گا تاکہ پتا لگائیں، تو ان کی وہ جماعت جو تہامہ کی طرف گئی تھی وہ گھومتے گھومتے ’نخلہ‘نامی جگہ پر پہنچی، جہاں نبی اکرم صلی اللہ علیہ وسلم صحابہ کرام کے ساتھ فجرکی نماز ادا کر رہے تھے،جب انھوں نے قرآن سنا تو پکار اٹھے کہ یہی وہ چیز ہے جس کی وجہ سے ہمارے اور آسمان کی خبر کے درمیان رکاوٹ کھڑی کردی گئی ہے۔ پھر وہ اپنے ساتھیوں کو بتانے چلے گئے کہ ہم نے ایک عجیب قرآن سنا ہے۔ اس وقت سورہ جن نازل ہوئی\"۔\nحافظ ابن حجر نے اپنی مشہور کتاب بخاری شریف کی شرح فتح الباری میں لکھا ہے کہ یہ واقعہ محمد صلی اللہ علیہ وسلم کے نبی ہونے کے ابتدائی دور کا ہے۔\nجنوں کے قرآن سننے کے دوسرے واقعے کا ذکر قرآن کی سورہ احقاف میں آیا ہے: ﴿وَإِذۡ صَرَفۡنَآ إِلَيۡكَ نَفَرࣰ ا مِّنَ ٱلۡجِنِّ يَسۡتَمِعُونَ ٱلۡقُرۡءَانَ فَلَمَّا حَضَرُوهُ قَالُوٓاْ أَنصِتُواْۖ فَلَمَّا قُضِيَ وَلَّوۡاْ إِلَىٰ قَوۡمِهِم مُّنذِرِينَ قَالُواْ يَٰقَوۡمَنَآ إِنَّا سَمِعۡنَا كِتَٰبًا أُنزِلَ مِنۢ بَعۡدِ مُوسَىٰ مُصَدِّقࣰ ا لِّمَا بَيۡنَ يَدَيۡهِ يَهۡدِيٓ إِلَى ٱلۡحَقِّ وَإِلَىٰ طَرِيقࣲ مُّسۡتَقِيمࣲ يَٰقَوۡمَنَآ أَجِيبُواْ دَاعِيَ ٱللَّهِ وَءَامِنُواْ بِهِۦ يَغۡفِرۡ لَكُم مِّن ذُنُوبِكُمۡ وَيُجِرۡكُم مِّنۡ عَذَابٍ أَلِيمࣲ وَمَن لَّا يُجِبۡ دَاعِيَ ٱللَّهِ فَلَيۡسَ بِمُعۡجِزࣲ فِي ٱلۡأَرۡضِ وَلَيۡسَ لَهُۥ مِن دُونِهِۦٓ أَوۡلِيَآءُۚ أُوْلَٰٓئِكَ فِي ضَلَٰلࣲ مُّبِينٍ﴾ [الأحقاف: ۲۹-۳۲] \"اوریاد کرو (اے نبی) جب کہ ہم نے کچھ جنوں کی توجہ تمھاری طرف کردی کہ وہ قرآن سن لیں، تو جب وہ وہاں پہنچے تو کہنے لگے: چپ ہوجاؤ! پھر جب وہ (قرآن کا سبق) پورا ہوگیا تو وہ اپنی قوم کی طرف خبردار بن کر لوٹے، انھوں نے کہا: اے ہماری قوم!ہم نے ایک کتاب سنی ہے جو موسی کے بعد اتری ہے۔اس کی تصدیق کرتی ہے، جو اس سے پہلے سے موجود ہے۔حق کی طرف اور سیدھی راہ کی طرف لے جاتی ہے۔ اے ہماری قوم! اللہ کے داعی کی دعوت قبول کرو اور اس پر ایمان لاؤ وہ (اللہ) تمھارے گناہوں کو معاف کردے گا اورتمھیں تکلیف دہ عذاب سے بچالےگا اور جوکوئی اللہ کے داعی کی دعوت قبول نہیں کرےگا تو وہ زمین پر اللہ سے بچ کر کہیں نہیں جاسکتا اور نہ اس کے سوا کوئی اس کا مددگار (ولی) ہوگا یہی وہ لوگ ہیں جو کھلی گمراہی میں ہیں\"۔\nان آیات سے معلوم ہوتا ہے کہ جن پہلے سے موسی علیہ السلام پر ایمان رکھتے تھے۔اس لیے جب انھوں نے قرآن کو سنا تو پکار اٹھے کہ یہ تو وہی پیغام ہے، جو موسی اور عیسی علیہما السلام لے کر آئے تھے۔\nاحادیث سے معلوم ہوتا ہے کہ یہ واقعہ اس وقت ہوا جب نبی اکرم صلی اللہ علیہ وسلم طائف سےواپس آرہے تھےاور آپ کےنبی ہونے کا دسواں سال تھا۔ طائف والوں نے آپ کو بہت تکلیف پہنچائی،جس کےسبب آپ بہت غمگین تھے۔ اس واقعے نے آپ کو یقین دلایا کہ انسان تو انسان جن بھی آپ پر ایمان لارہے ہیں۔\nعبداللہ بن عباس رضی اللہ عنہما کا خیال ہےکہ ان کی تعداد سات تھی۔ جو ترکی کے شہر ’نصیبین‘سے آئے تھے (دیکھیے: تفسیر ابن کثیر:۷: ۲۷۲)\nیہ واقعہ بھی وادیٔ نخلہ میں واقع ہوا۔ کیونکہ وہ ایک ایسی جگہ ہے، جہاں پانی ہے،جس کی وجہ سے وہاں ٹھہرناآسان ہوتا ہے۔ان دو واقعات کےعلاوہ بھی بہت سے واقعات پیش آئے ہیں، جب جن نبی اکرم صلی اللہ علیہ وسلم کے پاس قرآن سننے آیا کرتے تھے اورکبھی کبھی آپ خود ان کے پا س چلے جایا کرتے تھے۔ صحیح روایات سےپتا چلتا ہے کہ اس طرح کے کوئی سات واقعات پیش آئے ہیں۔(مزید معلومات کے لیے مؤلف کی کتاب الجامع الکامل دیکھیں)","",{}]]);
